// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":75,"question":"علي قضاء ثلاثة شهور من رمضان بسبب أنني كنت في نفاس، وشهر كنت مريضة، ثم قضيتها متأخرة من دون كفارة، فما رأي فضيلتكم؟","title":"حكم تأخير قضاء رمضان للنفاس والمرض","answer":"الجواب: إذا كان لعذر ما في كفارة، إذا كان لعذر شرعي كالمرض، والولادة، والحمل الذي يمنع فلا بأس، وإن كان لغير عذر لا بدّ من إطعام عن كل يوم نصف صاع؛ كيلو ونصف عن كل يوم، إذا كان من غير عذر؛ تساهل، تأخر بعد رمضان عن تساهل.","link":"https://binbaz.org.sa/fatwas/3039/حكم-تاخير-قضاء-رمضان-للنفاس-والمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0052.mp3","categories":["قضاء الصيام"]},{"id":418,"question":"امرأة أنجبت مولودًا في شهر رمضان قبل عشرين سنة، ولم تقضه حتى الآن، فما العمل؟ علمًا بأنها أفطرت الشهر جميعه؛ لأنها نُفساء، وهي جاهلة.","title":"حكم من أفطرت برمضان منذ سنين ولم تقض","answer":"الجواب: عليها التوبة إلى الله؛ لأنها قصرت في عدم السؤال، وهذا أمرٌ معلومٌ بين المسلمين، ليس بمجهولٍ -صيام رمضان- فالواجب عليها التوبة إلى الله، والندم، وصوم هذه الأيام، صوم الشهر الذي أفطرته، تصومه وتُطعم عن كل يومٍ مسكينًا إذا كانت تستطيع، فإن كانت فقيرةً عاجزةً تصوم وليس عليها شيء، وإن كانت تستطيع تصوم وتُطعم عن كل يوم نصفَ صاعٍ من التمر أو الرز، عن جميع الأيام، يُعطاها بعض الفقراء.","link":"https://binbaz.org.sa/fatwas/4842/حكم-من-افطرت-برمضان-منذ-سنين-ولم-تقض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0476.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","الرقائق"]},{"id":658,"question":"رجل عليه قضاء صيام من رمضان وعشرة أيام من الحج، فأيهما يُقَدِّم؟","title":"أيهما يُقَدِّم من قضاء رمضان وصوم الفِدية؟","answer":"الجواب: يُقَدِّم رمضان قبل الحج.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6689/ايهما-يقدم-من-قضاء-رمضان-وصوم-الفدية","audio":"https://files.zadapps.info/binbaz.org.sa/maram227 - 01 -  Start.mp3","categories":["قضاء الصيام"]},{"id":1001,"question":"إذا كنتُ مُسافرًا وحضرت صلاةُ العصر في جماعةٍ، ولم أُصلِّ الظهرَ، فهل أُصلي العصر ثم أُصلي الظهر بعدها، أم أُصلي العصر بنية الظهر؟ أم ماذا أفعل؟","title":"حكم من لم يُصَلِّ الظهر وحضرته العصر","answer":"الجواب: إذا حضر الإنسانُ جماعةً سيُصلون العصرَ في الحضر أو في السفر وهو ما صلَّى الظهر، فإنه يُصلي معهم بنية الظهر؛ من أجل الترتيب، ثم يُصلي العصر بعد ذلك، ولا حرج في ذلك؛ لأنَّ النية لا تُؤثر في هذا، فيُصلي معهم الظهر، ثم إذا سلَّموا صلَّى العصر بعد ذلك في المسجد، أو في بيته، وإن تيسرت جماعةٌ يُصلي معهم العصر صلَّى معهم العصر.\nوهكذا لو جاء وهم يُصلون العشاء، وهو ما صلَّى المغرب، يدخل معهم فيُصلي معهم المغرب بنية المغرب، ويجلس في الثالثة ينتظر، فإذا سلَّم الإمامُ سلَّم معهم، ثم بعد ذلك يُصلي العشاء في المسجد إن تيسر، أو في بيته، فيحصل الترتيبُ وفعل الجماعة، ويُصلي بعد ذلك الصلاة الحاضرة.","link":"https://binbaz.org.sa/fatwas/21054/حكم-من-لم-يصل-الظهر-وحضرته-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0850إذا كنت مسافراً وحضرت صلاة العصر في جماعة ولم أصلي الظهر فهل أصلي معهم العصر بية الظهر.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1013,"question":"إني أحبُّك في الله، والدي تُوفي وهو مريضٌ وكبيرٌ في السن أيضًا، ولم يستطع صيام رمضان، فهل أُطعم عنه أم لا؟","title":"حكم قضاء الصوم عن الميت الكبير المريض","answer":"الجواب: أما المحبَّة في الله فنقول: أحبَّك الله الذي أحببتنا له، والتَّحابُّ في الله من أفضل القُربات كما قال عليه الصلاة والسلام: ثلاثٌ مَن كنَّ فيه وجد حلاوةَ الإيمان: أن يكون الله ورسوله أحبَّ إليه مما سواهما، وأن يُحبّ المرء لا يُحبّه إلا لله .. الحديث، وقال عليه الصلاة والسلام: سبعةٌ يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله وذكر منهم رجلين تحابَّا في الله: اجتمعا عليه، وتفرَّقا عليه، وقال عليه الصلاة والسلام: يقول الله يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلهم في ظلِّي يوم لا ظلَّ إلا ظلِّي رواه مسلمٌ في \"صحيحه\"، وروى مالكٌ بإسنادٍ صحيحٍ عن النبي ﷺ أنه قال: يقول الله : وجبت محبَّتي للمُتحابين فيَّ، والمتزاورين فيَّ، والمتجالسين فيَّ، والمتباذلين فيَّ، نسأل الله أن يجعلنا وإيَّاكم منهم.\nأما والدك: فليس عليك شيءٌ ما دام مات مريضًا كبير السن عاجزًا، فليس عليك قضاء ولا إطعامٌ إذا كان لم يُدرك الصحة، بل مات في مرضه، أو في كبر سنِّه لا يستطيع معه الصوم، فليس عليك قضاء، ولكن إذا كان لكبر السن يُطعم عن كلِّ يومٍ مسكينًا في حياته، يطعم عنه عن كل يومٍ مسكينًا نصف صاع: تمرًا، أو أرزًا، أو بُرًّا، إذا كان عاجزًا ولكن عقله معه، فيطعم عنه مسكينًا عن كل يومٍ في جميع الأيام التي أفطرها من رمضان.\nأما المريض إذا مات في مرضه فليس عليه شيءٌ، وهكذا العاجز إذا تغيَّر شعوره، تغيَّر عقله، فلا شيء عليه، فإذا كان كبير السن أو المريض الذي تغيَّر شعوره كذلك لا شيء عليه؛ لأنه صار من غير المكلَّفين بسبب كبر السن أو المرض الذي غيَّر عقله، صار حكمُه حكمَ المعتوهين والمجانين، لا شيء عليه.","link":"https://binbaz.org.sa/fatwas/21063/حكم-قضاء-الصوم-عن-الميت-الكبير-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0859والدي توفي وهو مريض وكبير في السن وليم يستطع صيام رمضان فهل أطعم عنه أم لا؟ ابن باز.mp3","categories":["قضاء الصيام"]},{"id":1030,"question":"أفطرت في أحد السنين على قدري، أو في بعض سنين في الأيام التي تأتي فيها الدورة الشَّهرية، وكنتُ حينذاك صغيرةً، ولم أتمكن من الصيام، والآن أود أن أقضي ما عليَّ من دَين الصيام، ولكن لا أعرف كم عدد الأيام التي عليَّ، فماذا أفعل؟","title":"حكم من أفطرت جهلًا برمضان في صِغَرها","answer":"الجواب: الشيخ: عليك ثلاثة أمور:\nالأمر الأول: التَّوبة إلى الله عن هذا التَّأخير، والنَّدم على ما مضى، وكثرة الاستغفار، والعزم ألا تعودي لمثل هذا؛ لأنَّ الله يقول: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وهذه معصية، والتوبة منها واجب بالنَّدم على الماضي، والإقلاع من ذلك، وعدم العودة إليه.\nالأمر الثاني: البدار بالصوم على حسب الظن، لا يُكلِّف الله نفسًا إلا وسعها، الذي تظنين أنَّكِ تركتيه من الأيام تصومينه: إذا ظننتِ أنها عشرًا تصومين عشرة أيام، وإذا ظننتِ أنها خمسين يومًا تصومين خمسين يومًا، وإن كان أقلّ..... صومي ظنّك عند عدم الجزم، إذا كان ما عندك علمٌ فالظن يكفي.\nالأمر الثالث: إطعام مسكينٍ عن كل يومٍ إذا كنت تقدرين، إذا كان عندك مالٌ وقُدرة تُطعمين عن كل يومٍ مسكينًا من هذه الأيام المؤخَّرة، نصف صاع -كيلو وربع- عن كل واحدٍ، تجمعينها وتُعطينها بعض الفقراء.","link":"https://binbaz.org.sa/fatwas/21098/حكم-من-افطرت-جهلا-برمضان-في-صغرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0894فطرت في الأيام التي تأتيني الدورة وأنا صغيرة ولم أقضي والآن أريد أن أقضي ولا أعرف كم علي؟.mp3","categories":["الحيض والنفاس","قضاء الصيام","قضايا المرأة"]},{"id":1113,"question":"امرأةٌ أفطرت في رمضان بسبب النِّفاس، ومرت سنوات عديدة ولم تقضِ الأيام التي فاتتها جهلًا منها، ما الحكم في مثل هذه الحالة؟","title":"حكم مَن أفطرت في نفاسها ولم تقضِ جهلًا","answer":"الجواب:\nالتي عليها صيام من رمضان بسبب النِّفاس، أو الحيض، أو المرض، أو السفر، وتأخَّرت في الصيام؛ تصوم مع التوبة والنَّدم وإطعام مسكينٍ عن كل يومٍ إذا تأخَّر القضاءُ عن رمضان الذي يلي الشهر الذي تركت الصيام منه، إذا جاء رمضان الآخر وهي لم تصم؛ تصم بعد ذلك وعليها إطعام مسكينٍ عن كل يومٍ مع القدرة، إذا كانت تقدر، أما إنْ كانت فقيرةً لا تستطيع فيكفيها الصوم، تقضي الأيام، قال الله تعالى: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185].\nوهكذا الرجل: إذا تأخَّر الصوم الذي عليه بعدما صحَّ من مرضه، أو قدم من سفره، تساهل حتى جاء رمضان آخر، فإنه يقضي بعد ذلك، وعليه التوبة عن التَّقصير، وعليه إطعام مسكينٍ عن كل يومٍ أخَّره.\nفالرجل والمرأة في هذا سواء، إذا أخَّر إلى رمضان آخر وجب القضاء والتّوبة وإطعام مسكينٍ عن كل يومٍ، مع القُدرة، فإن لم يستطع الإطعام صام وكفاه الصيام.","link":"https://binbaz.org.sa/fatwas/21166/حكم-من-افطرت-في-نفاسها-ولم-تقض-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0962أمرأة أفطرت في رمضان بسبب النفاس مرَّت سنوات ولم تقضي الأيام التي فاتتها جهلاً منها فما الحكم.mp3","categories":["قضاء الصيام","الحيض والنفاس","قضايا المرأة"]},{"id":1145,"question":"لقد أفطرت عدة أيام في رمضان منذ سنوات، فهل يجب عليها قضاء تلك الأيام؟","title":"حكم مَن أفطرت أيامًا في رمضان منذ سنوات","answer":"الجواب:\nنعم، عليها أن تقضي، وعليها التوبة إلى الله، وعليها الصَّدقة مع ذلك، ثلاث أشياء: القضاء والتوبة والصدقة عن كلِّ يومٍ نصف صاعٍ؛ لأنها مُخطئة مُفرِّطة، إلا إذا كانت فقيرةً ما تستطيع فيكفي الصوم والتوبة، أما إن كانت تستطيع فعليها التوبة إلى الله والنَّدم والاستغفار على تفريطها وتساهُلها، وعليها أن تصوم بعدد الأيام، وعليها أن تُطعم عن كل يومٍ مسكينًا، نصف صاع من التمر أو غيره من قوت البلد، يُجمع ويُعطى بعض الفقراء، يُجمع الجميع ويُعطى بعض الفقراء، أو بعض البيوت الفقيرة، إذا كانت تستطيع، أما إذا كانت فقيرةً فليس عليها إطعامٌ، بل عليها الصيام فقط مع التوبة.","link":"https://binbaz.org.sa/fatwas/21187/حكم-من-افطرت-اياما-في-رمضان-منذ-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0983أمرأة أفطرت عدة أيام في رمضان منذ سنوات فهل يجب عليها القضاء تلك الأيام؟.mp3","categories":["قضاء الصيام"]},{"id":1232,"question":"إذا كان الإنسانُ نائمًا في الظهر ولم يستيقظ إلا بعد أذان المغرب، فصلَّى المغرب، فتذكَّر أنه لم يُصلِّ العصر: هل يُصليها أم لا؟","title":"حكم مَن صلى بعد نوم ثم تذكر فائتة قبلها","answer":"الجواب:\nنعم، إذا صلَّى المغرب ناسيًا للعصر، ثم ذكرها، يُصلي العصر، وصلاة المغرب مُجزئة، أما التَّعمد لا، لا يتعمَّد، يجب أن يبدأ بالعصر ثم بالمغرب، مثلما فعل النبيُّ ﷺ لما شُغل يوم الأحزاب في قتال الكفرة، شغلوه عن العصر، فصلَّاها بعد الغروب، ثم صلَّى المغرب بعدها، لكن لو نسي وصلَّى المغرب، ثم ذكر أنَّ عليه العصر أو غيرها، صلَّى الفائتة، وأجزأته التي صلَّاها لأجل النسيان: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، قال الله: قد فعلت.","link":"https://binbaz.org.sa/fatwas/21280/حكم-من-صلى-بعد-نوم-ثم-تذكر-فاىتة-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1023إذا كان الإنسان نائماً في الظهر ولم يستقظ إلا بعد أذان المغرب وتذكر أنه لم يصلي العصر هل يصليها؟.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1289,"question":"توفي والدي بسبب مرضٍ ألمَّ به، وقد كان يُعاني في أيامه الأخيرة من حالة غيبوبةٍ لفترات تطول أحيانًا، فأوصانا بأن نقوم بالصلاة عنه والصيام في الأيام التي لم يستطع الصلاةَ فيها ولا الصيام، فهل يلزمنا الصيام والصلاة عنه؟ أم ماذا يجب أن نفعل؟ علمًا بأنه قد مرَّ على وفاته حوالي ست سنوات؟","title":"هل يجوز الصلاة عن فاقد الوعي بعد موته؟","answer":"الجواب:\nليس عليكم صلاةٌ ولا صيامٌ، إذا كان مريضًا عجز عن الصيام فليس عليه قضاءٌ، وليس عليكم قضاءٌ أنتم؛ لأنه مات قبل أن يتمكن، فهو معذورٌ، وأنتم ليس عليكم شيءٌ؛ لأنه ما فرط، هو مات في مرضه.\nوأما الصلاة: فما يجوز له أن يُؤخِّر الصلاة، الواجب عليه أن يُصلي في الوقت، ولو على جنبه، ولو بالإيماء، ولو بالكلام والنية، النبي عليه السلام قال للمريض: صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنبٍ، فإن لم تستطع فمُستلقيًا، ما له عذرٌ إذا كان عقله معه، أما إذا كانت عنده غيبوبة وضاع عقله فما عليه شيءٌ، لكن إن كان عقله معه -يعقل الصلاة ويفهم- يُصلي على حسب حاله: القاعد يركع في الهواء، ثم يسجد في الأرض إن كان يستطيع، وإن كان ما يستطيع صلَّى على جنبه بالنية والكلام، يُكبر ويقرأ الفاتحة معها، ثم يُكبر ناويًا الركوع ويقول: سبحان ربي العظيم، ثم يقول: سمع الله، ناويًا الرفع من الركوع، ويقول: ربنا ولك الحمد، إلى آخره، ثم يُكبر ناويًا السّجود ويقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم يُكبر ناويًا الرفع من السجود ويقول: رب اغفر لي، رب اغفر لي، ثم يُكبر الثانية ناويًا السجود، وهكذا حتى يُكمل، وعلى جنبه، أو مُستلقيًا، لا يسقط عنه أداء الصلاة، على جميع الأحوال، ما دام عقله معه.\nأما إذا كانت عنده غيبوبة وضاع العقلُ، ما يضبط، فالله جلَّ وعلا لا يُكلِّف نفسًا إلا وسعها، ولا يُكلِّف غير العاقل، غير العاقل ما عليه شيءٌ، ما عليه تكاليف من حين تغيَّر العقلُ: لكبر سنٍّ، أو مرضٍ سقطت التَّكاليف.","link":"https://binbaz.org.sa/fatwas/21346/هل-يجوز-الصلاة-عن-فاقد-الوعي-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1089هل يجوز للمريض أن يوصي أحد أن يصلي عنه إذا لم يستطع ؟ ابن باز فتاوى.mp3","categories":["قضاء الصيام","قضاء الفوائت"]},{"id":1468,"question":"يقول السائل: ما حكم الوصية للأقارب غير الوارثين؟ هل هو واجب أم سُنة؟","title":"حكم الوصية للأقارب غير الوارثين","answer":"الجواب:\nمستحبة، مساعدة الأقارب غير الورثة مستحبة، يعني الوصية لهم. أما الورثة فلا؛ يقول النبي ﷺ: لا وصية لوارث.\nس: يكون من الثُّلُث؟\nج: من الثلث فما دونه.","link":"https://binbaz.org.sa/fatwas/21565/حكم-الوصية-للاقارب-غير-الوارثين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الوصية للأقارب غير الوارثين.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1532,"question":"أصبتُ بمرضٍ في أول رمضان العام، وفقدتُ شعوري، وما شعرتُ بالدنيا إلا بعد رمضان؟","title":"حكم القضاء على مَن أصيب بغيبوبة كل رمضان","answer":"الجواب:\nيعني: غيبوبة؟\nس: نعم تقريبًا حول الغيبوبة.\nج: إذا ذهب عقلُك فلا شيءَ عليك، وإن كان عقلك معك تقضي، هل لم تكن تعقل شيئًا؟\nس: نعم.\nج: ما عليك شيء.\nس: لا إطعام ولا صيام؟\nج: لا إطعام ولا صيام؛ لأنه كالمجنون وكالمعتوه، وقد رُفِعَ القلمُ عن ثلاثةٍ.","link":"https://binbaz.org.sa/fatwas/21632/حكم-القضاء-على-من-اصيب-بغيبوبة-كل-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصيام على من زال عقله.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","قضايا المرأة"]},{"id":1605,"question":"والد أوصى في وصيته لأبنائه بأن يُضحُّوا له كل سنةٍ، فمضت أيام التَّشريق في إحدى السنوات ولم يُضحّوا، فما الواجب عليهم؟","title":"حكم من أخلّ بوصية والده أن يُضَحَّى عنه","answer":"الجواب:\nيعني: هو الذي أوصى به؟\nس: نعم.\nج: يذبحونها ولو بعد العيد.\nس: هل عليهم التوبة؟\nج: نعم، عليهم التوبة إذا كانوا تعمَّدوا، حتى ولو من مالهم..... لو تصدَّق عنه بذبيحةٍ في أي وقتٍ، تصدَّق بها على الفقراء فله أجر.\nس: إذا لم يكن له مالٌ وإنما أوصى الأولاد أن يذبحوا؟\nج: إذا تيسر لهم.\nس: يعني ما هو واجب؟\nج: لا، ما هو واجب: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ ۝ وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:14- 15]، فمع كونهما جاهداه في الشرك قال الله له: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا بالإحسان إليهما وبرّهما، وإن كانا مشركين، فلعل الله يهديهما بسبب برّه لهما، والإحسان إليهما، والرفق بهما، لعلهما ولعلهما.","link":"https://binbaz.org.sa/fatwas/21709/حكم-من-اخل-بوصية-والده-ان-يضحى-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أوصى أولاده بأن يضحوا له كل عام ولم يستطيعوا.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1854,"question":"صيام الزوجة القضاء أيضًا بإذن زوجها؟","title":"هل يلزم المرأة استئذان زوجها لصوم القضاء؟","answer":"الجواب:\nلا، يلزمها القضاء، لكن إذا دعت الحاجة إلى التأخير فلا بأس، إذا طلب منها التأخير، فقد كانت عائشة تُؤخِّر.\nس: لكن تستأذنه؟\nج: في القضاء الأحسن تستأذن؛ لأن وقته واسع، القضاء وقته واسع.\nس: وإذا ضاق الوقتُ؟\nج: إذا ضاق الوقتُ ما عاد هناك إذن.","link":"https://binbaz.org.sa/fatwas/21963/هل-يلزم-المراة-استىذان-زوجها-لصوم-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يلزم المرأة استئذان زوجها في صوم القضاء.mp3","categories":["قضاء الصيام","قضايا المرأة"]},{"id":2095,"question":"أوصى المُوصِي بوصيَّةٍ ولم يقبلها المُوصَى له؟","title":"حكم الوصية إذا لم يقبلها المُوصَى له","answer":"الجواب:\nإذا ما قبلها تصير للورثة.\nس: للورثة أم لبيت المال؟\nج: لا، للورثة، ورثة الموصِي.","link":"https://binbaz.org.sa/fatwas/22213/حكم-الوصية-اذا-لم-يقبلها-الموصى-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أوصى المُوصِي ولم يقبلها المُوصَى له.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2184,"question":"كتابة الوصية هل هي واجبة؟","title":"ما حكم كتابة الوصية؟","answer":"الجواب:\nلا، مستحبة، لكن إذا كان له شيء يخشى عليه، مثل: ديون ما عليها وثائق، فعليه أن يُثبتها للناس حتى لا تضيع حقوقهم، أمَّا إذا لم يكن عليه شيء وإنما هي مجرد صدقة فمستحبٌّ له إذا كان عنده شيء يُوصي فيه، إذا كانت عنده سعة.","link":"https://binbaz.org.sa/fatwas/22306/ما-حكم-كتابة-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كتابة الوصية.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2276,"question":"امرأة لها ابنان، ولها مِلكٌ عبارة عن منزلٍ، واشترطت أنه إذا تُوفي الابنُ الصَّغير أن يحلّ محله ابنه كالسّبالة؟","title":"ما حكم الوصية لابن الابن والأجنبي؟","answer":"الجواب:\nإذا أوصت لهم؛ لا بأس، بقدر الثلث، ما لهم إلا قدر الثلث، إلا أن يرضى بقيةُ الورثة.\nس: الابنان شريكان في المنزل بعد ورثهما أمّهما؟\nج: المقصود أنها إذا أوصت لأولاد ولدها تكون الوصيةُ ناجزةً لا بأس بها، لكن بالثلث فأقل.\nس: هي أوصت لأحد ..؟\nج: أو لأجنبي لا بد أن يكون بالثلث فأقل.\nس: أوصت لأبناء أحد الابنين، هل يجوز ذلك؟\nج: بالثلث فأقل؛ لأنَّه ما يرث، فالابن مع الابن عمُّهم يمنعهم، ما هم بورثةٍ، فإذا أوصت لهم بالثلث أو بأقل كالربع والخمس لا بأس.\nس: الموصي ولو كان ماله قليلًا؟\nج: ولو كان ماله قليلًا إذا أوصى.","link":"https://binbaz.org.sa/fatwas/22399/ما-حكم-الوصية-لابن-الابن-والاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشتراك الأبناء في الميراث.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2335,"question":"رجلٌ نوى صيامَ يومٍ قضاءً، لكنَّه ما أكمل الصيام وأفطر، فهل عليه شيء؟","title":"حكم مَن بدأ صيامَ يومٍ قضاءً ولم يكمله","answer":"الجواب:\nما يجوز له أن يُفطر إلا من عِلَّة مرضٍ أو\nس: كأن يكون في وليمةٍ وأُلْزِمَ؟\nج: لا، الفريضة ما يُفطر فيها، يعتذر ويقول: إني صائم، فعليه أن يُجيب الدعوة ويقول: إني صائم، يقول ﷺ: إذا دُعِيَ أحدُكم فليُجِبْ، فإن كان صائمًا فليُصَلِّ يعني: فلْيَدْعُ وإن كان مُفْطِرًا فليَطْعَم.\nس: يُعيد هذا اليوم؟\nج: إذا أفطره يُعيده.\nس: يقضي هذا اليوم مرةً أخرى؟\nج: لا، يُعيد اليوم الذي كان عليه، ما صار شيء.\nس: لكن يأثم هذا الرجل؟\nج: يأثم إذا أفطر في الفريضة بغير عذرٍ شرعيٍّ.","link":"https://binbaz.org.sa/fatwas/22459/حكم-من-بدا-صيام-يوم-قضاء-ولم-يكمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نوى صيامَ يومٍ قضاءً ولم يكمل وأفطر.mp3","categories":["قضاء الصيام"]},{"id":2342,"question":"حديث عائشة رضي الله عنها أنها كانت تقول: \"كان عليَّ الصومُ من رمضان، فلا أقضيه إلا في شعبان\"، ما العِلَّة من تأخيرها؟","title":"ما علة تأخير عائشة قضاء الصوم إلى شعبان؟","answer":"الجواب: تقول: \"لمكان رسول الله ﷺ\"؛ لأجل اتِّصالها بالرسول وحاجته منها.\nس: لو أخَّره لغير حاجةٍ إلى شعبان؟\nج: ما فيه بأس، ما بين رمضان إلى رمضان لا بأس.\nس: لو أخَّره بعد رمضان؟\nج: ما يجوز، أفتى جماعةٌ من الصَّحابة أنَّ عليه مع القضاء إطعامَ مسكينٍ عن كلِّ يومٍ.","link":"https://binbaz.org.sa/fatwas/22466/ما-علة-تاخير-عاىشة-قضاء-الصوم-الى-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العلة في تأخير عائشة قضاء الصوم إلى شعبان.mp3","categories":["شروح الحديث","قضاء الصيام"]},{"id":2576,"question":"تجزيء الصيام على الأولاد، خمسة أولاد؛ كل واحد يصوم ستة أيام (عن والدهم)؟","title":"حكم صوم أولاد المتوفَّى عنه بتقسيمه بينهم","answer":"الجواب: ما في بأس، الأولاد أو الإخوة أو غيرهم هذا يصوم خمسة وهذا يصوم خمسة عشرة أيام وهذا يصوم.\nس: لكن لو صاموا كلهم في يوم واحد.\nالشيخ: الظاهر ما يضر، من مات وعليه صيام، كلهم صام يومًا.\nس: يأثمون إن لم يقضوا عنه؟\nالشيخ: لا، مستحب، المعروف بين العلماء أنه مشروع.","link":"https://binbaz.org.sa/fatwas/22709/حكم-صوم-اولاد-المتوفى-عنه-بتقسيمه-بينهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تجزئة الصيام على الأولاد إذا مات والدهم وعليه صوم.mp3","categories":["قضاء الصيام"]},{"id":2767,"question":"امرأة تسأل تقول: لها أخوات ماتوا قبل سنتين أو ثلاثة، وماتوا في أيام شهر رمضان وكن صائمات، فالسؤال هل الأخت أو أحد من العشيرة يصوم بقية الأيام؟","title":"هل يُصام بقية رمضان عنْ مَنْ مات فيه؟","answer":"الجواب: ماتوا في رمضان يعني ما عليهم شيء، لا يُصام عنهم ولا يُتصدق عنهم، معذورون ما تركوه وتساهلوا.","link":"https://binbaz.org.sa/fatwas/22915/هل-يصام-بقية-رمضان-عن-من-مات-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مات في أيام رمضان فهل يصوم وليه بقية الأيام.mp3","categories":["قضاء الصيام"]},{"id":4882,"question":"هل تقدم الوصية على الدين؟","title":"هل يجوز تقديم الوصية على الدين؟","answer":"لا، الدين مقدَّم على كل شيء مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ [النساء:11] قضى النبي ﷺ بالدين قبل الوصية.","link":"https://binbaz.org.sa/fatwas/25387/هل-يجوز-تقديم-الوصية-على-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما يقدم الوصية أم الدين.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":5226,"question":"وهذا سائل يقول: فضيلة الشيخ، جزاكم الله خيرًا، سألتني امرأةٌ وتقول: إنها كانت تجهل قضاء رمضان، وعاشت عدَّة سنوات لا تقضي ما فاتها بسبب الحيض وغيره، والآن تسأل وتقول: ماذا أفعل؟ وكيف أقضي ما فاتني؟ علمًا بأن عمرها يزيد على خمسين سنة؟","title":"حكم من لم تقض الصيام عدة سنوات؛ لجهلها","answer":"الجواب: هذا يسأل عنه الكثيرُ من نساء البادية والحاضرة، وأغلب ما يكون في البادية، والجواب: أنَّهم يُوجَّهون ويُرشدون أنَّ عليهم القضاء، وهذا الجهل الذي منهم لا يعذرهم من القضاء؛ لأنَّ هذا أمرٌ معلومٌ بين المسلمين، وشعيرة الله بين المسلمين، وقصارى ما عندها أنها غافلةٌ معرضةٌ، ما سألت، ولا انتبهت. فعليها القضاء -تقضي الصيام- وإذا كانت عندها سعةٌ تُطعم عن كلِّ يوم مسكينًا، كما أفتى جماعةٌ من الصحابة بذلك، نصف صاع من التمر، أو من الأرز، كيلو ونصف تقريبًا، عن كل يومٍ، يُجمع ويُعطاه بعض الفقراء عن عدد الأيام، وهي تقضي ما عليها من الأيام متابعةً أو مُفرَّقةً ما يضرُّ، سواء فرَّقتها أو تابعتها، مع التوبة والاستغفار عمَّا جرى من التَّأخير.","link":"https://binbaz.org.sa/fatwas/30170/حكم-من-لم-تقض-الصيام-عدة-سنوات-لجهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 258.mp3","categories":["قضاء الصيام"]},{"id":5322,"question":"ما هو القول الصحيح في الوصية الواجبة، ومن قال بالوصية الواجبة من العلماء؟","title":"ما حكم الوصية؟ ومتى تكون واجبة؟","answer":"الجواب: الوصية الواجبة من الحقوق التي عليه، يجب عليه أن يوصي بالديون التي ما عليها بيّنات؛ كفارات، حقوق عليه للناس، يلزمه أن يُوصِي بها. الحق الذي عليه لله أو لعباده يوصي به، وأما الوصية بالثلث، بطاعة الله، أو بالربع، أو بالخمس، هذه مستحبة.[1]","link":"https://binbaz.org.sa/fatwas/30985/ما-حكم-الوصية-ومتى-تكون-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 042.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":5851,"question":"امرأة مرضت في شهر رمضان، وأفطرت أيامًا منه، والآن شفيت من المرض، لكن [لا] تستطيع صيام الأيام التي فطرتها؟","title":"من أفطرت في رمضان لمرض ولم تستطع القضاء","answer":"الجواب: لعلها لا تستطيع، على كل حال من أفطرت في رمضان، أو أفطر غيرها من الرجال، ثم عافاه الله، أو عافاها الله؛ عليهما القضاء، الله يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فعلى المريضة، والمريض إذا شفي أن يقضي ما أفطره من رمضان، ولا يلزمهما أن يكون متتابعًا، ولو مفرقًا يصوم، ويفطر حتى يكمل، لا بأس بأن يقضي مفرقًا.  فإن كان لا يستطيع؛ لأن المرض باقٍ؛ فيبقى عليه الدين في ذمته حتى يستطيع، وحتى يشفى، ولو بعد أعوام، ما دام المرض يرجى زواله، وليس بميئوس منه، فالصوم يبقى في الذمة حتى يشفى، ثم يقضي بعد ذلك، ولو بعد رمضانات، ما دام المرض معه، حتى إذا عرف الأطباء أن هذا المرض لا يزول، وأنه مستمر، وأن مثله يستمر؛ فحينئذ يطعم عن كل يوم مسكينًا، ولا قضاء عليه، يطعم عن كل يوم مسكينًا، نصف صاع من قوت البلد إذا كان قادرًا، ولا شيء عليه بعد ذلك، هذا إذا قرر الأطباء أن هذا المرض مثله، لا يرجى برؤه مثله يستمر، أما ما دام المرض يرجى برؤه، ويرجى زواله؛ فإن الصوم يبقى في الذمة، فإذا شفي الإنسان من رجل، أو امرأة، إذا شفي؛ قضى قضاء غير متتابع، ما هو بلازم متتابع، إن تتابع؛ فهو أفضل، وإلا فلا يلزمه التتابع، إذا قضى مفرقًا، يصوم، ويفطر حتى ينهي ما عليه؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/1189/من-افطرت-في-رمضان-لمرض-ولم-تستطع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_185.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","قضايا المرأة"]},{"id":5856,"question":"امرأة مرضت في شهر رمضان، وأفطرت أيامًا منه، والآن شفيت من المرض، لكن [لا] تستطيع صيام الأيام التي فطرتها؟","title":"من أفطرت في رمضان لمرض ولم تستطع القضاء","answer":"الجواب: لعلها لا تستطيع، على كل حال من أفطرت في رمضان، أو أفطر غيرها من الرجال، ثم عافاه الله، أو عافاها الله؛ عليهما القضاء، الله يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فعلى المريضة، والمريض إذا شفي أن يقضي ما أفطره من رمضان، ولا يلزمهما أن يكون متتابعًا، ولو مفرقًا يصوم، ويفطر حتى يكمل، لا بأس بأن يقضي مفرقًا.  فإن كان لا يستطيع؛ لأن المرض باقٍ؛ فيبقى عليه الدين في ذمته حتى يستطيع، وحتى يشفى، ولو بعد أعوام، ما دام المرض يرجى زواله، وليس بميئوس منه، فالصوم يبقى في الذمة حتى يشفى، ثم يقضي بعد ذلك، ولو بعد رمضانات، ما دام المرض معه، حتى إذا عرف الأطباء أن هذا المرض لا يزول، وأنه مستمر، وأن مثله يستمر؛ فحينئذ يطعم عن كل يوم مسكينًا، ولا قضاء عليه، يطعم عن كل يوم مسكينًا، نصف صاع من قوت البلد إذا كان قادرًا، ولا شيء عليه بعد ذلك، هذا إذا قرر الأطباء أن هذا المرض مثله، لا يرجى برؤه مثله يستمر، أما ما دام المرض يرجى برؤه، ويرجى زواله؛ فإن الصوم يبقى في الذمة، فإذا شفي الإنسان من رجل، أو امرأة، إذا شفي؛ قضى قضاء غير متتابع، ما هو بلازم متتابع، إن تتابع؛ فهو أفضل، وإلا فلا يلزمه التتابع، إذا قضى مفرقًا، يصوم، ويفطر حتى ينهي ما عليه؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/1189/من-افطرت-في-رمضان-لمرض-ولم-تستطع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_185.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","قضايا المرأة"]},{"id":5912,"question":"هل يلزم إتمام الصيام إذا كان الصائم يقضي أيامًا من رمضان، ثم رغب أن يفطر، ويجعل بدل هذا اليوم يومًا آخر؟","title":"حكم من شرع في صيام القضاء ثم أراد أن يفطر","answer":"الجواب: المعروف عند العلماء أنه شرع في فرض فيلزمه تمامه، ولا يجوز له الإفطار إلا من علة، كمرض أصابه، أو سفر، أو حدث، وإلا فالواجب عليه أن يتمم الصوم المفترض، كقضاء رمضان، والنذر، يتمه، ولا يفطر فيه إلا من علة تبيح الفطر.","link":"https://binbaz.org.sa/fatwas/1247/حكم-من-شرع-في-صيام-القضاء-ثم-اراد-ان-يفطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_243.mp3","categories":["قضاء الصيام"]},{"id":5975,"question":"الذي عليه قضاء رمضان يصوم متصلًا، أو متفرقًا؟","title":"حكم التتابع في صوم القضاء","answer":"الجواب: صوم رمضان، لا ما في تتابع، شهر رمضان إن تابعه؛ فحسن، وإلا ما هو بلازم لو صام، وأفطر حتى يقضي، ما في بأس، ما هو لازم التتابع.","link":"https://binbaz.org.sa/fatwas/1354/حكم-التتابع-في-صوم-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_311.mp3","categories":["قضاء الصيام"]},{"id":5977,"question":"الذي عليه قضاء رمضان يصوم متصلًا، أو متفرقًا؟","title":"حكم التتابع في صوم القضاء","answer":"الجواب: صوم رمضان، لا ما في تتابع، شهر رمضان إن تابعه؛ فحسن، وإلا ما هو بلازم لو صام، وأفطر حتى يقضي، ما في بأس، ما هو لازم التتابع.","link":"https://binbaz.org.sa/fatwas/1354/حكم-التتابع-في-صوم-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_311.mp3","categories":["قضاء الصيام"]},{"id":6167,"question":"رجل عليه أيام من رمضان هل يجوز له أن يصوم هذه الأيام موزعة في كل يوم جمعة حيث يوجد عنده بقية الأيام عمل؟","title":"حكم صوم يوم الجمعة قضاءً","answer":"الجواب: قضاء رمضان لا يلزم فيه التتابع، يجوز تفريقه، قضاء الأيام الذي عليه من رمضان، كمن سافر في رمضان، أو مريض، بقي عليه أيام يقضيها مفرقة، لكن كونه يجعلها في جمعة هذا محل نظر؛ لأن الرسول ﷺ نهى عن صوم يوم الجمعة وقال: لا تخصوا يوم الجمعة إلا بصوم يوم قبله، ويوم بعده هذا التطوع، إذا تطوعنا.  لكن إذا أراد أن يصومها عن واجب، عن فريضة عليه لأنه لا يتمكن من صيامه في الأيام الستة الأخرى، أو قضاء رمضان؛ فهذا محل نظر، إن صامه فيجزئ -إن شاء الله- لأنه ما قصد الجمعة لفضلها، وإنما قصدها؛ لأنه يفرغ فيها، فهذا في الأظهر أنه يصح.  لكن لو تيسر له أن يصوم في غير الجمعة، أو يصوم معها قبلها شيء، فهذا أولى متابعة لظاهر الحديث عن النبي ﷺ لأنه إذا أمكن أن يكون صومه لغير الجمعة إذا أفرد اليوم، فهذا أولى، وإن صام مع الجمعة يومًا كالسبت، أو الخميس؛ زالت الكراهة، وزالت الشبهة.","link":"https://binbaz.org.sa/fatwas/1621/حكم-صوم-يوم-الجمعة-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_512.mp3","categories":["قضاء الصيام"]},{"id":6713,"question":"من مات وعليه أيام من رمضان، هل يصوم عنه وليه؟","title":"من مات وعليه أيام من رمضان هل يُصام عنه؟","answer":"الجواب:  هذا هو السنة لقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه متفق على صحته، فإذا مات، وعليه أيام لم يقضها، وقد تمكن، قام من مرضه، ولكن ما صام، تساهل؛ يقضى عنه. أما إذا كان ما طاق، مات في مرض، ولا قدر له الشفاء، فهذا لا يقضى عنه، وليس عليه إطعام؛ لأنه ما تمكن من القضاء. وأما الصلوات فلا تقضى، الصلاة لا تقضى عن الميت.","link":"https://binbaz.org.sa/fatwas/2587/من-مات-وعليه-ايام-من-رمضان-هل-يصام-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1083.mp3","categories":["قضاء الصيام"]},{"id":6744,"question":"حدث علي حادث، ومر علي صيام رمضان، وأنا في حالة غيبوية، فأرجو من فضيلتكم إعلامي، ما حكم صيام رمضان علي، والصلاة في حالة الغيبوبة ؟","title":"حكم من أصيب بغيبوبة مع شهر رمضان","answer":"الجواب: إذا كان عقلك قد زال قبل رمضان، واستمر العقل زائلًا حتى خرج رمضان ما عليك شيء، لا صلاة ولا صيام على شرط التكليف الآخر ..، إذا كنت في رمضان كله قد زال عقلك فلا صلاة ولا صيام، وإن صمت قضيت من باب الاحتياط، كما قاله بعض أهل العلم فحسن، ولكن لا يلزمك لا صلاة، ولا صيام.  أما إذا كانت الغيبوبة قليلة يوم يومين، هذا مثل النوم تقضي بعد الصحو، تقضي ما فاتك من صلاة، وصوم إذا كانت الغيبوبة قصيرة، ثلاثة أيام فأقل، مثل ما قضى بعض الصحابة، مثل عمار، وغيره، أما إذا طال الأمر؛ فهذا أشبه بالجنون، فلا شيء عليك.","link":"https://binbaz.org.sa/fatwas/2625/حكم-من-اصيب-بغيبوبة-مع-شهر-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1121.mp3","categories":["من يجب عليه الصوم","قضاء الصيام"]},{"id":6788,"question":"تزوجت قبل رمضان بمدة ثمانية أيام، وأصبحت في يوم من الأيام جُنُبًا، وأفطرت ذلك اليوم ... فأفطرت في اليوم الثاني، وداعبت أهلي، فأفطرت هكذا.. فما حكم الشرع في ذلك؟","title":"حكم من أصبح جُنُبًا في رمضان ثم داعب أهله وأفطر","answer":"الجواب: كون الإنسان أصبح جُنُبًا ما يمنع من الصوم، له يجامع في الليل ولكن لا يغتسل إلا بعد الصبح لا يضر هذا الشيء، ولا يجوز له الفطر بسبب ذلك، النبي ﷺ ربما جامع أهله ليلًا ثم أصبح جنبًا ثم اغتسل وذهب للصلاة عليه الصلاة والسلام، فلا حرج في أن الإنسان يؤخر الغسل حتى يتسحر، ثم يغتسل بعد الأذان، بعد الصبح ما يضره ذلك، بشرط أنه يبادر حتى يحضر الجماعة. أما الجماع في رمضان هذا منكر ومن كبائر الذنوب، فلا يجوز الجماع في رمضان للمقيم، بل عليه أن يتجنب أهله في ذلك ويكتفي بالليل، فإذا وقع منه شيء في النهار بأن جامع أهله فعليه التوبة إلى الله، وعليه الكفارة، وهي عتق رقبة مع القدرة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعا من الحنطة أو من التمر أو من الأرز من قوت البلد على ستين مسكين، ثلاثين صاعا على ستين مسكينًا، إذا عجز عن العتق، وعن الصيام شهرين متتابعين مع قضاء اليوم، مع المبادرة بقضاء اليوم منه ومنها، وعلى كل واحد إخراج كفارة إذا تطاوعا، عليهما الكفارة عتق عبد عن كل واحد، فإن عجزا صام كل واحد شهرين متتابعين، فإن عجزا أطعما ستين مسكينًا، كل واحد يطعم ثلاثين صاعًا، يعني ستين صاعًا عليهما جميعًا لستين مسكينًا، كل مسكين يعطى صاعًا واحدًا، نصف صاع عن الرجل ونصف صاع عن المرأة، من قوت البلد: من ذرة أو دخن أو حنطة أو زبيب أو رز أو غير ذلك. السؤال: طيب لو تكرر ثلاث أربع مرات؟ الجواب: كل ما تكرر عليه كفارة لكل يوم، إذا كان يومين كفارتين، ثلاثة أيام ثلاث كفارات. السؤال: إذا كان مسافرًا؟ الجواب: أما إذا كان من أهل السفر؛ لا يضر، إذا كانا مسافرين جميعًا؛ فلا بأس إذا أباح له الفطر بالأكل؛ يبيح له الجماع.","link":"https://binbaz.org.sa/fatwas/2638/حكم-من-اصبح-جنبا-في-رمضان-ثم-داعب-اهله-وافطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1134.mp3","categories":["الجماع في نهار رمضان","قضاء الصيام"]},{"id":6900,"question":"إني رجل قد كنت في ماضي الزمن منذ سنتين، أو ثلاث أفطرت في رمضان، وكنت لا أميز في ذاك الوقت بتقوى الله، وقد تبت إلى الله  ولا أدري كم علي من يوم صيام، ولا أقدر على عددها، فما الحكم، وأنا محتار؟","title":"حكم من أفطر من رمضان عامداً ثم تاب","answer":"الجواب:  وأنت تصلي؟ إن كان يصلي وهو مسلم؛ عليه أن يقضي هذه الأيام التي تركها من رمضان بحسب ظنه واجتهاده، يقضي الأيام التي أفطرها في رمضان، وأما إن كان لا يصلي، ثم تاب الله عليه، فالتوبة تجب ما قبلها؛ لأن الذي لا يصلي كافر ،وإذا تاب ليس عليه قضاء ما فات، عليه التوبة الصادقة، والندم على ما مضى، والعزم الصادق ألا يعود فيما هو عليه من الباطل، والتوبة تجب ما قبلها، وقد أسلم ناس كثيرون في عهد النبي ﷺ وبعده، ولم يؤمروا بقضاء الصلوات التي تركوها. السؤال: وآخر يقول : يوجد في مدينة الخبر مدرسة لتحفيظ القرآن الكريم لمحو الأمية، وعادة تكون النساء كبارًا، ولكن تلك الجماعة، ينقص تلك الجماعة أشياء منها: عدم توفر المكان المناسب، وعدم توفر رواتب للمدرسات، وعدم وجود طريقة صحيحة لسير تلك المدرسة على الطريق الصحيح، فما رأيكم؟ الجواب: ننظر في الموضوع -إن شاء الله- نكاتب أهلها، أو يكاتبونا، أما المدرسة لابد نسأل عنها جماعة الخير الذين هناك، وينظر في الأمر -إن شاء الله-.","link":"https://binbaz.org.sa/fatwas/2836/حكم-من-افطر-من-رمضان-عامدا-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1284.mp3","categories":["قضاء الصيام"]},{"id":6928,"question":"إذا مات الوالد وعليه صوم ثلاثة رمضانات، هل أصوم عنه، أم ماذا أعمل؟","title":"حكم الصيام عن الوالد إذا مات","answer":"الجواب: إذا مات الوالد مفرطًا، قد عافاه الله، وشفاه الله من المرض، ولكنه تساهل؛ فالمشروع لك أن تصوم عنه أنت، وإخوانك؛ لأن النبي  قال: من مات وعليه صيام؛ صام عنه وليه وسأله جماعة كل واحد يسأله، يقول: يا رسول الله إن أبي مات وعليه كذا، أفأصوم عنه؟ والآخر يقول: إن أمي ماتت وعليها كذا، أفأصوم عنها؟ والآخر يقول: إن أختي ماتت وعليها كذا، أفأصوم عنها؟ فيقول النبي ﷺ: أرأيت لو كان على أبيك دين؟ أرأيت لو كان على أمك دين؟ أكنت قاضيه، اقضوا الله، فالله أحق بالوفاء.  فعليك أن تقضي ذلك أنت وإخوانك، مشروع لكما، يعني: سنة لكما، فإن لم تقضوا عنه؛ أطعمتم عنه من ماله عن كل يوم إطعام مسكين، هذا إذا لم تقضوا عنه صيامًا، والسنة الصيام عن والدكم هذا إذا كان شفي من مرضه، وتساهل، أما إذا كان مات في مرضه -ما شفي- مرض، واستمر معه المرض حتى مات، هذا لا قضاء، ولا إطعام، لا قضاء عليه، ولا إطعام. الطالب: سقط عنه؟ الجواب: سقط عنه؛ لأنه معذور. السؤال: طيب بالنسبة للصلاة؟ الجواب: لا تقضى الصلاة.","link":"https://binbaz.org.sa/fatwas/2849/حكم-الصيام-عن-الوالد-اذا-مات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1297.mp3","categories":["قضاء الصيام"]},{"id":6944,"question":"مات قبل ما يقضي الصيام؟","title":"حكم من مات وعليه صوم","answer":"الجواب: إذا كان مات وعليه صيام، وهو غير معذور؛ يصام عنه، أما إذا مات في العذر، مات في مرضه، ما صام؛ فلا عليه صيام، لا صيام، ولا شيء، النبي ﷺ قال: من مات وعليه صيام؛ صام عنه وليه. والذي مات بسبب المرض، ولم يشف منه، بل مات في مرضه؛ فهو معذور، لا إطعام عليه، ولا صيام.","link":"https://binbaz.org.sa/fatwas/2874/حكم-من-مات-وعليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1322.mp3","categories":["قضاء الصيام"]},{"id":6975,"question":"هل يجوز قضاء الصيام عن أحد أقربائي الذين توفوا، وعليه بعض شهر رمضان؟ ومن الذي يصوم عن أهله؟","title":"حكم قضاء الصوم عمن مات وعليه صوم","answer":"الجواب:\n\nإذا صام عنهم؛ فهو مأجور، قال النبي ﷺ: من مات، وعليه صيام صام عنه وليه والولي القريب، يعني فإذا صام أقاربه؛ يكونوا أولى من غيرهم، وإذا صام غيرهم؛ فلا بأس؛ أجزأ كالدين؛ لأن الرسول ﷺ شبهه بالدين، والدين يقضيه القريب، والبعيد، إذا كان الميت وجب عليه القضاء.\n\nأما إذا كان الميت مات في المرض، ما عاش بعد المرض، مات في المرض؛ فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/2926/حكم-قضاء-الصوم-عمن-مات-وعليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1374.mp3","categories":["قضاء الصيام"]},{"id":7002,"question":"إذا أرادت المرأة أن تصوم قضاء شهر رمضان الذي مضى، ولكنها لا تستطيع لإصابتها بفقر دم، وحامل، وتتألم، وتخاف إذا صامت أن يؤثر على صحتها، وصحة جنينها، وكذلك تخاف أن يأتي الشهر المقبل وهو رمضان، ومع ذلك لم تقض الشهر الأول؛ لأنها بدأت الحمل، ولم تستطع .. فما الحكم؟","title":"حكم تأخير قضاء رمضان للمرأة الحامل إلى بعد رمضان الثاني","answer":"الجواب:\n\nعليها أن تعمل ما تستطيع، تجرب إن استطاعت تصوم، وتصبر حتى تكمل قبل رمضان، فهذا هو الواجب عليها، فإن عجزت؛ أجلت إلى بعد رمضان، والحمد لله فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] والحبلى، والمرضع في حكم المريض، فإذا عجزت؛ تؤجل، وليس عليها إطعام، ولكنها تؤجل، فإذا قويت؛ صامت ولو بعد رمضان، وليس عليها شيء لأجل العذر، ولكنها تجرب، تنظر؛ لأن بعض الحبلى ما يضرهم، كثير من الحاملات في أول الأمر ما يضرهن.","link":"https://binbaz.org.sa/fatwas/2934/حكم-تاخير-قضاء-رمضان-للمراة-الحامل-الى-بعد-رمضان-الثاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1382.mp3","categories":["قضاء الصيام","قضايا المرأة"]},{"id":7012,"question":"إذا أرادت المرأة أن تصوم قضاء شهر رمضان الذي مضى، ولكنها لا تستطيع لإصابتها بفقر دم، وحامل، وتتألم، وتخاف إذا صامت أن يؤثر على صحتها، وصحة جنينها، وكذلك تخاف أن يأتي الشهر المقبل وهو رمضان، ومع ذلك لم تقض الشهر الأول؛ لأنها بدأت الحمل، ولم تستطع .. فما الحكم؟","title":"حكم تأخير قضاء رمضان للمرأة الحامل إلى بعد رمضان الثاني","answer":"الجواب:\n\nعليها أن تعمل ما تستطيع، تجرب إن استطاعت تصوم، وتصبر حتى تكمل قبل رمضان، فهذا هو الواجب عليها، فإن عجزت؛ أجلت إلى بعد رمضان، والحمد لله فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] والحبلى، والمرضع في حكم المريض، فإذا عجزت؛ تؤجل، وليس عليها إطعام، ولكنها تؤجل، فإذا قويت؛ صامت ولو بعد رمضان، وليس عليها شيء لأجل العذر، ولكنها تجرب، تنظر؛ لأن بعض الحبلى ما يضرهم، كثير من الحاملات في أول الأمر ما يضرهن.","link":"https://binbaz.org.sa/fatwas/2934/حكم-تاخير-قضاء-رمضان-للمراة-الحامل-الى-بعد-رمضان-الثاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1382.mp3","categories":["قضاء الصيام","قضايا المرأة"]},{"id":7080,"question":"توجد امرأة أفطرت من رمضان قبل الماضي سبعة أيام؛ لوجود حيض، وصامت منها أربعة، وبقي ثلاثة، ثم أتى رمضان الماضي، فوضعت حملًا كان في بطنها، وأفطرت منه ستة وعشرين يومًا، وصامت عشرة أيام، وبقي ستة عشرة يومًا، وقد أقبل رمضان وهي لم تصم، علمًا بأن الصيام يؤثر عليها بحيث لا تستطيع المشي، ويضيق صدرها، وحالتها النفسية ضعيفة جدًا في العمل، هل تصوم، أو تدفع الكفارة؟","title":"حكم من دخل عليها رمضان وعليها أيام من رمضان الماضي","answer":"الجواب:\n\nلا، عليها صيام، لكن يؤجل إذا كانت عاجزة الآن، يؤجل عليها إلى بعد رمضان؛ حتى تجد القوة، فتصوم بقية الأيام الأولى، الثلاثة أيام التي عليها، ثم تصوم بقية الأيام التي عليها من رمضان القريب، وهذا هو الواجب عليها فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، يقول سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185].\n\nوإذا كانت أخرت ذلك لعجز -أخرت الثلاثة للعجز- ما عليها إطعام، وإن كان تساهلًا؛ فعليها صاع ونصف، عن كل يوم نصف صاع، عن الثلاثة التي بقيت من العام الماضي، أما هذا العام إذا كانت أخرتها ولم تستطع قضاء هذه الأيام؛ لعجزها، ومرضها؛ فلا شيء عليها، تقضيها فقط، وليس عليها إطعام في المستقبل.","link":"https://binbaz.org.sa/fatwas/3093/حكم-من-دخل-عليها-رمضان-وعليها-ايام-من-رمضان-الماضي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1472.mp3","categories":["قضاء الصيام","قضايا المرأة"]},{"id":7133,"question":"نسأل عن امرأة تفطر في رمضان بسبب الولادة والرضاعة، وكذلك بسبب بعض الأمراض قبل أن تقضي ما فاتها يأتي عليها رمضان آخر، والآن هي تسأل هل عليها القضاء فقط كلما تيسر لها القضاء، أم عليها الكفارة، علمًا أنها تقضي أيام فاتتها من حوالي ثلاثة عشر عامًا تقريبًا؟","title":"ما يلزم من جاء رمضان وعليها أيام أفطرتها للولادة والرضاع؟","answer":"الجواب:\n\nعليها القضاء فقط، إذا كان التأخير من أجل الرضاع، والحمل؛ فعليها القضاء فقط، وليس عليها إطعام، أما إن كانت فرطت، تساهلت، تؤخر من دون عذر؛ فعليها مع القضاء إطعام مسكين عن كل يوم.\n\nوأما الذي يؤخر من عذر شرعي من مرض، أو رضاع، أو حمل؛ فهذا عليه القضاء فقط، يصوم بعدد الأيام، وليس عليه إطعام، ولكن متى تساهل وأخر -وهو صحيح يستطيع القضاء- فإنه يأثم، وعليه مع القضاء إطعام مسكين عن كل يوم.","link":"https://binbaz.org.sa/fatwas/3160/ما-يلزم-من-جاء-رمضان-وعليها-ايام-افطرتها-للولادة-والرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1518.mp3","categories":["قضاء الصيام","قضايا المرأة"]},{"id":7217,"question":"إذا كان ولد له أم ما تصلي إلا أنها يعني مقرة بالتوحيد يعني، وماتت، وهي تاركة للصلاة نهائيًا، وعارفة الحكم في ترك الصلاة، وعلى عقيدة شرك في الأولياء والصالحين وشيء من هذا، تعتقد فيهم، هل يضحي لها، يستغفر لها؟","title":"إهداء الثواب للميت إذا كان مقرًا بالتوحيد ولكنه لا يصلي","answer":"الجواب:\n\nلا لا، من مات على الشرك لا يستغفر له، النبي ﷺ استأذن ربه أن يستغفر لأمه -وماتت في الجاهلية- فلم يأذن له  أذن له أن يزورها، ولم يأذن له أن يستغفر لها، وهكذا لم يأذن له أن يستغفر لعمه أبي طالب، مع أنه نصره وحماه، وأنزل الله في هذا: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى [التوبة:113].\n\nفلا يستغفر للمشرك، ولو أنها أمه إذا ماتت على الشرك، أو على ترك الصلاة، لا يستغفر لها، ولا يدعى لها، لكن لا يدعى عليها، لا يدعى لها ولا يدعى عليها، لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا، لكن من مات على الشرك ولو كان والدًا، ولو كان أمًا، ولو كان أخًا، لا يدعى له، ولا يستغفر له، نسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/3275/اهداء-الثواب-للميت-اذا-كان-مقرا-بالتوحيد-ولكنه-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1600.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها","إهداء القرب للميت"]},{"id":7219,"question":"إذا فاتت على الإنسان بضعة أيام من رمضان لمرض، واستمر هذا المرض إلى رمضان التالي وبعد ذلك عليه القضاء مع الإطعام، هل يخرج كل يوم، أم يخرجها جميعًا في يوم واحد؟ ولمن تكون؟ وهل تجزئ النقود؟","title":"تأخير قضاء رمضان إلى رمضان الثاني بسبب المرض","answer":"الجواب:\n\nإذا استمر المرض من رمضان إلى رمضان ما عليه إطعام، يقضي وبس يعني معذور، إذا استمر معه المرض من رمضان إلى رمضان، ثم عافاه الله بعد رمضان الثاني؛ يقضي ما فاته من رمضان الأول من دون حاجة إلى إطعام. \n\nإنما الإطعام على من تساهل ولم يقض حتى جاء رمضان من غير عذر، يتساهل، وأخر حتى جاء رمضان ولم يقض؛ فهذا هو الذي عليه مع القضاء الإطعام عند جماعة من أصحاب النبي ﷺ أفتى به جماعة من أصحاب النبي ﷺ أنه يصوم ما ترك، ويطعم عن تفريطه، كونه أخر من غير عذر عن كل يوم نصف صاع من قوت البلد، من أرز، أو غيره يجمع ويعطاه بعض الفقراء، ولا يعطي نقودًا، يعطي طعامًا كما أفتى الصحابة، ويجمع ويعطيه بعض الفقراء قبل الصيام، أو بعد الصيام، والحمد لله.","link":"https://binbaz.org.sa/fatwas/3281/تاخير-قضاء-رمضان-الى-رمضان-الثاني-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1606.mp3","categories":["قضاء الصيام"]},{"id":7224,"question":"إذا فاتت على الإنسان بضعة أيام من رمضان لمرض، واستمر هذا المرض إلى رمضان التالي وبعد ذلك عليه القضاء مع الإطعام، هل يخرج كل يوم، أم يخرجها جميعًا في يوم واحد؟ ولمن تكون؟ وهل تجزئ النقود؟","title":"تأخير قضاء رمضان إلى رمضان الثاني بسبب المرض","answer":"الجواب:\n\nإذا استمر المرض من رمضان إلى رمضان ما عليه إطعام، يقضي وبس يعني معذور، إذا استمر معه المرض من رمضان إلى رمضان، ثم عافاه الله بعد رمضان الثاني؛ يقضي ما فاته من رمضان الأول من دون حاجة إلى إطعام. \n\nإنما الإطعام على من تساهل ولم يقض حتى جاء رمضان من غير عذر، يتساهل، وأخر حتى جاء رمضان ولم يقض؛ فهذا هو الذي عليه مع القضاء الإطعام عند جماعة من أصحاب النبي ﷺ أفتى به جماعة من أصحاب النبي ﷺ أنه يصوم ما ترك، ويطعم عن تفريطه، كونه أخر من غير عذر عن كل يوم نصف صاع من قوت البلد، من أرز، أو غيره يجمع ويعطاه بعض الفقراء، ولا يعطي نقودًا، يعطي طعامًا كما أفتى الصحابة، ويجمع ويعطيه بعض الفقراء قبل الصيام، أو بعد الصيام، والحمد لله.","link":"https://binbaz.org.sa/fatwas/3281/تاخير-قضاء-رمضان-الى-رمضان-الثاني-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1606.mp3","categories":["قضاء الصيام"]},{"id":7592,"question":"سؤال المستمعة (م. أ. ع) من تعز، تقول فيه: إذا أفطرت المرأة بعض أيام رمضان لعذر شرعي، وعندما تقضيها هل يجب عليها أن تقضيها متتابعة، وهل إذا كانت متفرقة لا تجزئ، وهل يجب الصيام ست من شوال متتابعة أم متفرقة؟","title":"حكم التتابع في قضاء صوم رمضان","answer":"الجواب: قضاء رمضان واجب ولكن لا يجب فيه التتابع، إن قضت متتابعة هو أفضل، وإن فرقت فلا بأس، القضاء واجب والتتابع غير واجب، فإذا قضت رمضان مفرقاً فلا بأس، سواء كان إفطارها في رمضان لمرض أو لحيض أو نفاس، القضاء لا يجب فيه التتابع ولكن يستحب، فإذا فرقت القضاء فلا بأس أو فرقه الرجل، فرق القضاء لأنه مريض فأفطر في رمضان ثم صام بعد ذلك لا حرج في التفريق، وأما ست من شوال فلا يجب صيامها، سنة مستحبة، صيام ست من شوال صوم مستحب ولا يجب، فمن تركه فلا بأس ومن صامه له أجر. نعم.","link":"https://binbaz.org.sa/fatwas/4645/حكم-التتابع-في-قضاء-صوم-رمضان ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01910.mp3","categories":["قضاء الصيام"]},{"id":7640,"question":"سماحة الشيخ! هذه رسالة وردتنا من المدينة المنورة ومن المرسلة .. تقول إحدى الأخوات (م. م) تقول في رسالتها: كان العلم قليلاً في قديم الزمان، وكان العلماء قليلون أيضاً، وقد قال لي أهلي: إن الشاب لا يصوم من رمضان إلا العشر الأيام الأولى، وإنني لا أدري هل صمت العشر الأيام الأولى أم صمت الشهر كله؟ فهل يجب علي القضاء أم لا يجب، أفيدونا جزاكم عنا خير الجزاء؟","title":"حكم من ترك الصيام جهلاً بحكمه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن صيام رمضان فريضة على كل مكلف من المسلمين من الذكور والإناث، وهو أحد أركان الإسلام الخمسة، فإذا كانت السائلة لم تصم رمضان أو العشرين الأخيرة من رمضان بعد بلوغها الحلم فإن عليها القضاء، والبلوغ يكون بأن أربعة أمور في حق المرأة:\n1- يكون بالحيض.\n2- ويكون بإكمال خمسة عشر سنة.\n3- ويكون بالإنبات؛ إنبات الشعر الخشن حول الفرج أو العانة، ما يسمى بالشعرة.\n4- ويكون بأمر رابع وهو الإنزال.\nإما في اليقظة، إنزال المني عن شهوة، أو في النوم وهو الاحتلام.\nفإذا وجد واحد من هذه الأربعة صارت المرأة مكلفة، تجب عليها الصلاة والصوم والحج مع الاستطاعة، فإذا كانت السائلة قد تركت شيئاً من رمضان بعد بلوغها فعليها القضاء، ولا يلزم الترتيب بل تقضيه ولو مفرقاً.\nوعليها إطعام مسكين عن كل يوم في أصح قولي العلماء، عن تأخيرها لقضاء ذلك الصيام، نص صاع من تمر أو رز أو حنطة أو شعير أو زبيب أو غيره من قوت البلد.\nوعليها التوبة والاستغفار عما جرى لها من التأخير، فإن التأخير معصية، تأخير الصوم عن رمضان معصية، فعليها التوبة والاستغفار عن ذلك، والتوبة يمحو الله بها ما قبلها، إذا كانت توبة صادقة نصوحاً محى الله بها ما قبلها. نعم.","link":"https://binbaz.org.sa/fatwas/4759/حكم-من-ترك-الصيام-جهلا-بحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03501.mp3","categories":["قضاء الصيام"]},{"id":7642,"question":"هذه رسالة وردتنا يا سماحة الشيخ عبد العزيز من الحدود الشمالية يقول مرسلها ضبيان خضر الجرير الشمري: سافرت في رمضان وأفطرت يوماً، فما هي كفارته؟","title":"ما كفارة الإفطار في رمضان للسفر؟","answer":"الجواب: إذا كنت أفطرت في السفر فعليك القضاء فقط ولا فيه كفارة، إذا كنت أفطرت في السفر من أجل السفر فلا حرج بل سنة، يقول الله عز وجل: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فالله وسع ويسر سبحانه وتعالى، ورخص للمسافر والمريض أن يفطرا، فإذا سافرت إلى أي جهة من الجهات فأفطرت يوماً أو أكثر؛ فعليك القضاء ولا كفارة عليك، إلا إذا تأخر القضاء إلى رمضان آخر فلم تقض فعليك القضاء بعد رمضان مع إطعام مسكين عن كل يوم، نص صاع من التمر أو الرز أو غيرهما من قوت البلد عن التأخير، أفتى به جماعة من الصحابة رضي الله وأرضاهم وهو أصح قولي العلماء، يعني: تقضي يومك الذي أفطرته، وتفدي فدية تكفر بإطعام مسكين إذا كان القضاء تأخر إلى ما بعد رمضان آخر، والله سبحانه وتعالى أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/4776/ما-كفارة-الافطار-في-رمضان-للسفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03503.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":7645,"question":"أيضاً هذا محمد ناصف معطي أو مطري يقول: لقد تركت بعض الأيام من شهر رمضان في العام الماضي، وأنا محرج حيث سيداهمني أو يداهمني رمضان هذا العام، هل أترك الصيام لما بعد رمضان وأصوم، أم أصوم الذي عن رمضان الماضي، ثم أبدأ مع المسلمين في صيام هذا الشهر؟","title":"حكم تأخير قضاء أيام من رمضان حتى رمضان التالي","answer":"الشيخ: تعيد السؤال.\nالمقدم: يقول: إنه قد فاتني بعض الأيام من شهر رمضان في العام الماضي، وأخشى أن يداهمني، أو يقول: داهمني رمضان هذا العام، وأنا لم أصم ما بقي علي من رمضان العام الماضي، فهل أصوم الذي من العام الماضي، أو أتركه وأؤجله وأصوم مع المسلمين رمضان هذا العام الذي علينا؟\nالشيخ: يلزم السائل وفقه الله أن يبادر بالصوم في هذه المدة الباقية، وأن يقضي ما عليه من الصوم، هذا الواجب عليه قبل رمضان، ولا يجوز له التأخير والتساهل، لكن لو غلبه أمر كمرض منعه من الصوم فإنه يصوم بعد رمضان، وعليه إطعام مسكين عن كل يوم؛ بسبب التساهل الذي ألجأه إلى التأخير، أما الآن فيلزمه الصوم، يلزمه أن يبادر ويصوم ما عليه ويقضي قبل رمضان، هذا هو الواجب عليه، إلا إذا منعه مانع من المرض، كالمرض ما استطاع فلا بأس أن يؤجل، إذا عجز بسبب المرض حتى جاء رمضان فإنه يؤجله ويصومه بعد رمضان إن شاء الله، وعليه إطعام مسكين عن كل يوم؛ لأنه تساهل في التأخير قبل المرض، أما لو أخره بسبب المرض في جميع السنة، يعني: من حين أفطر وهو في مرض إلى الآن في مرض حتى جاء رمضان فلا شيء عليه إلا القضاء، يقضي بعد ذلك إذا عافاه الله يقضي بعد رمضان ولا شيء عليه، أما الذي أخر الصيام تساهلاً وعدم عناية فإن هذا عليه التوبة والاستغفار، وعليه أن يقضي ويطعم إذا أخره إلى ما بعد رمضان، أما إذا صام في رجب أو في شعبان لا بأس، ما عليه شيء، يصوم ولا حرج عليه. نعم.","link":"https://binbaz.org.sa/fatwas/4785/حكم-تاخير-قضاء-ايام-من-رمضان-حتى-رمضان-التالي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03506.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":7812,"question":"تقول السائلة: امرأة لم تصم شهر رمضان لأنها جاهلة، والآن قضت ما فاتها، ولكن تسأل: هل يلزمها إطعام وكفارة؟","title":"حكم من لم يصم رمضان جهلاً لفريضته","answer":"الجواب: نعم، عليها أن تطعم عن كل يوم مسكين إذا كانت قضاؤها تأخر بعد رمضان، عليها نص صاع كيلو ونصف عن كل يوم للفقراء؛ لأنها تأخرت في القضاء بغير عذر شرعي، إذا كان قضاؤها بعد رمضان آخر. نعم.","link":"https://binbaz.org.sa/fatwas/5209/حكم-من-لم-يصم-رمضان-جهلا-لفريضته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05127.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":7881,"question":"سماحة الشيخ عبد العزيز! لدينا مجموعة كبيرة من رسائل السادة المستمعين، نبدؤها برسالة عبد الله الحماد الصالح ويسأل عن الإنزال في رمضان دون جماع، ورسالة المستمع (س. م. ش) ويسأل عن حكم التبرج، وهذه رسالة عبد الله الحماد الصالح يقول في رسالته هذه: السلام عليكم ورحمة الله وبركاته، وبعد: أرجو عرض رسالتي هذه على سماحة الشيخ عبدالعزيز بن عبدالله بن باز يقول: في شهر رمضان المبارك الذي انصرم نمت مع زوجتي على الفراش، وضميتها بدون أن أواقعها فعليًّا، أي: بدون جماع، الأمر الذي أودعني أنزل بدون مباشرة، أرجو إفادتي ما هو الحكم؟ وما هي الكفارة؟ ولكم تحياتي.","title":"حكم الإنزال في نهار رمضان","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا شك أن الجماع في صيام رمضان وفي كل صيام واجبٍ: غيرُ جائز ويبطل الصيام، أما الملامسة والتقبيل والمباشرة فلا حرج في ذلك، فقد كان النبي صلى الله عليه وسلم يباشر وهو صائم ويقبل وهو صائم عليه الصلاة والسلام، ولكن إذا كان الإنسان سريع الشهوة ويخشى من المباشرة أو التقبيل نزول المني فالأولى به أن يتباعد عن ذلك ولا يتساهل في هذا الشيء، فإن ضم زوجته إليه أو قبلها أو لمسها ثم خرج منه المني فإنه يجب عليه الغسل من جهة المني وقضاء ذلك اليوم إذا كان في النهار، وليس عليه كفارة، إنما الكفارة فيما إذا جامعها، أما مجرد ضمها إليه أو تقبيلها أو ما أشبه ذلك من الملامسة هذا كله جائز ولا حرج فيه فعله النبي صلى الله عليه وسلم ورخص فيه اللهم صل عليه وسلم، ولكن إذا كان من طبعه سرعة الشهوة فالأولى به التباعد عن هذا الشيء حتى لا يقع في المحذور، وإذا نزل المني فإن عليه قضاء ذلك اليوم، يفسد الصوم وعليه قضاء ذلك اليوم، وليس عليه كفارة، هذا هو الحكم، يقضي اليوم ويغتسل من الجنابة لأنه يوجب الغسل ولكن ليس عليه قضاء[1]، والمرأة كذلك مثله إن أنزلت بضمها أو بلمسها أو تقبيلها إن أنزلت منيٍّا فعليها الغسل وقضاء ذلك اليوم، وليس عليها كفارة، وإن لم تنزل ليس عليها شيء. نعم.\n\n\n\tلعل الشيخ رحمه الله قصد: (وليس عليه كفارة)، كما هو الظاهر من السياق.","link":"https://binbaz.org.sa/fatwas/5350/حكم-الانزال-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_058/05801.mp3","categories":["مفسدات الصيام","قضاء الصيام","الجماع في نهار رمضان"]},{"id":7895,"question":"أولاً نبدأ برسالة: سعود عبد الرحمن الفرج ، وقد عرضنا بعضاً منها في اللقاء الماضي.يقول في رسالته سعود: عمري واحد وعشرون سنة لم أصم ولا شهر من رمضان، ولكن نويت -أعتقد أنه يقول أتوب- ونبت إلى الصواب والحق، وأريد أن أبتدئ من جديد، هل يجوز ذلك أم لا؟ -يعني: أعتقد أنه يقول: هل ما أصوم السنوات الماضية-.","title":"حكم من ترك صيام عدة رمضانات ثم تاب","answer":"الجواب: عليك أن تصوم رمضان والتوبة إلى الله عز وجل، وعليك أن تصوم ما مضى من الشهور عند جمهور أهل العلم، هذا هو الصواب عليك أن تصوم ذلك ولو مفرقاً غير متتابع تصوم السنة الأولى بعد بلوغك، السنوات التي بعد البلوغ بإكمال خمسة عشر سنة، أو بإنزال المني عن شهوة، أو بإنبات الشعر الخشن حول الفرج، هذه الأشياء التي يبلغ بها الرجل، فعليك أن تقضي رمضان الذي بعد هذا، رمضانات تصومها مع التوبة إلى الله والإنابة إليه سبحانه وتعالى، وإذا أطعمت مع هذا عن كل يوم مسكيناً كان ذلك أكمل؛ لأن بعض الصحابة أفتى بهذا ، فتطعم مسكيناً عن كل يوم مع القضاء. هذا إذا كنت تصلي، أما إذا كنت لا تصلي مع ترك الصوم فترك الصلاة كفر وضلال، فيكفي التوبة وليس عليك صوم ولا صلاة، إذا كنت لا تصلي فعليك التوبة إلى الله عز وجل، والرجوع إليه والإنابة والصدق وليس عليك قضاء بعد ذلك لا صلاة ولا صيام؛ لأن ترك الصلاة كفر، كفر أكبر على الصحيح، والكافر تكفيه التوبة، إذا تاب إلى الله وأناب كفى ذلك، وليس عليه قضاء ما ترك في حال الكفر، كما قال الله سبحانه: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، وقال النبي ﷺ: التوبة تجب ما كان قبلها، والإسلام يهدم ما كان قبله. نعم.\nالسؤال: سؤاله هذا موجه لنا شخصياً يقول الأخ، هل سليمان الشبانة يستطيع الإجابة على الأسئلة؟\nالجواب نقول: يا أخ سعود عبد الرحمن لا، يوجد من يستطيع الإجابة على الأسئلة، وفقنا وإياك لما يحبه ويرضاه.","link":"https://binbaz.org.sa/fatwas/5367/حكم-من-ترك-صيام-عدة-رمضانات-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06001.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":7910,"question":"هذه رسالة وردتنا من المرسلة أم محمد من جدة، تقول: السلام عليكم ورحمة الله وبركاته.لقد مرضت أمي قبل شهر رمضان بعدة أشهر، ولقد استمر مرضها إلى أن اختارها الله سبحانه وتعالى إلى جواره، ولقد صامت شهر رمضان إلا تسعة أيام، مع أنها مريضة، ولكنها أفطرت هذه الأيام من أجل العلاج، ولكنها قالت لي: إنها تود أن تقضي هذه الأيام التسعة بعد أن ينتهي شهر رمضان، ولكنها توفيت، فهل يجوز علي أن أقضي هذه الأيام التسعة، أم ماذا، أرشدوني جزاكم الله عني كل خير؟","title":"حكم من أفطرت في مرضها ثم ماتت","answer":"الجواب: مادامت ماتت في مرضها فلا قضاء عليها ولا إطعام، هذا هو الصواب، مادامت والدتها ماتت في مرضها فليس عليها قضاء ولا إطعام بل معفو عنها. نعم.","link":"https://binbaz.org.sa/fatwas/5393/حكم-من-افطرت-في-مرضها-ثم-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06202.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":8205,"question":"سؤال يقول: هل يجوز قضاء أيام من رمضان يوماً بعد يوم؟","title":"حكم التتابع في قضاء أيام رمضان","answer":"الجواب: نعم يجوز، المتابعة أفضل إذا تيسر ذلك، فإن فرق بين أيام القضاء فلا بأس ؛ لأن الله قال جل وعلا: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، ولم يقل متتابعة ، قال: فَعِدَّةٌ ...، هذا يشمل المتتابعة والمفرقة، فالأمر في هذا واسع والحمد لله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6021/حكم-التتابع-في-قضاء-ايام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09507.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":8216,"question":"سؤال يقول: هل يجوز قضاء أيام من رمضان يوماً بعد يوم؟","title":"حكم التتابع في قضاء أيام رمضان","answer":"الجواب: نعم يجوز، المتابعة أفضل إذا تيسر ذلك، فإن فرق بين أيام القضاء فلا بأس ؛ لأن الله قال جل وعلا: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، ولم يقل متتابعة ، قال: فَعِدَّةٌ ...، هذا يشمل المتتابعة والمفرقة، فالأمر في هذا واسع والحمد لله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6021/حكم-التتابع-في-قضاء-ايام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09507.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":8462,"question":"أخونا عثمان حسن الشريف يسأل مجموعة من الأسئلة في سؤاله الأول، يقول: توفي والدي يوم ثلاثة رمضان، فهل يجب علي إكمال رمضان له، يعني: أصوم بالنيابة عنه سبعة وعشرين يوماً؟","title":"حكم القضاء عمن مات في رمضان","answer":"الجواب: ... لا ليس عليك شيء، الحمد لله، لما توفي سقط عنه الواجب، فليس عليك ولا يشرع لك أن تصوم عنه أيضاً. نعم.","link":"https://binbaz.org.sa/fatwas/6468/حكم-القضاء-عمن-مات-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12309.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":8482,"question":"أختنا تقول: إنها لم تكن تقضي الأيام التي فاتتها من شهر رمضان وهي لا تستطيع إحصاءها فكيف توجهونها؟","title":"حكم من أفطر أياماً لا يعلم عددها ويريد القضاء","answer":"","link":"https://binbaz.org.sa/fatwas/6541/حكم-من-افطر-اياما-لا-يعلم-عددها-ويريد-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12509.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":8965,"question":"أختنا تقول: كان لي أخ يشتغل سائق في أرض زراعية وحدث مرة أن اصطدم برجل كبير في السن فمات الرجل، سلم أخي نفسه للشرطة معترفاً أنه اصطدم بالرجل لكن بدون قصد، فخرج أخي بكفالة ولم يمض عام واحد حتى قتل أخي بيد طفل في العاشرة، فسامحه أبي وسامحت أمي وكلنا سامحنا الطفل وأهله، أمي صامت شهرين متتابعين حتى تكفر عن أخي بعض ذنوبه، ما حكم صيامها وهل علينا في جانب أخي من شيء أرجو التكرم بإفادتنا؟","title":"الواجب على أولياء الميت إذا مات وعليه صوم","answer":"الجواب: قد أحسنتم في التسامح والعفو، وأحسنت الوالدة في الصوم عن ابنها؛ لأن عليه الكفارة، وهي: عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، ولقد أحسنت الوالدة في صيام شهرين؛ لأن تحصيل الرقبة قد يتعسر في بعض الأحيان، وقد يعجز عنه القاتل وهو لا يوجد إلا قليل يوجد في بعض دول أفريقيا ولكنه قليل، فإذا تمكن من شراء عبد أو الأمة من عتق فهو مقدم على الصيام، وإذا لم يتمكن صام شهرين متتابعين، ولما صامت أمك عنه فقد أحسنت في ذلك، لقول النبي ﷺ: من مات وعليه صيام صام عنه وليه، يعني: قريبه، وهي أقرب الناس إليه فقد أحسنت في ذلك. نعم.\nالمقدم: كأني بالوالدة لم تصم من أجل القتل الخطأ سماحة الشيخ بل صامت للتكفير عن ذنوب أخرى؟ ترشدونها إلى شيء لو تكرمتم؟\nالشيخ: إن كانت صامت عن ابنها لأجل الصوم الذي عليه بسبب قتله الشيخ الكبير فهذا صحيح، فإن كانت صامت لغير ذلك فهذا لا يجزي، لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى، فيستحب لها.. يشرع لها أن تصوم أو أبوه إن كان هو موجود أو أحد إخوانه أو إحدى خواته، هذا كله طيب، لقوله ﷺ: من مات وعليه صيام صام عنه وليه. نعم.\nالمقدم: بارك الله فيكم، لو توزعت الأسرة الصيام يجوز هذا؟\nالشيخ: هذا فيه التتابع لابد يصومه واحد. نعم.","link":"https://binbaz.org.sa/fatwas/7123/الواجب-على-اولياء-الميت-اذا-مات-وعليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_145/14507.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9146,"question":"السؤال الثاني في رسالتها تقول فيه: علي صيام من ست سنوات، ويقولون: بأن اليوم بيومين، فما حكم الشرع في ذلك؟ وهل هذا صحيح، أفيدونا أفادكم الله؟","title":"كيفية قضاء الصوم المتأخر من سنوات","answer":"الجواب: عليك أن تقضي الصيام الذي عليك فقط من غير زيادة، وقول بعض الناس: اليوم بيومين هذا خطأ باطل ما له أصل، وإنما تصومين الأيام فقط التي أفطرتيها، وليس عليك زيادة فقط. لكن إذا كان تأخير الصيام من دون عذر شرعي ليس هناك مرض يمنع ولا أعذار أخرى من حمل أو نفاس أو نحو ذلك فإن عليك مع الصوم إطعام مسكين عن كل يوم إذا تيسر لك ذلك، إذا كنت مليئة تطعمي عن كل يوم مسكيناً، يعني: نصف صاع عن كل يوم كيلو ونص تقريباً عن كل يوم يجمع أو يعطى لبعض الفقراء عن الأيام التي عليك كلها، كل يوم عنه نصف صاع من قوت البلد من أرز أو تمر أو حنطة أو شعير أو ذرة من قوت البلد ونحو ذلك، تدفعينه لبعض الفقراء، تنظرين بعض البيوت الفقيرة ويدفع إليهم هذا الطعام عن جميع الأيام التي لم تصوميها إذا كنت أخرتيها من دون عذر، أما إذا كان لك عذر كالمرض فليس عليك إطعام، تصومين فقط عدد الأيام فقط لا زيادة، وأما قول من قال: إنه يصام عن كل يوم يومين فهذا قول باطل ليس له أساس.","link":"https://binbaz.org.sa/fatwas/7308/كيفية-قضاء-الصوم-المتاخر-من-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23011.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9148,"question":"الرسالة الأولى وصلت إلى البرنامج من السيدة رانية الجندي الأردن المفرق، تقول في رسالتها وفي بدايتها: بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، أرجو التكرم بالإجابة عن هذا  أنا امرأة مسلمة، منذ سنتين لم أصم شهر رمضان، في السنة الأولى؛ لأنني كنت في أيام النفاس، وفي السنة الثانية كنت حامل ومريضة، ونصحني الدكتور بعدم الصيام، وأنا لم أقض هذه الأيام ولم أخرج بدلاً منها مال، هل يقبل الله توبتي؟ وما الحكم في هذه الحالة أفيدوني أفادكم الله؟","title":"حكم من مضت عليها سنتان ولم تصم بسبب النفاس والحمل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: أيها الأخت في الله السائلة! لا شيء عليك والحمد لله ما دمت إنما أخرت الصيام لأجل النفاس والحمل فعليك أن تصومي ما أفطرت من السنتين والحمد لله، إن كنت تساهلت في هذا وأخرت القضاء من غير عذر بعد الطهور من النفاس، فعليك أن تطعمي عن كل يوم مسكين زيادة، هذا هو الذي أفتى به جمع من أصحاب النبي صلى الله عليه وسلم، فتصومي الأيام التي عليك وتطعمي عن كل يوم مسكيناً، أما إن كنت معذورة في المدة كلها أولاً: بالنفاس، وثانياً: بالحمل، وليس هناك مدة بينهما حصل فيها قدرة على القضاء، فإنك تقضين فقط وليس عليك إطعام، بل تصومين الأيام التي عليك والحمد لله وليس عليك إطعام، ولا حرج أن تصوميها متتابعة أو متفرقة، وأما إن كنت تساهلت ولم تصومي وأنت تستطيعين الصوم فإنك عليك التوبة إلى الله مع ذلك والاستغفار، وعليك الصيام، وعليك إطعام مسكين عن كل يوم، كيلو ونصف عن كل يوم للفقراء والمساكين، يعني من التمر أو من الأرز أو من الحنطة من قوت البلد، يعطاها المساكين ولو جمعت كلها ودفعت إلى مسكين واحد أو اثنين أو ثلاثة كفى ذلك والحمد لله.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7298/حكم-من-مضت-عليها-سنتان-ولم-تصم-بسبب-النفاس-والحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23001.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9188,"question":"الرسالة التالية وصلت إلى البرنامج من الرياض وباعثها أحد الإخوة يقول (ص. أ. أ) سوداني، أخونا يقول: قبل ثلاث عشرة سنة كنت أعمل في مدينة غير التي أسكنها وكان العمل شاقاً للغاية، وصادفت تلك الفترة شهر رمضان الكريم ولم أستطع صيام خمسة عشر يوماً من شهر رمضان، فهل يجوز القضاء، وهل علي أشياء غير القضاء أرجو أن توجهوني، وفيما إذا تكرر الحال مرة أخرى كيف أتصرف جزاكم الله خيراً؟","title":"حكم الفطر في رمضان لعذر مشقة العمل","answer":"","link":"https://binbaz.org.sa/fatwas/7348/حكم-الفطر-في-رمضان-لعذر-مشقة-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15103.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":9204,"question":"عند قضاء الأيام التي يفطرها الإنسان من شهر رمضان للأعذار المبيحة مثل: المرض، والسفر، والحيض، يقولون: يجب زيادة يوم عند قضائها ليكون شاهد، فهل هذا صحيح؟","title":"حكم زيادة صيام يوم فوق قضاء الأيام التي أفطرها","answer":"الجواب: ليس له أصل، لا، ليس عليها إلا قضاء ما تركت، إذا نامت عن شيء أو نسيت شيء من الصلوات تصلي ما فاتها فقط، وفي الحيض لا صلاة عليها، لو كانت حائض أو نفساء ليس عليها قضاء صلاة الحيض والنفاس وإنما الصوم صوم رمضان فقط، لكن لو نامت عن صلاة أو نسيتها فعليها أن تقضي فقط ما تركت؛ لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكر لا كفارة لها إلا ذلك.","link":"https://binbaz.org.sa/fatwas/7364/حكم-زيادة-صيام-يوم-فوق-قضاء-الايام-التي-افطرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18111.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9308,"question":"الأخ مجدي محمد عبدالخالق مصري الجنسية ومقيم بالعراق يسأل مجموعة من الأسئلة، في سؤاله الأول يقول: أنا رجل متزوج ومعي عائلتي، وقد وضعت زوجتي في أول يوم من شهر رمضان الماضي، وأتى رمضان الآخر وهي مرضع، كيف يكون حالها لو تكرمتم؟","title":"حكم الصيام لمن أتى رمضان وهي مرضع","answer":"الجواب: لا حرج عليها في الإفطار إذا كان الرضاع يضرها معه الصوم، فالحاصل أنها مأذون لها المرضع والحامل، والمريضة، كلهن معذورات، حتى تستطيع الصيام، فإذا جاء رمضان الآخر وهي ترضع ولم تستطع الصيام بل يشق عليها من أجل الرضاع فإنها تفطر رمضان الآخر ثم تصومهما بعد ما يحصل لها القوة على ذلك، إما بفطم الولد أو بقوة تعينها على الصوم، أو بغير هذا من أسباب القدرة.\nفالحاصل: أنها ما دامت يشق عليها الصوم من أجل الرضاع أو من أجل الحمل، أو من أجل بعض الأمراض فإنها تفطر ولا كفارة عليها؛ لأنها غير يائسة من الصوم بل ترجو القدرة عليه، فإذا يسر الله لها الصوم فالحمد لله تصوم الجميع، تصوم ما مضى عليها متتابعًا أو مفرقًا لا حرج، ولا كفارة عليها. نعم.\nالمقدم:إذا أفطرت من أجل الإرضاع، هل يلزمها مع القضاء شيء أو لا.. ؟\nالشيخ: لا يلزمها شيء؛ لأنه كالمرض.\nالمقدم: لأنه كالمرض؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7469/حكم-الصيام-لمن-اتى-رمضان-وهي-مرضع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18408.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":9468,"question":"السؤال الأول ورد من الأخ شيخي محمد بلدية عين الخضرة ولاية المسيلة الجزائر- العاصمة، يسأل في أول سؤال عن حكم من أفطر في رمضان يومين حتى أتاه شهر رمضان القادم، فما حكم ذلك وأفيدوه؟","title":"حكم من أخر قضاء ما عليه من رمضان حتى دخل رمضان","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن من أفطر في رمضان يجب عليه أن يقضي قبل رمضان الآخر، وما بين الرمضانين فهو محل سعة من ربنا ، إذا قضى في شوال أو في ذي القعدة أو في ذي الحجة أو في المحرم أو ما بعد ذلك.. إلى شعبان، فعليه أن يقضي ما أفطره لمرض أو سفر أو نحو ذلك قبل رمضان، فإن أخره إلى رمضان آخر لم يسقط القضاء بل يجب عليه القضاء ولكن يلزمه مع القضاء إطعام مسكين عن كل يوم زيادة مع القضاء، أفتى به جماعة من أصحاب النبي ﷺ، فيقضي ويطعم عن كل يوم مسكينًا نصف صاع من قوت البلد كيلو ونصف من قوت البلد من تمر أو أرز أو غير ذلك، أما إن صام ذلك قبل رمضان القادم فإنه يقضي ولا إطعام عليه. نعم.","link":"https://binbaz.org.sa/fatwas/7632/حكم-من-اخر-قضاء-ما-عليه-من-رمضان-حتى-دخل-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19201.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9666,"question":"يقول: كنت في وقت مضى تركت شهوراً كثيرة من رمضان لم أصمها عمداً، وهي تقارب ست سنوات، يعني: ستة رمضانات، وكنت في نفس الوقت لا أقصر في صلاتي، والآن لا أقدر على صيامها كلها، وكذلك لا أستطيع أن أكفر إلا أنني أستطيع أن أصومها مجزأة ولو يوماً في الأسبوع، ولا أستطيع أكثر من ذلك أفيدوني أفادكم الله؟","title":"حكم ترك صيام عدة رمضانات","answer":"الجواب: الواجب عليك يا أخي! التوبة إلى الله، التوبة الصادقة التي تشتمل على الندم على الماضي والأسف ما مضى منك، والعزم الصادق أن لا تعود في ذلك، وعليك قضاؤها على حسب طاقتك، ولو يوماً في الأسبوع تقضيها حتى تكمل إن شاء الله، تلك السنوات الست ما دمت تصلي والحمد لله، فعليك أن تكمل وتقضي هذا الصيام على حسب طاقتك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nوالأول الأول أيضاً عليه إطعام، عليك أن تطعم عن هذه السنوات، عن كل يوم نصف صاع على الصحيح أفتى به جماعة من أصحاب النبي ﷺ، فعليك أن تطعم عن كل يوم مسكيناً إذا كنت تستطيع ذلك، نصف صاع من قوت البلد، من تمر أو رز أو غيرهما إذا استطعت، أما إذا كنت فقيراً فلا شيء عليك. نعم.\nالمقدم: يعني: مع القضاء؟\nالشيخ: مع القضاء، مع الصيام.\nالمقدم: لأنه مر عليها رمضانات؟\nالشيخ: ... مضى عليه رمضانات. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7830/حكم-ترك-صيام-عدة-رمضانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25112%20After%20editing.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9828,"question":"هذا محسن حسين المسعودي من بلدة البدع الشمالية، بعث بهذه الرسالة، يقول: إن والدي من البادية الرحل ويقوم بتربية المواشي، وأنا كنت أقوم برعاية الأغنام عنده، وفي يوم من أيام رمضان المبارك وأنا أرعى في الأغنام قابلتني فتاة كذلك ترعى أغنامها، وكان الوقت ما بين الظهر والعصر، وجلست معها، وأخذت في مبادلتي للحديث ووصل ذلك إلى المزاح والمداعبة في أثناء ذلك اليوم الذي هو في شهر رمضان، فحصل مني ما حصل دون أن أقرب هذه الفتاة، يسأل عن حكم ذلك في نهار رمضان؟","title":"حكم من داعب أجنبية في نهار رمضان حتى أنزل","answer":"الجواب: أما من ناحية الحكم فهو لا يجوز؛ لأنها أجنبية وليس له أن يحادثها محادثة تجب الشهوة وربما أغرت إلى الفتنة والزنا، بل يجب التحرز من ذلك.\n\nأما الحديث العابر الذي ليس فيه إثم وليس فيه ما يجر إلى الفاحشة كسؤالها عن أهلها، أو سؤالها عن المرعى الطيب، أو عن الماء أو ما أشبه ذلك من الأمور التي ليس فيها ما يجر إلى فتنة هذا لا بأس به.\n\nوأما المداعبة والأشياء التي تتعلق بالفاحشة وتدلي إلى الزنا وتسبب الوقوع في المنكر هذه أشياء لا تجوز.\n\nأما الصوم فهو صحيح صومه صحيح إذا كان لا يخرج منه مني.\n\nالمقدم: لا هو ذكر أنه أنزل.\n\nالشيخ: أما إذا كان أنزل فإن عليه أن يقضي اليوم؛ فإنه يفطر هذا لأنه بإنزاله المني يفطر صومه، أما المذي فلا يفطر على الصحيح، المذي هو الماء اللزج الذي يخرج عند آثار الشهوة هذا لا يفطر الصوم على الصحيح من أقوال العلماء.\n\nأما المني فإنه يفطر صومه وعليه قضاء.\n\nالمقدم: لكن لا يلزمه كفارة.\n\nالشيخ: وليس عليه كفارة الكفارة، الكفارة في الجماع خاصة.","link":"https://binbaz.org.sa/fatwas/8002/حكم-من-داعب-اجنبية-في-نهار-رمضان-حتى-انزل","audio":"https://files.zadapps.info/binbaz.org.sa/%D8%AD%D9%83%D9%85%20%D9%85%D8%AF%D8%A7%D8%B9%D8%A8%D8%A9%20%D8%A7%D9%84%D9%85%D8%B1%D8%A3%D8%A9%20%D8%A7%D9%84%D8%A3%D8%AC%D9%86%D8%A8%D9%8A%D8%A9%20%D9%81%D9%8A%20%D9%86%D9%87%D8%A7%D8%B1%20%D8%B1%D9%85%D8%B6%D8%A7%D9%86.mp3","categories":["مفسدات الصيام","قضاء الصيام"]},{"id":9978,"question":"هذه رسالة من الأخت السائلة (زينب . ع. ف. ض.) من السعودية الأخت زينب تقول في رسالتها: هي فتاة مسلمة والحمد لله تصوم وتصلي وقد أصابها مرض شديد في يوم من أيام رمضان، وقد أوشكت على الموت فأفطرت من شدة المرض ثم قضت هذا اليوم، فتسأل هل عليها في فطرها إثم؟","title":"حكم الفطر في نهار رمضان للمريض","answer":"الجواب: ليس عليها إثم بل مأجورة، الإنسان إذا أصابه المرض وشق عليه الصوم شرع له أن يفطر وهو مأجور في قبول الرخصة، يقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] ويقول النبي ﷺ: إن الله يحب أن تؤتى رخصه كما يكره أن تؤتى معصيته فإذا أخذ الإنسان بالرخصة طاعة لله وعملًا بما شرع  فهو مأجور ولا إثم عليه، فأنت أيها الأخت السائلة لا حرج عليك في إفطارك من أجل مرض وعليك القضاء وقد قضيت والحمد لله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8137/حكم-الفطر-في-نهار-رمضان-للمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20006.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10001,"question":"تقول: عندما كنت في الثانية عشرة والثالثة عشرة والرابعة عشرة من عمري أفطرت أيامًا كثيرة في رمضان تلك السنين، ولا أعلم كم عدد هذه الأيام، والآن بعد مضي عدة سنوات صحوت من غفلتي ولله الحمد والمنة، وتذكرت تلك الأيام التي أفطرتها فأردت أن أصوم ثلاثة أشهر، فصمت ستة عشر يومًا منها، ولكني الآن توقفت عن صيامها، وذلك بعد أن سمعت في برنامج نور على الدرب: أن الذي لا يصلي بحكم الكافر الذي لا يقبل منه أي عمل حتى الصيام، وحيث أنني في تلك السنوات كنت لا أصلي بعض الصلوات كسلًا، وبالإضافة إلى ذلك كنت بعد العادة الشهرية أجلس يومًا كاملًا لا أصلي فيه بحجة أن أتبين هل تطهرت تطهرًا كاملًا أم لا، فماذا أفعل، أفيدوني جزاكم الله خيرًا؟","title":"حكم من أفطر أيامًا من رمضان مع تركه للصلاة","answer":"الجواب: يكفي التوبة في هذا، يكفيك يا أيها الأخت! في الله التوبة، عليك بالتوبة والحمد لله، التوبة الندم على الماضي، والعزيمة أن لا تعودين مع الاستغفار والحمد لله؛ لأن ترك الصلاة كفر كما قال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فالذي لا يصلي لا صوم له ولا زكاة له ولا غير ذلك، فلا يلزمك القضاء حينئذ وإنما عليك التوبة، والحمد لله الذي من عليك بالتوبة والالتزام.\nالمقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8166/حكم-من-افطر-اياما-من-رمضان-مع-تركه-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33106.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":10211,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلينا من إحدى الأخوات المستمعات، تقول: أم أحمد ، أم أحمد عرضنا جزءاً من أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها مجموعة من الأسئلة، من بينها سؤال حول من أفطرت عدة رمضانات بسبب حال النفاس، ولم تقضها حتى الآن، كيف تتصرف؟ وتسأل: هل يجزئ ذلك الصيام في رجب، جزاكم الله خيراً؟","title":"حكم من أفطرت عدة رمضانات بسبب النفاس ولم تقضها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد: فالواجب على من أفطرت في رمضان من أجل النفاس أو الحيض القضاء قبل أن يأتي رمضان الآخر الذي بعده؛ لقول الله جل وعلا: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] والحائض والنفساء من جنس المريض والمسافر عليهما القضاء، فإذا طهرت من نفاسها، وطهرت من حيضها، تقضي والبدار أفضل، ولا يجوز لها التأخير إلى رمضان، بل يجب أن تبادر حتى تقضي ما عليها قبل رمضان، ولا مانع أن تصوم في رجب أو غيره، ولا حرج أن تؤخر إلى شعبان، قالت عائشة رضي الله عنها: كان يكون علي الصوم من رمضان، فلا أستطيع أن أقضي إلا في شعبان .\nفالواجب على المرأة أن تعتني بهذا الأمر، وأن تبادر بالقضاء قبل رمضان، ولو مفرقاً، ولو موزعاً، لا يجب التتابع، فتصوم وتفطر حتى تكمل، وإذا أخرته عن رمضان وجب عليها التوبة من ذلك، وعليها القضاء والإطعام، إطعام مسكين عن كل يوم، نصف صاع عن كل يوم من التمر أو غيره من قوت البلد، مقداره كيلو ونصف تقريباً، كفارة عن التأخير، فيكون عليها ثلاثة أشياء: التوبة، وقضاء الصيام، مع الإطعام عن كل يوم؛ إذا كان التأخير لغير عذر.\nأما إن كان أخرت ذلك لمرض لم تستطع معه الصوم، فلا حرج عليها، تصوم بدون إطعام، تقضي بدون إطعام، وليس عليها إثم، لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]سبحانه وتعالى، والواجب على المؤمنة أن تتقي الله، وأن تعتني بقضاء ما عليها، وأن تتحرى الأوقات التي تستطيع فيها القضاء قبل أن يأتي رمضان، حتى تفرغ من ذلك قبل أن يأتي رمضان الدائر الذي هو بعد رمضان الذي أفطرت فيه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8381/حكم-من-افطرت-عدة-رمضانات-بسبب-النفاس-ولم-تقضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31001.mp3","categories":["قضاء الصيام","الحيض والنفاس","قضايا المرأة"]},{"id":10235,"question":"امرأة كانت لا تعلم أن على المرضع والنفساء قضاء الأيام التي أفطرتها في رمضان، وقال لها بعض الناس: إن عليها أن تطعم عن كل يوم أفطرته مسكينًا، وقد فعلت ذلك، فهل يكفي هذا الإطعام، أم لابد من قضاء الأيام التي أفطرتها؟ وهل إطعامها الذي أطعمته يكفي، أم تطعم مرة أخرى؟ علمًا بأن هذا الإطعام مرت عليه سنوات كثيرة.","title":"حكم من أفطرت بسبب عذر شرعي وأطعمت ولم تقض","answer":"الجواب: عليها أن تقضي، إذا أفطرت الحامل أو المرضع وهكذا المريضة فإنها تقضي بعد ذلك، تقضي المريضة إذا شفيت، وتقضي الحامل إذا وضعت واستطاعت القضاء بعد ذلك، وتقضي المرضع كذلك، كلهن يقضين ولا يجزئ عنهن الإطعام، وإذا تأخر القضاء بغير عذر وجب القضاء والإطعام، أما إذا كان التأخير للعذر لأنها حامل، ولأن الرضاع يمنعها من ذلك أو المرض فالإطعام لا يجب، ولكن يجب القضاء فقط؛ لأنها معذورة في التأخير، فليس عليها إلا القضاء إذا شفيت المريضة وفطمت المرضعة أو قويت على الصيام وإن لم تفطم، وولدت الحامل وقويت على القضاء فإن كلًا منهن يقضي، وليس عليه إطعام لأنه معذور، لكن من تأخر قضاؤها بدون عذر فعليها مع القضاء الإطعام، ويجزئها الإطعام الذي أخرجته تحسب أن هذا هو الواجب عليها لفتوى بعض الناس، يجزئها الإطعام عما يجب عليها من الإطعام إذا كانت تأخرت في القضاء؛ لأنها أخرجت الإطعام عن تأخيرها وعن إفطارها. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8403/حكم-من-افطرت-بسبب-عذر-شرعي-واطعمت-ولم-تقض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33509.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10290,"question":"تقول في قضية أخرى سماحة الشيخ: عندما بلغت سن التكليف لم أكن أعلم بالطريقة الصحيحة لأداء الفروض ومن ذلكم الصيام، فكنت أصوم أياماً وأفطر أياماً ولم ينبهني أهلي على هذا الأمر، ولما كبرت أكثر وأكثر أدركت أني كنت مخطئة، كيف أتصرف والحال ما ذكر ولا سيما وقد أفطرت بعض الأيام ولا أدري كم هي، جزاكم الله خيراً؟","title":"حكم قضاء من أفطر أياماً معلومة من رمضان جاهلاً","answer":"الجواب: عليك أن تقضي الأيام التي أفطرت بالظن، الذي يغلب على ظنك أنك أفطرت صومي اقضيه والحمد لله، فإذا كان ظنك أنك أفطرت عشرة أيام عشرين يوماً أكثر أقل فاعملي بذلك، ولا حاجة إلى اليقين، اعملي بالظن والحمد لله، الذي تظنين افعلي، فإذا شككت هل هي عشرة أو خمسة عشر، صومي خمسة عشر، شككت هل أفطرت خمسة عشر أو عشرين صومي عشرين، اعملي بغالب الظن والحمد لله، ولا شيء عليك.\nلكن إذا كنت مليئة تستطيعين أن تطعمي أطعمي عن الصيام الذي مضى قبل رمضان الماضي، الصيام الذي أخرتيه قبل رمضان الماضي أطعمي عن كل يوم مسكين زيادة مع الصوم نصف صاع مقدار كيلو ونصف من قوت البلد من تمر أو أرز أو حنطة أو شعير نصف صاع يقارب كيلو ونصف تقريباً يعطاه الفقير، تجمعين ذلك كله وتعطينه لبعض الفقراء فقير أو فقيرين يكفي، والحمد لله، إذا كنت موسرة، أما إذا كنت عاجزة فقيرة فلا حاجة إلى الإطعام يكفي الصوم والحمد لله، حسب ظنك واجتهادك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8462/حكم-قضاء-من-افطر-اياما-معلومة-من-رمضان-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31202.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10295,"question":"تقول في قضية أخرى سماحة الشيخ: عندما بلغت سن التكليف لم أكن أعلم بالطريقة الصحيحة لأداء الفروض ومن ذلكم الصيام، فكنت أصوم أياماً وأفطر أياماً ولم ينبهني أهلي على هذا الأمر، ولما كبرت أكثر وأكثر أدركت أني كنت مخطئة، كيف أتصرف والحال ما ذكر ولا سيما وقد أفطرت بعض الأيام ولا أدري كم هي، جزاكم الله خيراً؟","title":"حكم قضاء من أفطر أياماً معلومة من رمضان جاهلاً","answer":"الجواب: عليك أن تقضي الأيام التي أفطرت بالظن، الذي يغلب على ظنك أنك أفطرت صومي اقضيه والحمد لله، فإذا كان ظنك أنك أفطرت عشرة أيام عشرين يوماً أكثر أقل فاعملي بذلك، ولا حاجة إلى اليقين، اعملي بالظن والحمد لله، الذي تظنين افعلي، فإذا شككت هل هي عشرة أو خمسة عشر، صومي خمسة عشر، شككت هل أفطرت خمسة عشر أو عشرين صومي عشرين، اعملي بغالب الظن والحمد لله، ولا شيء عليك.\nلكن إذا كنت مليئة تستطيعين أن تطعمي أطعمي عن الصيام الذي مضى قبل رمضان الماضي، الصيام الذي أخرتيه قبل رمضان الماضي أطعمي عن كل يوم مسكين زيادة مع الصوم نصف صاع مقدار كيلو ونصف من قوت البلد من تمر أو أرز أو حنطة أو شعير نصف صاع يقارب كيلو ونصف تقريباً يعطاه الفقير، تجمعين ذلك كله وتعطينه لبعض الفقراء فقير أو فقيرين يكفي، والحمد لله، إذا كنت موسرة، أما إذا كنت عاجزة فقيرة فلا حاجة إلى الإطعام يكفي الصوم والحمد لله، حسب ظنك واجتهادك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8462/حكم-قضاء-من-افطر-اياما-معلومة-من-رمضان-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31202.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10309,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (س. ص) يقول: ذكرت بعد مضي سنة أني لم أصم يوماً من الأيام وأنا مسافر في رمضان، فهل علي قضاء هذا اليوم والإطعام أم ماذا جزاكم الله خيراً؟","title":"حكم نسيان قضاء رمضان حتى دخول رمضان آخر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب عليك قضاء هذا اليوم؛ لأن الله جل وعلا يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185].\nأما كونك ناسياً فلا يمنع من القضاء وإنما يسقط عنك الإثم بسبب النسيان، وليس عليك كفارة ما دمت لم تذكر إلا بعد رمضان آخر؛ لأنك معذور بالنسيان ولا حرج عليك في عدم التكفير.\nأما إن كنت ذكرت اليوم قبل رمضان ثم تساهلت ولم تقضه إلا بعد رمضان فعليك إطعام مسكين نصف صاع من قوت البلد، من تمر أو حنطة أو أرز أو شعير يدفع لمسكين واحد، أما إذا كان النسيان استمر معك حتى دخل رمضان آخر فلا شيء عليك إلا القضاء. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8475/حكم-نسيان-قضاء-رمضان-حتى-دخول-رمضان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31301.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10317,"question":"يقول: إذا كان الشاب في بداية حياته قد ضيع بعض الصلوات وتركها وكذلك الصيام جهلاً وتكاسلاً، ثم تاب بعد ذلك وندم، فهل عليه إعادة لما ترك من الصلوات والصيام علماً بأنه لا يستطيع تحديدها، أفتونا مأجورين جزاكم الله خيراً؟","title":"حكم من تاب من ترك الصلاة والصيام كسلًا وجهلًا","answer":"الجواب: ليس عليه قضاء، والتوبة كافية، إذا كان لا يصلي ولا يصوم أو عنده أنواع من الكفر الأخرى فإن التوبة تكفي، يقول الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، ويقول جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ يعني: بالشرك والمعاصي لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]، أجمع العلماء على أن الآية المذكورة في التائبين، فإذا كان لا يصلي ولا يصوم، أو كان يسب الدين، أو كان يشرك بغير الله، يدعو الأموات، ويستغيث بأهل القبور، أو بالأصنام والأشجار، فإنه متى تاب توبةً صادقة تاب الله عليه، والتوبة الصادقة تشمل أموراً ثلاثة: الندم على الماضي الندم الصادق، والإقلاع من المعصية أو الشرك وترك ذلك، والعزم الصادق ألا يعود رغبةً فيما عند الله وإخلاصاً له ومحبةً له وتعظيماً له فإن هذه التوبة تمحو ما قبلها، من جميع أنواع الشرك والمعاصي.\nالأمر الأول: الندم على الماضي؛ خوفاً من الله وتعظيماً له.\nالأمر الثاني: الإقلاع من الذنوب من الكفر والمعاصي.\nالأمر الثالث: العزم الصادق ألا يعود في ذلك.\nفمتى فعل هذا خوفاً من الله وتعظيماً له ورغبةً فيما عنده وإخلاصاً له سبحانه تاب الله عليه ومحا عنه جميع الذنوب وليس عليه قضاؤها لا صلاة ولا صيام ولا غير ذلك، التوبة تجب ما قبلها، وإن كان عنده حق للمخلوقين فلابد من الأمر الرابع وهو رد حقوقهم إليهم كالسرقات والغصوب يعطيهم حقوقهم، وهكذا القصاص إذا قتل لهم أحداً يعطيهم حقهم بالقصاص أو الدية، لابد من أداء الحق للمخلوق أو استحلاله إذا أحله وسامحه لا بأس.\nأما إن كان فعله ليس بكفر أكبر كترك الصيام فقط وإلا هو يصلي لكن فرط في بعض الصيام فإنه يقضي، إذا كان يصلي ولكنه فرط في بعض الصيام أو في الزكاة ما زكى، ليس بكافر، ترك الصيام ليس بكفر إذا كان يؤمن بالوجوب وأن رمضان واجب عليه ولكن تساهل ففرط في بعض الصيام يقضي، عليه القضاء والتوبة إلى الله، وعليه أداء الزكاة عما مضى إذا كان لا يزكي، مع التوبة الصادقة والله يتوب على التائبين.\nأما ترك الصلاة فكفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالصلاة أمرها عظيم، وهي عمود الإسلام، من حفظها حفظ دينه ومن ضيعها ضيع دينه، نسأل الله العافية.\nفالواجب على كل مسلم أن يحذر تركها والتساهل بها، على الجميع رجالاً ونساء أن يتقوا الله، وأن يحافظوا على الصلوات الخمس في أوقاتها، وأن يؤديها الرجل في الجماعة، هذا هو الواجب على الجميع، فمن ضيعها وتهاون بها وتركها كفر نسأل الله العافية في أصح قولي العلماء.\nأما من جحد وجوبها وقال: ما هي بواجبة، هذا يكفر عند الجميع عند جميع الأمة عند جميع أهل العلم، من قال: إنها غير واجبة أو إن واحدة منها غير واجبة كالظهر أو العصر أو المغرب أو العشاء أو الفجر كفر إجماعاً، أما إذا كان يؤمن بأنها واجبة ولكن يتساهل ويتركها أو بعضها فإنه يكفر بذلك نسأل الله العافية، أما إن كان يصلي لكن في البيت فهذا يكون عاصي وعليه التوبة إلى الله وأن يصلي في الجماعة، وصلاته مجزئة لا يعيدها لكن عليه أن يصلي في الجماعة ويتوب مما سلف، إذا كان لا يصلي في الجماعة بل يصلي في البيت يجب أن يصلي مع الجماعة، وأن يتوب إلى الله مما سلف.\nأما النساء فعليهن الصلاة في البيت، السنة لهن الصلاة في البيوت، ومن صلت مع الجماعة صلاتها صحيحة، لكن الأفضل في حق النساء الصلاة في البيت. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8494/حكم-من-تاب-من-ترك-الصلاة-والصيام-كسلا-وجهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها","الرقائق"]},{"id":10329,"question":"يقول: إذا كان الشاب في بداية حياته قد ضيع بعض الصلوات وتركها وكذلك الصيام جهلاً وتكاسلاً، ثم تاب بعد ذلك وندم، فهل عليه إعادة لما ترك من الصلوات والصيام علماً بأنه لا يستطيع تحديدها، أفتونا مأجورين جزاكم الله خيراً؟","title":"حكم من تاب من ترك الصلاة والصيام كسلًا وجهلًا","answer":"الجواب: ليس عليه قضاء، والتوبة كافية، إذا كان لا يصلي ولا يصوم أو عنده أنواع من الكفر الأخرى فإن التوبة تكفي، يقول الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، ويقول جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ يعني: بالشرك والمعاصي لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]، أجمع العلماء على أن الآية المذكورة في التائبين، فإذا كان لا يصلي ولا يصوم، أو كان يسب الدين، أو كان يشرك بغير الله، يدعو الأموات، ويستغيث بأهل القبور، أو بالأصنام والأشجار، فإنه متى تاب توبةً صادقة تاب الله عليه، والتوبة الصادقة تشمل أموراً ثلاثة: الندم على الماضي الندم الصادق، والإقلاع من المعصية أو الشرك وترك ذلك، والعزم الصادق ألا يعود رغبةً فيما عند الله وإخلاصاً له ومحبةً له وتعظيماً له فإن هذه التوبة تمحو ما قبلها، من جميع أنواع الشرك والمعاصي.\nالأمر الأول: الندم على الماضي؛ خوفاً من الله وتعظيماً له.\nالأمر الثاني: الإقلاع من الذنوب من الكفر والمعاصي.\nالأمر الثالث: العزم الصادق ألا يعود في ذلك.\nفمتى فعل هذا خوفاً من الله وتعظيماً له ورغبةً فيما عنده وإخلاصاً له سبحانه تاب الله عليه ومحا عنه جميع الذنوب وليس عليه قضاؤها لا صلاة ولا صيام ولا غير ذلك، التوبة تجب ما قبلها، وإن كان عنده حق للمخلوقين فلابد من الأمر الرابع وهو رد حقوقهم إليهم كالسرقات والغصوب يعطيهم حقوقهم، وهكذا القصاص إذا قتل لهم أحداً يعطيهم حقهم بالقصاص أو الدية، لابد من أداء الحق للمخلوق أو استحلاله إذا أحله وسامحه لا بأس.\nأما إن كان فعله ليس بكفر أكبر كترك الصيام فقط وإلا هو يصلي لكن فرط في بعض الصيام فإنه يقضي، إذا كان يصلي ولكنه فرط في بعض الصيام أو في الزكاة ما زكى، ليس بكافر، ترك الصيام ليس بكفر إذا كان يؤمن بالوجوب وأن رمضان واجب عليه ولكن تساهل ففرط في بعض الصيام يقضي، عليه القضاء والتوبة إلى الله، وعليه أداء الزكاة عما مضى إذا كان لا يزكي، مع التوبة الصادقة والله يتوب على التائبين.\nأما ترك الصلاة فكفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالصلاة أمرها عظيم، وهي عمود الإسلام، من حفظها حفظ دينه ومن ضيعها ضيع دينه، نسأل الله العافية.\nفالواجب على كل مسلم أن يحذر تركها والتساهل بها، على الجميع رجالاً ونساء أن يتقوا الله، وأن يحافظوا على الصلوات الخمس في أوقاتها، وأن يؤديها الرجل في الجماعة، هذا هو الواجب على الجميع، فمن ضيعها وتهاون بها وتركها كفر نسأل الله العافية في أصح قولي العلماء.\nأما من جحد وجوبها وقال: ما هي بواجبة، هذا يكفر عند الجميع عند جميع الأمة عند جميع أهل العلم، من قال: إنها غير واجبة أو إن واحدة منها غير واجبة كالظهر أو العصر أو المغرب أو العشاء أو الفجر كفر إجماعاً، أما إذا كان يؤمن بأنها واجبة ولكن يتساهل ويتركها أو بعضها فإنه يكفر بذلك نسأل الله العافية، أما إن كان يصلي لكن في البيت فهذا يكون عاصي وعليه التوبة إلى الله وأن يصلي في الجماعة، وصلاته مجزئة لا يعيدها لكن عليه أن يصلي في الجماعة ويتوب مما سلف، إذا كان لا يصلي في الجماعة بل يصلي في البيت يجب أن يصلي مع الجماعة، وأن يتوب إلى الله مما سلف.\nأما النساء فعليهن الصلاة في البيت، السنة لهن الصلاة في البيوت، ومن صلت مع الجماعة صلاتها صحيحة، لكن الأفضل في حق النساء الصلاة في البيت. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8494/حكم-من-تاب-من-ترك-الصلاة-والصيام-كسلا-وجهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها","الرقائق"]},{"id":10408,"question":"مستمع مواطن مصري الجنسية مقيم في العراق يقول: لقد أصابني حريق في شهر رمضان ولم أستطع الصيام، والطبيب الذي كان يشرف على علاجي كان طبيبًا مسلمًا ونصحني بعدم الصيام، لم أطعم مساكين لحالتي المادية الضعيفة، وجهوني كيف أتصرف جزاكم الله خيرًا؟","title":"من أفطر رمضان بسبب المرض","answer":"الجواب: إذا كنت تستطيع الصيام تصوم تقضي والحمد لله، وإن كنت لا تستطيع الآن فيؤجل حتى تستطيع، وإذا استطعت تصوم والحمد لله وليس عليك شيء فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] الله يقول سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] والحرق الذي أصابك نوع من المرض.\nأما إن قرر الأطباء أنك لا تستطيع الصوم وأن هذا المرض مستمر وأنه صار هذا المرض ملازم ما في حيلة فيما يظهر لهم، فإنك تطعم عن كل يوم مسكين، من الأيام التي أفطرتها نص صاع من التمر أو نحوه كالرز والحنطة ويكفي إذا كنت عاجزًا عن الصيام، حسب تقرير الأطباء أن هذا المرض الذي حصل بسبب الحريق ملازم ولا يرجى برؤه ويشق عليك الصوم معه تطعم عن كل يوم مسكينًا من قوت البلد نصف صاع من قوت البلد.\nأما إذا قدرت فإنك تصوم، وإذا أخرت الصيام مع القدرة حتى جاء رمضان الآخر يكون عليك إطعام مع الصيام زيادة، تصوم وتطعم عن كل يوم مسكين؛ لأنه لا يجوز تأخير الصيام إلى رمضان الآخر وأنت قادر. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/8581/من-افطر-رمضان-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34015.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10426,"question":"حدثونا لو تكرمتم عن امرأة عليها أيام من شهر رمضان من عامين أو ثلاثة أيام، هل تؤدي ما عليها من أيام فقط، أم عليها كفارة؟ وما كفارتها؟","title":"حكم من أخرت قضاء رمضان حتى دخل عليها رمضان الآخر","answer":"الجواب: إذا أخر الإنسان الصيام عاماً أو أكثر من دون عذر فعليه التوبة إلى الله والندم والعزم أن لا يعود، وعليه القضاء وعليه الكفارة جميعاً ثلاثة أشياء: التوبة، وقضاء الأيام التي على الإنسان من رجل أو امرأة، وإطعام مسكين عن كل يوم، أما إن كان لعذر كالمرض فلا شيء عليها إلا القضاء فقط، وأما التساهل فعليه القضاء، وعليه التوبة إلى الله، وعليه إطعام مسكين عن كل يوم بحسب الأيام، كل يوم عليه نصف صاع يجمعها ويعطيها بيتاً فقيراً أو شخصاً فقيراً كلها، لا بأس يجمعها ويعطيها بعض الفقراء في أول الشهر أو في آخره، في أول الصيام أو في آخر الصيام، هذا إذا كان أخرها عاماً أو أكثر، أما إذا كان قضاها في العام قبل رمضان الآخر، في نفس العام قضى.. هذا ما عليه إلا القضاء وليس عليه إطعام. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8602/حكم-من-اخرت-قضاء-رمضان-حتى-دخل-عليها-رمضان-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31709.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10463,"question":"من إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ص. هـ. ي) من الرياض تقول في أحدها: اشتد علي العطش في يوم رمضان، وكنت أقوم برعي الغنم في البادية، فأغمي علي وأفطرت، ماذا علي حينئذٍ، جزاكم الله خيراً؟","title":"حكم من أفطر في رمضان مضطراً","answer":"الجواب: لا شيء من أجل الضرورة، لكن عليك القضاء، .. لأن الإنسان إذا اضطر إلى الفطر أفطر ويمسك، إذا اشتد بالإنسان ظمأ يشرب ما يسد ما يزيل الظمأ ثم يمسك إلى الغروب ويقضي، وهكذا لو أصابه جوع شديد وأكل خوفاً من الخطر يقضي بعد ذلك، يمسك ويقضي فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8646/حكم-من-افطر-في-رمضان-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32012.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10472,"question":"يقول: أفطرت بعض أيام من رمضان وحينئذٍ تأخرت في القضاء، وبدأت أقضيها الآن، فماذا علي، جزاكم الله خيراً؟","title":"حكم من أفطر في رمضان وأخر القضاء حتى رمضان الآخر","answer":"الجواب: إذا كنت قضيتها قبل رمضان الثاني فليس عليك إلا القضاء الحمد لله، أما إذا كنت أخرتها بعد رمضان فعليك مع القضاء إطعام مسكين عن كل يوم مع التوبة والاستغفار، وهو إطعام مسكين يعني: نص صاع تمر أو رز أو غيره من قوت البلد مقداره كيلو ونص تقريباً مع التوبة والاستغفار والصيام، إذا كنت أخرتها بغير عذر لا مرض ولا عذر آخر كالسفر، فالإنسان إذا أخر الصيام عن السنة إلى رمضان الآخر فإنه يكون قد أتى معصية، فعليه التوبة إلى الله، وعليه القضاء وعليه إطعام مسكين عن كل يوم، أفتى به جماعة من الصحابة  وأرضاهم كالتعزير. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8644/حكم-من-افطر-في-رمضان-واخر-القضاء-حتى-رمضان-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32010.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10593,"question":"من جامعة الملك فهد للبترول والمعادن أحد الإخوة المستمعين سمى نفسه منصور بعث برسالة وضمنها قضية يقول فيها: قبل سنوات قليلة حوالي ثلاث أو أربع سنوات كنت أجهل الكثير من أحكام الصيام والعقوبات المترتبة على من خالف أحد هذه الأحكام، كنا ثلاثة إخوة بالغين، وكان إذا جاء رمضان صمنا بعض أيامه الأولى، ثم أفطرنا البعض بجهل تام منا بالعقوبة الوخيمة المترتبة على الإفطار المتمثلة بالحديث الذي معناه: «من أفطر يوماً من رمضان لم يجزئه صيام الدهر كله وإن صامه» الحديث قلته بالمعنى، أفيدوني كيف نتصرف جزاكم الله خيراً؟","title":"ما يلزم من أفطر في رمضان عمداً وهو جاهل","answer":"الجواب: عليكم التوبة إلى الله والندم، والعزم الصادق أن لا تعودوا، وعليكم قضاء الأيام التي أفطرتموها كلكم، والحديث المذكور حديث ضعيف ليس بصحيح عند أهل العلم حديث مضطرب، ويكفي أن يصوم مع التوبة، من صام يوماً بدل يوم كفى والحمد لله، شهر بدل شهر كفى والحمد لله مع التوبة إلى الله، وأما الحديث الذي ذكره السائل: من أفطر يوماً عمداً بغير عذر لم يقضه صوم الدهر وإن صامه، حديث ضعيف ذكر المحققون من أهل العلم أنه مضطرب لا يثبت، ولو صح لكان من باب الوعيد والتحذير، وإلا فاليوم يكفي، قال الله تعالى: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، وهكذا من أفطر عمداً عليه عدة من أيام أخر مع التوبة إلى الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8770/ما-يلزم-من-افطر-في-رمضان-عمدا-وهو-جاهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32508.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10597,"question":"من جامعة الملك فهد للبترول والمعادن أحد الإخوة المستمعين سمى نفسه منصور بعث برسالة وضمنها قضية يقول فيها: قبل سنوات قليلة حوالي ثلاث أو أربع سنوات كنت أجهل الكثير من أحكام الصيام والعقوبات المترتبة على من خالف أحد هذه الأحكام، كنا ثلاثة إخوة بالغين، وكان إذا جاء رمضان صمنا بعض أيامه الأولى، ثم أفطرنا البعض بجهل تام منا بالعقوبة الوخيمة المترتبة على الإفطار المتمثلة بالحديث الذي معناه: «من أفطر يوماً من رمضان لم يجزئه صيام الدهر كله وإن صامه» الحديث قلته بالمعنى، أفيدوني كيف نتصرف جزاكم الله خيراً؟","title":"ما يلزم من أفطر في رمضان عمداً وهو جاهل","answer":"الجواب: عليكم التوبة إلى الله والندم، والعزم الصادق أن لا تعودوا، وعليكم قضاء الأيام التي أفطرتموها كلكم، والحديث المذكور حديث ضعيف ليس بصحيح عند أهل العلم حديث مضطرب، ويكفي أن يصوم مع التوبة، من صام يوماً بدل يوم كفى والحمد لله، شهر بدل شهر كفى والحمد لله مع التوبة إلى الله، وأما الحديث الذي ذكره السائل: من أفطر يوماً عمداً بغير عذر لم يقضه صوم الدهر وإن صامه، حديث ضعيف ذكر المحققون من أهل العلم أنه مضطرب لا يثبت، ولو صح لكان من باب الوعيد والتحذير، وإلا فاليوم يكفي، قال الله تعالى: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، وهكذا من أفطر عمداً عليه عدة من أيام أخر مع التوبة إلى الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8770/ما-يلزم-من-افطر-في-رمضان-عمدا-وهو-جاهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32508.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10615,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من المستمع (ع. م.هـ) من معهد الدلم العلمي، أخونا ضمن رسالته جمعاً من الأسئلة، في أحدها يقول: إنني في شهر رمضان المبارك قبل سنتين ذهبت إلى مكة المكرمة لأداء مناسك العمرة، فاضطررت للإفطار في اليوم الذي ذهبت فيه، وكان يجب علي أن أصومه فيما بعد -أي: بعد شهر رمضان المبارك- ولكنني تهاونت، فجاء شهر رمضان بالسنة المقبلة ولم أصم ذلك اليوم، فقلت بعد هذا الشهر، ولكن مرت الأيام ولم أصمه، كل يوم أقول: غداً، حتى جاء شهر رمضان للسنة الثانية ولم أصمه حتى هذا اليوم، ولكنني تنبهت لهذا الأمر، فقررت أن أصومه، ولكن هل أصوم يوماً واحداً؟ أم علي صيام أيام تكفيراً، ما هو الحكم ، وأنا في انتظار إجابتكم، جزاكم الله خيراً؟","title":"حكم من أفطر من رمضان ولم يقضه حتى جاء رمضان الآخر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب قضاء يوم واحد؛ لأن الله سبحانه يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فأنت عليك قضاء يوم واحد مع التوبة والاستغفار؛ لأجل تفريطك في التأخير، وعليك مع ذلك إطعام مسكين نصف صاع من تمر أو أرز مقدار كيلو ونصف تقريباً، يدفع لبعض الفقراء، مع التوبة والاستغفار، والحمد لله.\nالمقدم: الحمد لله، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8789/حكم-من-افطر-من-رمضان-ولم-يقضه-حتى-جاء-رمضان-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32701.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10713,"question":"من الجمهورية العربية السورية الأخت السائلة نورا محمد بعثت تقول: إنني لم أستطع صيام شهر رمضان المبارك، بسبب الحمل، وقد نويت على الصيام بعد الولادة، ولكن بعد الولادة إرضاع فلم أستطع الصيام، بسبب الإرضاع كما قلت، ولأن جسمي لا يتحمل الصيام، أفيدونا أفادكم الله، هل تجوز الصدقة عن الصيام، أم يجب أن أصوم الشهر الذي فاتني وأنا لا أستطيع؟ بماذا ترشدوني جزاكم الله خيراً؟","title":"حكم من عجزت عن الصوم وقضائه بسبب الحمل والرضاع","answer":"الجواب: عليك الصيام عند الاستطاعة: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فالمرضعة والحامل مثل المريض، إذا شق عليهما الصيام أجلا الصيام ولو بعد رمضان آخر، ما دمت لا تستطيعين من أجل الرضاع، فأنت معذورة كالمريضة، فإذا يسر الله لك الصيام ولو مفرقاً، يوم تصومين ويومين تفطرين، وثلاثة تفطرين، وأربعة تفطرين، فلا بأس، ليس بلازم المتابعة، لا بأس بالتفرقة، فإذا عجزت أجلي والحمد لله، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8895/حكم-من-عجزت-عن-الصوم-وقضاىه-بسبب-الحمل-والرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34310.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10714,"question":"من الجمهورية العربية السورية الأخت السائلة نورا محمد بعثت تقول: إنني لم أستطع صيام شهر رمضان المبارك، بسبب الحمل، وقد نويت على الصيام بعد الولادة، ولكن بعد الولادة إرضاع فلم أستطع الصيام، بسبب الإرضاع كما قلت، ولأن جسمي لا يتحمل الصيام، أفيدونا أفادكم الله، هل تجوز الصدقة عن الصيام، أم يجب أن أصوم الشهر الذي فاتني وأنا لا أستطيع؟ بماذا ترشدوني جزاكم الله خيراً؟","title":"حكم من عجزت عن الصوم وقضائه بسبب الحمل والرضاع","answer":"الجواب: عليك الصيام عند الاستطاعة: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فالمرضعة والحامل مثل المريض، إذا شق عليهما الصيام أجلا الصيام ولو بعد رمضان آخر، ما دمت لا تستطيعين من أجل الرضاع، فأنت معذورة كالمريضة، فإذا يسر الله لك الصيام ولو مفرقاً، يوم تصومين ويومين تفطرين، وثلاثة تفطرين، وأربعة تفطرين، فلا بأس، ليس بلازم المتابعة، لا بأس بالتفرقة، فإذا عجزت أجلي والحمد لله، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8895/حكم-من-عجزت-عن-الصوم-وقضاىه-بسبب-الحمل-والرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34310.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10867,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. أ. ح) من مدينة جدة مفهوم ما في هذه الرسالة يقول: كان النساء لا يقضين ما أفطرنه من رمضان بسبب أعذارهن الشرعية، كالحيض مثلًا، والآن اكتشفن أنهن كن على خطأ، بم تنصحونهن؟ جزاكم الله خيرًا، ولا سيما أنهن لا يعلمن عدد الرمضانات التي أفطرن فيها.","title":"حكم من نسيت عدد ما أفطرته في رمضان","answer":"الجواب:  عليهن أن يقضين ما يغلب على الظن أنهن تركنه من الصيام، والله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فعليهن أن يتحرين ما أفطرن فيه، ويقضينه، ويطعمن عن كل يوم مسكينًا، زيادة مع القضاء إذا كن قادرات على الطعام، كل يوم عنه إطعام مسكين، نصف صاع من التمر، أو الأرز، أو الحنطة، أو الشعير حسب الطاقة، وإذا كن لا يستطعن الطعام كفى الصيام، والحمد لله؛ لأن الله يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]. والحائض كذلك، والنفساء كذلك كالمريض يقضي، تقضي الصوم كما يقضي المريض، والمسافر، وإذا نسيت العدد فإنها تتحرى في غالب ظنها، وتصوم، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9039/حكم-من-نسيت-عدد-ما-افطرته-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35707.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11056,"question":"بعد هذا ننتقل إلى سلطنة عمان عبر رسالة بعث بها المستمع: محمد بن سالم، أخونا له جمع من الأسئلة من بينها سؤال يقول فيه: تهاونت في الصيام في بعض الأيام في أشهر مضت من رمضان حيث أفطرت عمدًا، وقبل رمضانين التزمت وتبت ولزمت، ثم إني عزمت على عدم العودة إلى التهاون في رمضان، هل تجزئ هذه التوبة، أم تلزمني الكفارة؟ علمًا بأني قد نسيت عدد الأيام التي أفطرتها؟","title":"حكم من أفطر أياماً من رمضان عمداً ولا يعلم عددها","answer":"الجواب:  التوبة يمحو الله بها الذنب، ولك فيها الأجر العظيم، كما قال الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وقال النبي ﷺ: التائب من الذنب كمن لا ذنب له، وقال -عليه الصلاة والسلام-: التوبة تهدم ما قبلها، وعليك قضاء الأيام لقول الله  في المريض والمسافر: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، فتقضي حسب ظنك هذا هو الأحوط لك، وإن كنت قد تبت فعليك أن تقضيها حسب ظنك، فإذا كنت تظنها عشرة أيام اقض عشرة، عشرين عشرين، وهكذا.. اعمل بظنك إذا كنت لا تستطيع الجزم، والله -جل وعلا- يعفو عما سلف بالتوبة الصحيحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9234/حكم-من-افطر-اياما-من-رمضان-عمدا-ولا-يعلم-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36707.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11104,"question":"تقول: في بداية حياتي كنت معذورة شرعًا، ولكنني لم أقض الأيام التي أفطرتها في رمضان، لجهلي بكثير من الأحكام، وبما فطر عليه النساء، والآن أريد أن أقضي تلك الأيام، لكني لا أعرف عددها، ولا كم هي، فكيف توجهونني، وهل يلزمني مع الصيام أشياء أخرى؟ جزاكم الله خيرًا.","title":"عليه أيام من رمضان لا يعرف عددها فماذا يفعل؟","answer":"الجواب:  عليك التوبة إلى الله النصوح، والصدق وبالندم والحزن على ما جرى منك، والعزيمة الصادقة أن لا تعودي في ذلك، وعليك القضاء بحسب ظنك، إذا لم تعلمي عليك العمل بالظن، تحسبين الأيام التي عليك، عشرين يومًا، ثلاثين يومًا، أربعين يومًا التي أفطرت، الأيام التي أفطرتيها من رمضان، عليك أن تقضيها، مع إطعام مسكين عن كل يوم إذا كنت قادرة. أما إن كنت فقيرة ما تستطيعين فإنه يكفي الصيام، أما مع الاستطاعة تطعمين عن كل يوم مسكينًا، كيلو ونصف عن كل يوم، نصف صاع يعني، فعن اليومين صاع، وعن.. الأربعة صاعان وهكذا، تعطيها بعض الفقراء، قبل الصيام، أو بعد الصيام، ولو فقيرًا واحدًا، تجمع ويعطاها فقير أو فقيران، أو أهل بيت فقير يكفي هذا، والحمد لله، مع التوبة والاستغفار والندم وعدم العود، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9298/عليه-ايام-من-رمضان-لا-يعرف-عددها-فماذا-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36816.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11120,"question":"تقول: في بداية حياتي كنت معذورة شرعًا، ولكنني لم أقض الأيام التي أفطرتها في رمضان، لجهلي بكثير من الأحكام، وبما فطر عليه النساء، والآن أريد أن أقضي تلك الأيام، لكني لا أعرف عددها، ولا كم هي، فكيف توجهونني، وهل يلزمني مع الصيام أشياء أخرى؟ جزاكم الله خيرًا.","title":"عليه أيام من رمضان لا يعرف عددها فماذا يفعل؟","answer":"الجواب:  عليك التوبة إلى الله النصوح، والصدق وبالندم والحزن على ما جرى منك، والعزيمة الصادقة أن لا تعودي في ذلك، وعليك القضاء بحسب ظنك، إذا لم تعلمي عليك العمل بالظن، تحسبين الأيام التي عليك، عشرين يومًا، ثلاثين يومًا، أربعين يومًا التي أفطرت، الأيام التي أفطرتيها من رمضان، عليك أن تقضيها، مع إطعام مسكين عن كل يوم إذا كنت قادرة. أما إن كنت فقيرة ما تستطيعين فإنه يكفي الصيام، أما مع الاستطاعة تطعمين عن كل يوم مسكينًا، كيلو ونصف عن كل يوم، نصف صاع يعني، فعن اليومين صاع، وعن.. الأربعة صاعان وهكذا، تعطيها بعض الفقراء، قبل الصيام، أو بعد الصيام، ولو فقيرًا واحدًا، تجمع ويعطاها فقير أو فقيران، أو أهل بيت فقير يكفي هذا، والحمد لله، مع التوبة والاستغفار والندم وعدم العود، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9298/عليه-ايام-من-رمضان-لا-يعرف-عددها-فماذا-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36816.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11291,"question":"من المستمعة (ج. هـ) من القصيم رسالة وضمنتها سؤالين، في سؤالها الأول تقول: قبل ثلاث سنوات كنت مسرفة على نفسي كثيرًا، وكنت مفرطة في الصلوات وفي الصوم، ولكن أنا الآن نادمة وتائبة، وسؤالي: كنت في أيام الغفلة ومضى علي سنتان وأنا لم أصم ولا أصلي، فهل يجب علي قضاء ما فات من صلاة وصيام؟أم كيف توجهونني؟ جزاكم الله خيرًا,","title":"حكم قضاء الصلاة والصيام على من تركها","answer":"الجواب: الصواب التوبة كافية إن شاء الله، ولا قضاء عليك، لا قضاء عليك والحمد لله، التوبة كافية، يقول النبي ﷺ: التوبة تجب ما قبلها.  والتائب من الذنب كمن لا ذنب له فلا قضاء عليك لا للصلاة ولا للصيام؛ لأن ترك الصلاة كفر، والكافر إذا أسلم لا يقضي ما مضى، قال الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [لأنفال: 38]، يغفر لهم ما قد سلف. فالمرتد لا يقضي ما سلف ولكن عليه التوبة والاستقامة والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9483/حكم-قضاء-الصلاة-والصيام-على-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37615.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":11343,"question":"تقول عندما كنت صغيرة لم أكن أهتم بقضاء الصيام عندما أفطر للعذر الشرعي والآن تذكرت، لكني لا أدري كم هي المدة التي لم أصمها، وكم هي عدد الأشهر التي أفطرت فيها، فبماذا تنصحونني الآن، وهل علي كفارة وقضاء؟ جزاكم الله خيرًا.","title":"حكم من أفطرت أياماً في عدة رمضانات لعذر ولم تقضها","answer":"الجواب:  عليك أن تصومي بالتحري والظن جميع الأيام التي أفطرتيها، عليك أن تتحري وتعملي بالظن حتى تصومي جميع الأيام ولو مفرقة غير متتابعة ولو مفرقة، مع التوبة الصادقة إلى الله مع التوبة النصوح والندم على ما مضى منك والعزم ألا تعودي في هذا الشيء ومع إطعام مسكين عن كل يوم نصف صاع عن كل يوم تجمعيها وتعطيها بعض الفقراء، فقير أو فقيرين أو أكثر، مع التوبة الصادقة والندم وعدم العود. نعم. المقدم: جزاكم الله خيرًا، إذًا عليها مع القضاء كفارة؟ الشيخ: نعم إطعام مسكين عن كل يوم. المقدم: بارك الله فيكم وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9540/حكم-من-افطرت-اياما-في-عدة-رمضانات-لعذر-ولم-تقضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37817.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11357,"question":"تقول عندما كنت صغيرة لم أكن أهتم بقضاء الصيام عندما أفطر للعذر الشرعي والآن تذكرت، لكني لا أدري كم هي المدة التي لم أصمها، وكم هي عدد الأشهر التي أفطرت فيها، فبماذا تنصحونني الآن، وهل علي كفارة وقضاء؟ جزاكم الله خيرًا.","title":"حكم من أفطرت أياماً في عدة رمضانات لعذر ولم تقضها","answer":"الجواب:  عليك أن تصومي بالتحري والظن جميع الأيام التي أفطرتيها، عليك أن تتحري وتعملي بالظن حتى تصومي جميع الأيام ولو مفرقة غير متتابعة ولو مفرقة، مع التوبة الصادقة إلى الله مع التوبة النصوح والندم على ما مضى منك والعزم ألا تعودي في هذا الشيء ومع إطعام مسكين عن كل يوم نصف صاع عن كل يوم تجمعيها وتعطيها بعض الفقراء، فقير أو فقيرين أو أكثر، مع التوبة الصادقة والندم وعدم العود. نعم. المقدم: جزاكم الله خيرًا، إذًا عليها مع القضاء كفارة؟ الشيخ: نعم إطعام مسكين عن كل يوم. المقدم: بارك الله فيكم وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9540/حكم-من-افطرت-اياما-في-عدة-رمضانات-لعذر-ولم-تقضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37817.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11367,"question":"سؤالها الثاني تقول: بأن والدتي عندما توفت كان عليها قضاء لصيام شهر رمضان ولا نعلم كم عدد هذه الأيام لكثرة إفطارها بسبب مرض الربو وكانت تنوي القضاء ولكنها ماتت، ماذا يلزمنا سماحة الشيخ؟","title":"كيفية الصيام عن مات ولا يُعلم عدد الأيام التي أفطرها","answer":"الجواب:  يشرع لكم الصيام عنها، يشرع لكم الصيام عنها حسب الظن، تجتهدون وتصومون ما يغلب على الظن أنها أفطرته من رمضان وأنتم مأجورون، يقول النبي ﷺ: من مات وعليه صيام صام عنه وليه يعني: قريبه. فالأفضل لكم أن تصوموا عنها ما تيسر أنت وأخواتك أو واحدة منكن تصوم عنها حسب الظن، إذا ظننتم أنها عشرة أيام صوموا عشرة، ظننتم أنها خمسة عشر صوموا خمسة عشر، وهكذا بالظن ويكفي هذا، وإن تصدقتم عنها عن كل يوم طعام مسكين كفى، لكن صومكم عنها أفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9549/كيفية-الصيام-عن-مات-ولا-يعلم-عدد-الايام-التي-افطرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29310.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11404,"question":"تقول: ذهبت مني تقريبًا ستون يومًا صيامًا من خلال وضع الحمل أربعة أطفال، وإنني جسديًا غير متمكنة، وغير قادرة على الصيام، فارشدوني ماذا أعمل؟ جزاكم الله خيرًًا.","title":"حكم من أفطرت بسبب الحمل ولم تستطع القضاء","answer":"الجواب:  إذا كنت أفطرت في الحمل هذا ستين يومًا؛ فعليك القضاء، وإذا كنت مريضة؛ حتى تشفي -إن شاء الله- أما إن كنت قد عجزت، وعجزت عن الصيام لأجل كبر سنك؛ فعليك الإطعام عن كل يوم، إطعام مسكين نصف صاع عن كل يوم تجمعينه وتعطيه لبعض الفقراء. أما إذا كنت تستطيعين الصوم؛ فعليك الصوم، عليك أن تقضي ولو مفرقاً غير متتابع، وعليك مع ذلك إطعام مسكين عن التأخير، إذا قد أخرت، وأنت قادرة؛ عليك إطعام مسكين بعدد الأيام نصف صاع عن كل يوم، يجمع ويعطاه بعض الفقراء، ولا يجوز التساهل في هذا الأمر، هذه أمور عظيمة، فريضة صوم رمضان ركن في الإسلام، فالواجب العناية بهذا الأمر، إن كنت قادرة؛ فبادري بالصوم، وإن كنت عاجزة؛ يؤجل حتى تشفي من مرضك، الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، أما إذا كان تساهلًا؛ فعليك التوبة إلى الله، والندم، والإقلاع، والبدار بالصوم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9583/حكم-من-افطرت-بسبب-الحمل-ولم-تستطع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38004.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":11446,"question":"بعد هذا رسالة بعث بها المستمع محمد أحمد سيد أحمد سوداني، يقول: لقد حل علي شهر رمضان، وصمت منه اثنين وعشرين يومًا، وأفطرت الأيام الباقية، وذلك لسخونة الجو، وللعمل الشاق، فكيف أقضي ما فاتني؟ أفيدوني أفادكم الله.","title":"حكم من أفطر أياماً من رمضان لمشقة العمل وسخونة الجو","answer":"الجواب:  عليك التوبة والاستغفار، وعليك القضاء، سواءً جمعت، أو فرقت، الأيام الباقية عليك أن تقضيها مجتمعة، أو مفرقة، لا بأس، وأما العمل وسخونة الجو لا يبيح لك الإفطار، تستريح وتصوم، تستريح من العمل، وتصوم، والحمد لله، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا، الذين يفتون يا سماحة الشيخ بأن العمل الشاق، أو أن سخونة الجو تبيح الإفطار.  الشيخ: ليس بعذر، لا، ليس بعذر، كل هذه لها علاج، يجلس في المحل الذي يرى أنه مناسب، ويستريح، وبقية المدة تسد على بقية الأيام هذه، الحمد لله لا يتعلق بالعمل، نعم، العمل يستريح منه، أو يؤجل، أو يستقيل، أو يكون في وقت خاص قليل لا يضره، نعم. المقدم: نعم، أو ينقله إلى الليل؟ الشيخ: أو ينقله إلى الليل كله طيب، كله طيب. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9627/حكم-من-افطر-اياما-من-رمضان-لمشقة-العمل-وسخونة-الجو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38103.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11478,"question":"من منطقة عشيرة إحدى الأخوات المستمعات تقول، الرمز (س. ح. ف) تسأل وتقول: إنني مريضة قبل عشرين عامًا، وأفطرت بعض أيام من شهر رمضان، وأنا لا أدري الآن كم عدد تلك الأيام، وصمت الآن عشرة أيام، ولا أدري أهي أكثر، أم أقل، فبماذا توجهونني الآن؟ جزاكم الله خيرًا.","title":"حكم من أفطر أياماً من رمضان لمرض ونسي عدد الأيام","answer":"الجواب:  عليك أن تصومي ما يغلب على ظنك حتى تكملي، إذا كان يغلب على ظنك أنها خمسة عشر؛ كملي بخمسة أيام، وهكذا، تحري بغلبة الظن، ويكفي، والحمد لله، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا، تقول: إنها صامت الآن عشرة، هل تنصحونها بشيء آخر سماحة الشيخ؟ الشيخ: نعم تنظر، تتأمل، فإن ذكرت أنها خمسة عشر؛ تكمل ثلاثة عشر؛ تكمل سبعة عشر، وهكذا، بغالب الظن. المقدم: وإن اعتقدت أنها عشرة فقط، فتكتفي؟ الشيخ: فقد انتهت، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9666/حكم-من-افطر-اياما-من-رمضان-لمرض-ونسي-عدد-الايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38212.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11538,"question":"يسأل أخونا ويقول: شاب مراهق أفطر ثلاثة أيام من رمضان؛ لأنه بذل مجهودًا عضليًا كبيرًا، ولم يستطع أن يكمل صيامه لرغبته الشديدة في الماء، فما هو الحل؟ هل يصوم عن كل يوم ستين يومًا متتالية، أم ماذا يفعل؟ مع العلم بأنه محافظ الآن على صيام رمضان، وصيام الإثنين والخميس جزاكم الله خيرًا.","title":"كيفية قضاء من أفطر من رمضان بسبب شدة العطش","answer":"الجواب:  إذا كان أفطر؛ لأنه لم يستطع إكمال الصوم بسبب شدة الظمأ، بسبب الإرهاق الذي أصابه، وخاف على نفسه الموت، أو مرض شديد، فهذا له عذر، وليس عليه إلا أن يقضي يومًا بدل اليوم، يعني: ثلاثة أيام بدل ثلاثة أيام فقط لا زيادة، إذا كان فطره بالماء. أما إذا كان فطره بالجماع؛ فهذا شيء آخر، لكن إذا كان فطره بالماء؛ فعليه قضاء اليوم فقط، والحمد لله. أما إذا كان تساهل وإلا ما هناك ضرورة؛ فعليه التوبة مع القضاء، قضاء يوم فقط، عن كل يوم يوم، ثلاثة ثلاثة، مع التوبة إلى الله، أما إن كان الأمر خطيرًا، يعني أصابه شدة عظيمة، وخاف من مرض شديد، أو من موت؛ فهذا عذر، الله يقول -جل وعلا-: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]. نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ قد يفطر بعض الناس لأمر ما، كهذا الأمر الذي حل بأخينا، فإذا ما أفطر لا يستمر في صيامه بعد ذلك، بل يستمر مفطرًا، فيأكل ويشرب ويستبيح المأكولات؟ الجواب: لا يجوز له، يفطر بقدر الحاجة، يشرب، ثم يمسك إذا كان من أجل الظمأ، يأكل ما يسد رمقه إذا كان الخطر من أجل الجوع، ثم يمسك حتى غروب الشمس، ما يستمر في الفطر، إنما أكل وشرب الضرورة، ثم يستمر، وهكذا لو أن الإنسان أراد إنقاذ إنسان من غرق، أو من عدو، ولم يستطع إلا بالفطر؛ أفطر، وأنقذ أخاه، ثم أمسك، أمسك إلى غروب الشمس، وقضى اليوم فقط، يقضي اليوم فقط؛ لأنه أفطر للضرورة نعم؛ لأن إنقاذ المسلم واجب، إنقاذ أخيه المعصوم واجب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9721/كيفية-قضاء-من-افطر-من-رمضان-بسبب-شدة-العطش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29504.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11892,"question":"رسالة من إحدى الأخوات المستمعات تقول أم عبدالعزيز وعلي: لها جمع من الأسئلة تقول في أحدها: توفي جدي لأبي، وعليه صيام من رمضان، وقمت أنا وأبي بالصيام عنه، أنا ثمان وأبي ثمان، فهل يصح ذلك؟ جزاكم الله خيرًا.","title":"حكم صيام المرأة عن جدها الذي مات وعليه صوم","answer":"الجواب:  مشكور جزاكم الله خير طيب، يقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه يعني: قريبه، فإذا قضيت أنت والأب ما على الميت؛ جزاكم الله خيرًا هذا عمل مشكور، ومأجور، وينفع الميت.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10076/حكم-صيام-المراة-عن-جدها-الذي-مات-وعليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42513.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12130,"question":"إحدى الأخوات المستمعات تقول أم حسن تقول: إنها كانت تضع مواليدها في رمضان، ولم تقض، ولم تدر عدد ما فاتها من الأيام، فكيف تتصرف الآن؟ جزاكم الله خيرًا.","title":"حكم من أفطرت في رمضان لعذر ولم تدر عدد الأيام","answer":"الجواب:  تعمل بغالب ظنها، عليها أن تعمل بغالب ظنها، عليك يا أم حسن أن تعملي بغالب الظن في قضاء الأيام التي أفطرت من رمضان، اعملي بغالب الظن، والحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إذا غلب على ظنك أنك أفطرت عشرة أيام، خمسة عشر يومًا؛ فاقضيها من كل سنة، حتى تكملي، سواءً قضيتيها متتابعة، أو مفرقة؛ لا بأس، اعملي بالظن، ويكفيك هذا، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10315/حكم-من-افطرت-في-رمضان-لعذر-ولم-تدر-عدد-الايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43815.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12305,"question":"علي قضاء أربعة رمضانات بعيدة جدًا، ولا أذكر عدد الأيام التي أفطرت فيها، علمًا بأنني أصبحت أقضي ما علي من صيام أولًا بأول، لكن تلك الأيام الماضية يقلقني أنني لم أقضها، ولم أدر ما مقدارها، وهي أربعة رمضانات كما قلت، فكيف تنصحونني؟","title":"حكم من أفطرت في رمضان ولا تعلم عدد الأيام","answer":"الجواب:  ننصحك بأن تقضي هذه الأيام التي عليك بحسب الظن، يجب عليك أن تقضي ما أفطرت فيه بحسب الظن، وتحتاطي، فإذا كنت تظنين من كل سنة سبعة أيام، أو ثمانية أيام؛ اجعليها ثمانية، وإذا كنت تشكين هل ثمانية، أو تسعة؛ اجعليها تسعة، اعملي بالاحتياط، وصوميها كلها، وأطعمي عن كل يوم مسكينًا أيضًا زيادة؛ لتفريطك وتأخيرك للصيام، وهو نصف صاع، عن كل يوم كيلو ونصف تقريبًا من تمر، أو حنطة، أو أرز، هكذا أفتى جمع من الصحابة -رضي الله عنهم وأرضاهم- في حق من أخر الصيام إلى رمضان آخر أنه يطعم مع القضاء، إذا لم يكن له عذر، وأنت أخرت بلا عذر سنوات. فالواجب عليك التوبة إلى الله، والقضاء مع إطعام مسكين عن كل يوم في الأيام الماضية كلها، والله يعينك ويهديك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10505/حكم-من-افطرت-في-رمضان-ولا-تعلم-عدد-الايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45311.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12349,"question":"هل يجوز قضاء أيام الإفطار من شهر رمضان في العشرة الأيام الأخيرة من شعبان، أو قبلها بالنسبة للمرأة؟","title":"حكم تأخير قضاء رمضان إلى شعبان","answer":"الجواب:  لا حرج بالنسبة للمرأة والرجل جميعًا، يجوز تأخير القضاء إلى شعبان، كانت عائشة تؤخر إلى شعبان -رضي الله عنها-.... والله -جل وعلا- قال: فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] ولم يقل في كذا، ولا في كذا، ولم يقل يجب المبادرة، فدل هذا على التوسعة، فإذا قضى أيام رمضان في شوال، في ذي القعدة، في ذي الحجة، في محرم، في صفر إلى آخره؛ يصح، لا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10551/حكم-تاخير-قضاء-رمضان-الى-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39910.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12370,"question":"إحدى الأخوات المستمعات تقول: (ص. ع. م) مقيمة في الرياض، وهي مصرية تسأل وتقول: أفطرت شهر رمضان كاملًا نظرًا لأنني وضعت حملي الأول، وفي السنة الثانية لنفس العذر أفطرت نصف شهر رمضان، وإلى الآن لم أستطع قضاء ما علي من صيام؛ لأن حالتي الصحية لا تسمح، ما هو مقدار ما علي من إطعام للمساكين؟ أفيدوني جزاكم الله خيرًا.","title":"حكم تأخير قضاء رمضان للحامل والمرضع","answer":"الجواب:  عليك القضاء إذا استطعت بدون إطعام، ما دمت تركت القضاء من أجل العجز؛ فلا بأس أن تقضي إذا وجدت الاستطاعة -عافاك الله- واستطعت تقضين، والحمد لله، وليس عليك إطعام، إلا إذا كنت تساهلت، وتركت القضاء، وأنت تستطيعين، فعليك مع القضاء إطعام مسكين، عن كل يوم نصف صاع، كيلو ونصف عن كل يوم ، تجمع ويعطاها بعض الفقراء، إذا كنت تساهلت، أما إذا كنت أخرت لأجل العجز؛ فليس عليك إلا القضاء إذا استطعت، ولو تأخر سنتين ثلاثًا؛ لا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10580/حكم-تاخير-قضاء-رمضان-للحامل-والمرضع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40018.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12406,"question":"رسالة وصلت إلى البرنامج من الأخ المستمع نور الدين آدم من الجمهورية العربية السورية محافظة الحسكة، قرية هلالية، يقول في رسالته: أنا شاب في السابعة عشرة من العمر، أصلي وأقرأ القرآن، وأبتعد عما هو شر وآثام، ولكن مشكلتي عندما يحين وقت رمضان لا أصوم الشهر؛ وذلك لأنني أعمل أعمالًا شاقة، ولا سيما في أيام الصيف، فهل يجوز لي أن أصوم في أوقات أخرى؟ أو ماذا علي أن أفعل؟أرشدوني جزاكم الله خيرًا.","title":"حكم من ترك الصيام في رمضان بحجة الأعمال الشاقة","answer":"الجواب:  عليك القضاء مع التوبة، تقضي الصيام، وتتوب إلى الله -جل وعلا- وفي المستقبل تصوم مع الناس، وتترك العمل الذي يشق عليك، تعمل أعمالًا لا تشق عليك مع الصوم، فإذا كنت لا تستطيع إلا بترك العمل؛ فاترك العمل، وادخر لرمضان ما يكفيك في رمضان من أعمالك التي في شعبان وقبله، ادخر من نقودك وأجورك التي تحصل لك في شعبان ورجب، وما قبلهما، ادخر منها ما يعينك على صيام رمضان، أو رتب نفسك على عمل لا يشق عليك، وتمكن معه من الصيام، أما التساهل، والحرص على الدنيا، والأعمال الشاقة، وتترك الصوم؛ هذا لا يجوز لك.  فاتق الله ما استطعت، اعمل عملًا قليلًا إذا كنت محتاجًا إليه ليس فيه ما يمنعك من الصوم، وإلا فادخر من أعمالك التي قبل رمضان، ادخر من أجورها ما يعينك على الفراغ للصيام مع المسلمين، نسأل الله لنا ولك الهداية، والتوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا! سماحة الشيخ الذين يفتون العمال، والذين يعملون أعمالًا شاقة بجواز الفطر في رمضان، هل هم على حق؟ الشيخ: لا نعلم لهذا أصلًا أقول ليس له أصل، الواجب أنهم يعملون بقدر الطاقة، وإذا كان لابد من عمل؛ فليؤجلوا العمل إلى بعد رمضان، ويدخروا من أعمالهم السابقة ما يعينهم على صيام رمضان، فالتساهل في هذا شره عظيم، وعاقبته وخيمة.  فالواجب عدم التساهل في هذا الأمر، ولكن إذا تيسر له عمل يستطيع معه الصوم؛ فلا حرج في العمل في رمضان ويصوم، أما إذا كان لابد من الفطر؛ فليترك العمل الذي يلجئه إلى الفطر، وليستعن بالله على صومه بما عنده من المال السابق. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10611/حكم-من-ترك-الصيام-في-رمضان-بحجة-الاعمال-الشاقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45511.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":12564,"question":"أنا آدم جمعة محمد أحمد سوداني الجنسية أبلغ من العمر ثمانًا وثلاثين سنة، قبل بضع سنوات أفطرت رمضان كله بأمر من الدكتور حيث كنت مريضًا، وبعدها أفطرت في رمضان آخر خمسة عشر يومًا لأسباب أخرى، ومر على هذه الأيام سنين، وما قضيتها، وصمت بعدها، وأريد أن أقضيها، فماذا أفعل؟ أفيدوني أثابكم الله.","title":"حكم تأخير قضاء صوم رمضان لعدة سنوات","answer":"الجواب:  عليك القضاء مع التوبة إلى الله -جل وعلا- عما حصل من التأخير، فعليك يا أخي أن تستغفر الله، وتتوب إليه، وتندم على ما فعلت، وعليك أن تقضي هذه الأيام، وأن تطعم مع ... عن كل يوم مسكينًا من قوت البلد، نصف صاع من قوت البلد، فالمعنى: عليك ثلاثة أمور: الأمر الأول: القضاء والمبادرة به. والأمر الثاني: إطعام مسكين عن كل يوم مع القدرة، فإن كنت فقيرًا عاجزًا؛ سقط عنك الإطعام، وبقي عليك الصيام. الأمر الثالث: التوبة إلى الله من هذا التأخير والاستغفار والندم، ومن تاب؛ تاب الله عليه، نسأل الله لنا ولك الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10772/حكم-تاخير-قضاء-صوم-رمضان-لعدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_411/41107.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12701,"question":"يقول: لمرض أصابني لم أصم رمضان لعامين متتالين، ماذا علي أن أفعل؟","title":"حكم من أفطر رمضان في عامين لمرض","answer":"الجواب:  ما دمت أفطرت لعذر شرعي؛ فعليك القضاء، عليك أن تقضي ما أفطرته من العامين، وإذا كان التأخير إلى رمضان الثاني بعذر شرعي؛ فلا شيء عليك سوى الصيام تقضي، أما إذا كنت أخرت من غير عذر، بل تساهلًا منك؛ فعليك مع القضاء إطعام مسكين عن كل يوم، كما أفتى بذلك جمع من الصحابة، من أصحاب النبي ﷺ. أما إن قضيت في العام قبل رمضان؛ فإنك تقضي بدون إطعام، لكن إذا أخرت القضاء إلى رمضان الآخر؛ فعليك القضاء مع الإطعام نصف صاع عن كل يوم من التمر، أو الحنطة، أو الرز مع التوبة والاستغفار.  أما المعذور فلا شيء عليه، إذا أخر من أجل المرض؛ فلا شيء عليه سوى القضاء؛ لأن الله يقول: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] فعليه القضاء فقط. لكن من تساهل، وأمكنه القضاء، ولم يقض حتى جاء رمضان؛ فعليه مع القضاء إطعام مسكين عن كل يوم، مع التوبة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10911/حكم-من-افطر-رمضان-في-عامين-لمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45906.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12727,"question":"مستمع رمز إلى اسمه بالحروف (س. م. ح) من الرياض بعث برسالة، وضمنها سؤالًا طويلًا ملخصًا، سؤالًا يقول: من توفي وعليه صيام أيام أفطرها للسفر، هل يصوم عنه ورثته؟","title":"حكم من مات وعليه صوم أيام أفطرها في السفر","answer":"الجواب:  نعم، إذا كان فرط، إذا كان قدم، ولا صام؛ فالسنة أن يصوموا، أما إذا كان مات في السفر، أو مات من حين قدم، مثل المريض الذي مات في مرضه، أو من حين شفي، مات، ما أمكنه أن يصوم؛ فهو معذور. لكن إذا فرط المريض، أو المسافر بأن شفي المريض؛ قدم من السفر المسافر، ولكن تساهل، ما صام، ثم مات يشرع لأقاربهما أن يصوموا عنهما، لقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه وسأله جماعة هذا يقول: أمي ماتت وعليها صوم شهر، وهذا يقول: أبي مات وعليه صوم شهر، عليه صوم شهرين، فهل أصوم عنه؟ فيقول النبي ﷺ نعم. يجيبهم بنعم. فالسنة لهؤلاء أن يصوموا عن أقاربهم، ويحسنوا إليهم بذلك، إذا كان أقاربه قد فرطوا، يعني: تساهلوا، أما إذا كان مات في مرضه، أو مات في سفره، أو من حين شفي مات، أو من حين قدم مات ما أمكنه؛ فهو معذور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10940/حكم-من-مات-وعليه-صوم-ايام-افطرها-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46015.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12844,"question":"المستمع (ع. ب. ي. أ) بعث برسالة يقول فيها: في الماضي قبل حوالي أربعين سنة تقريبًا كانت الأحوال المادية والاجتماعية سيئة، وأنا أبلغ من العمر الآن ستين سنة، وكان يأتي شهر رمضان، ولا أصوم لعدة أسباب منها: ضعف في الوازع الديني؛ لعدم علمي، ولجهلي في كل أمور الدين؛ ولأني كنت أرعى الغنم في الحر الشديد في الصحراء، فاضطررت للإفطار، استمر هذا الوضع إلى أن أفطرت أربعة شهور، أي: في أربع سنوات، فماذا علي؟ هل علي قضاء، أم أن لي توبة بحكم إقلاعي عن ذلك العمل، ولأنني أبشركم تفقهت، وهداني الله للإسلام، أم ما ذا علي؟ وما صفة القضاء إذا لزم، جزاكم الله خيرًا؟","title":"الواجب على من أفطر عدة رمضانات تساهلًا","answer":"الجواب:  الواجب عليك القضاء مع التوبة إلى الله، والندم، والعزم الصادق على ألا تعود في ذلك، وعليك القضاء للشهور الأربعة، ولا يلزمك التتابع، تقضيها ولو متفرقة، لا يلزم التتابع، تصوم وتفطر حتى تكملها -إن شاء الله- وعليك مع ذلك إطعام مسكينًا، عن كل يوم نصف صاع، كيلو ونصف عن كل يوم تمرًا، أو رزًا، أو حنطة، يعني: نصف صاع من قوت بلدك، والمقدار كيلو ونصف عن كل يوم، مع القدرة، فإن كنت فقيرًا لا تقدر؛ فليس عليك إلا الصوم فقط، تصومها وتستعين بالله -جل وعلا- مع التوبة إلى الله. وهذا هو الواجب على المسلم؛ لأن الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فإذا كان المريض والمسافر يقضي، فالمتساهل يقضي من باب أولى، مع التوبة إلى الله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11058/الواجب-على-من-افطر-عدة-رمضانات-تساهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46410.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12910,"question":"تقول عن نفسها: أنا فتاة بلغت العادة من قبل اثني عشر عامًا، وكنت لا أقضي ما أفطره في رمضان، وقد علمت بالذنب، وتبت إلى الله تعالى، وقررت، بل عاهدت الله: بأن أصوم الشهر، وأقضي الأيام التي أفطرت، ما حكم ذلك؟ هل أقضي السنوات الماضية، أم ماذا أفعل؟ علمًا بأني لا أستطيع القضاء؛ لأن صحتي ضعيفة جدًا، وأيضًا لا أستطيع إطعام كل يوم مسكينًا؛ لأنني فقيرة، لا أملك المال، وجهوني جزاكم الله خيرًا.","title":"حكم من أفطرت في رمضان بسبب العادة الشهرية ولم تقضي","answer":"الجواب:  عليك القضاء متى استطعت، ولو مفرقًا، كلما استطعت تصومين يومًا، يومين ثلاثًا، أربعًا، ثم تفطرين، وهكذا، تصومين بالتدريج حسب القوة والقدرة، كلما استطعت، وكل ما قويت؛ تصومين، والحمد لله، وتضبطين هذا، وتكتبينه، تكتبين ما تصومين حتى تكملي ما عليك، والله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] أبشري بالخير، عليك التوبة الصادقة، والندم، ثم استمري في القضاء، ولو كان قضاءًا متفرقًا على حسب طاقتك، نسأل الله لك العون والتوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11125/حكم-من-افطرت-في-رمضان-بسبب-العادة-الشهرية-ولم-تقضي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46812.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12953,"question":"أيضًا يسأل المستمع (ص. س. س) من جمهورية مصر العربية بعض الأسئلة، من بينها سؤال يقول: لقد وضعت أمي طفلًا في شهر رمضان من مدة طويلة، ولم تصم، ولم تطعم، وهي الآن لا تقدر على ذلك، كيف توجهونها -جزاكم الله خيرًا- هل تصوم ابنتها بدلًا منها؟","title":"حكم من عجز عن قضاء الصيام","answer":"الجواب:  عليها أن تطعم، ويكفي والحمد لله مادامت تعجز عن الصوم، عليها التوبة إلى الله، والندم على ما مضى من عملها السيئ، وعليها أن تطعم عن كل يوم مسكينًا نصف صاع من التمر، أو من قوت البلد كالرز ونحوه، كيلو ونص يدفع لبعض المساكين عن جميع الأيام التي ما صامتها، ويكفي والحمد لله. المقدم: جزاكم الله خيرًا. الشيخ: نعم، ولو لفقير واحد، أو أهل بيت فقراء، يجمع ويعطاه أهل بيت فقراء، أو جماعة آخرون فقراء مع التوبة والندم والعمل الصالح، نعم. المقدم: جزاكم الله خيرًا، تطعم عن كل يوم مسكينًا.  الشيخ: نعم بعدد الأيام.  المقدم: بعدد الأيام.  الشيخ: وإن كانت لا تحفظها يكفي الظن، إذا كانت لا تحفظ الأيام؛ يكفي الظن والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11170/حكم-من-عجز-عن-قضاء-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47002.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12964,"question":"شخص أفطر في رمضان متعمدًا، ستة أيام متعمدًا على معصية، هل له قضاء، أو كفارة، أفيدونا بذلك؟","title":"حكم من أفطر أياماً من رمضان متعمداً","answer":"الجواب:  نعم، عليه التوبة والقضاء، عليه التوبة والقضاء، التوبة إلى الله من معصيته، وعليه القضاء، وإن كانت المعصية جماعًا، زنًا؛ فعليه كفارة مع القضاء، والتوبة كفارة عتق رقبة، فإن عجز؛ يصوم شهرين متتابعين، فإن عجز؛ يطعم ستين مسكينًا، إذا كان جماعًا، زنًا، أو لزوجته عليه الكفارة، وعليه التوبة، وعليه القضاء جميعًا.  أما إن أفطر من الأكل، أو الشرب؛ فعليه القضاء مع التوبة، التوبة إلى الله، والقضاء، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11181/حكم-من-افطر-اياما-من-رمضان-متعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50220.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13011,"question":"لها سؤال آخر تقول: علي قضاء من رمضان، ذات يوم نويت الصيام إلا أنني لم أتمه؛ لأنني أحسست بجوع، فأفطرت على أن أصومه في اليوم التالي، ولكن زميلاتي لمنني كثيرًا ووصفوا ما فعلته بالحرام، والحقيقة أنني لم أكن أعلم ذلك خاصة أنه ليس في رمضان، وظننت أن الأمر فيه سعة، فماذا علي؟","title":"حكم الإفطار في صوم القضاء","answer":"الجواب:  نعم، الذي قال لك أخواتك هو الصواب، لا يجوز لك الإفطار لإحساس بالجوع، بل عليك الصبر حتى تغيب الشمس؛ لأن قضاء رمضان فرض لا يجوز التساهل فيه. وإذا جاع الإنسان وهو صائم في الفرض، أو ظمئ؛ يتصبر، ويتحمل حتى يكمل، إلا إذا خشي الموت، أو مرضًا شديدًا يعلم أنه يترتب على هذا الشيء هذا عذر له في إفطاره، ثم إمساكه، يأخذ ما يزيل الخطر، ثم يمسك إلى الغروب، أما مجرد الجوع، أو مجرد الظمأ الذي ليس معه خطر؛ فهذا لا يسوغ الإفطار في الفريضة، لا في رمضان، ولا في قضاء رمضان، ولا في النذور في الصيام المنذورة، ولا في الكفارات، بل يجب الإمساك والصبر حتى تغيب الشمس، وعليك التوبة إلى الله والاستغفار وقضاء اليوم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11228/حكم-الافطار-في-صوم-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47107.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13130,"question":"من اليمن لواء إب المستمع محمد ناجي يسأل ويقول: إنني قد أفطرت يومًا من أيام رمضان، وذلك لأنه اشتد بي العطش، وخشيت على نفسي من الضر، فهل الواجب علي أن أقضي يومًا واحدًا، أم أنه يجب علي تطبيق حكم من أفطر متعمدًا؟ أفيدونا، جزاكم الله خيرًا.","title":"ما الواجب على من أفطر في رمضان خشية الضرر؟","answer":"الجواب:  ليس عليك إلا قضاء يوم واحد، وهكذا من أفطر متعمدًا عليه التوبة، ويقضي يومًا واحدًا، أما حديث: إنه لا يقضي عنه الدهر ولو صامه فهو حديث ضعيف. من أفطر عامدًا؛ فعليه التوبة، والقضاء لما أفطره يومًا، أو أكثر، يقضي ما أفطر، والحمد لله مع التوبة النصوح. أما من اضطر إلى ذلك، كمسألتك الذي خشيت معها الضرر البين، ثم أفطرت؛ فإنك تقضي هذا اليوم، وتمسك باقي النهار.. إذا أفطرت تمسك، وتقضي إلا عند الضرورة، والخوف من المرض الشديد، أو الموت نعم. المقدم: إذا لم يمسك -سماحة الشيخ- إذا أفطر، ولم يمسك بقية يومه؟ الشيخ: يأثم يأثم، يأثم وعليه التوبة إلى الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11359/ما-الواجب-على-من-افطر-في-رمضان-خشية-الضرر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47408.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13132,"question":"رسالة من أحد الإخوة السودانيين، وسؤالها طويل على طريقة إخوتنا في السودان، يقول فيه: أنا سوداني مقيم في المملكة العربية السعودية، والحمد لله على ذلك، لي أخت شقيقة في السودان أرسلت لي بسؤالها؛ لكي أرسله لكم، ونص سؤالها كالآتي: في بداية حياتها أي: في السنة الأولى من سن بلوغها أفطرت ثمانية أيام من أول شهر رمضان، حتى اليوم الثامن، وكانت هذه السنة هي أول سنة تشعر فيها بعلامات البلوغ، وكانت لا تدري بذلك، وواصلت من اليوم الثاني حتى نهاية الشهر، والحمد لله حتى الآن هي مواظبة على صيامها المفروض والتطوع، وعلى صلواتها المفروضة والنوافل، وهي مؤمنة ومتدينة والحمد لله على ذلك، والآن قد ناهزت الثلاثين من عمرها، وتذكرت تلك الأيام الثمانية، وسألت أحد العلماء في السودان وأفتى لها بأن تصوم عن كل يوم شهرين، والآن ومن حوالي ستة شهور هي مواصلة في الصيام، ولا أدري هل هذا هو السبيل الوحيد، أم ماذا، خوفي عليها يكاد يقتلني، كيف تصوم أربعمائة وثمانين يومًا مقابل ثمانية أيام، وهي مصرة على إتمام الأربعمائة والثمانين يومًا، فأفتونا جزاكم الله خيرًا.","title":"حكم من أفطر متعمدًا في رمضان","answer":"الجواب:  هذه الفتوى باطلة لا أساس لها من الصحة، وهذا جهل كبير ممن أفتاها بذلك، ليس عليها إلا الأيام الثمانية فقط، ليس عليها أن تصوم إلا الأيام الثمانية، مع التوبة والاستغفار، وإطعام مسكين، عن كل يوم نصف صاع، كيلو ونص تمرًا، أو رزًا، عن كل يوم تجمع ويعطاها بعض الفقراء، أربعة أصواع عن ثمانية أيام، أو اثنا عشر كيلو عن ثمانية أيام، كل يوم عنه كيلو ونص، يعطاها بعض الفقراء، والصيام ثمانية أيام فقط مثلما أفطرت. أما هذه الفتوى عن كل يوم شهرين فهذه فتوى باطلة، نسأل الله السلامة والعافية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11366/حكم-من-افطر-متعمدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47410.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13169,"question":"بعد ذلك ننتقل إلى رسالة السائلة أم عبدالله من اليمن تقول: كانت لدي ابنة أصيبت بمرض في بداية شهر رمضان، ولم تصم غير ثلاثة أيام، واستمر معها هذا المرض حتى بداية محرم، ثم توفيت،  هل يجب علينا صيام رمضان بدلًا عنها؟ وهل الذي يصوم عنها واحد فقط، أم أنه ممكن أن يشارك الوالدة والأبناء في قضاء الصيام عنها؟ مأجورين.","title":"حكم الصيام عمن مرضت في رمضان ثم ماتت","answer":"الجواب:  إذا كانت ماتت وهي عاجزة عن الصوم من أجل المرض؛ فلا شيء عليها، ولا يصام عنها؛ لأنها معذورة، والله يقول سبحانه: ومَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ يُرِيدُ [البقرة:185] يعني: بعد الشفاء، وبعد السفر، أما إن كانت شفيت، وتساهلت حتى مضت الأيام التي تستطيع فيها الصيام؛ فإنه يشرع لأقاربها أن يصوموا عنها؛ لقول النبي ﷺ: من مات، وعليه صيام؛ صام عنه وليه يعني: قريبه، أمها وأخواتها وإخوانها لا بأس إذا صاموا عنها، ولو اشتركوا في ذلك. فإذا كان عليها -مثلًا- عشرون يومًا، إذا كان عليها عشرون يومًا، فصاموا عنها، صام كل واحد خمسة؛ أربعة، صام كل واحد خمسة، أو خمسة صام كل واحد أربعة، أو عشرة صام كل واحد يومين؛ فلا بأس. أما إذا كانت ماتت وهي في مرضها؛ فلا شيء عليها، ولا يصام عنها. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11424/حكم-الصيام-عمن-مرضت-في-رمضان-ثم-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51105.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13192,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من الأخ المستمع بشير شداد، أخونا بشير عرضنا له بعض الأسئلة في حلقة مضت، وفي هذه الحلقة بقي له سؤال واحد يقول فيه: ما هو الحكم في شخص كان لا يصوم رمضان، ثم تاب، وعاد إلى الله، وبدأ يصوم، ما حكم الأشهر التي أفطرها جزاكم الله خيرًا؟","title":"حكم من أفطر أيامًا من رمضان متعمدًا ثم تاب","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  الحكم في ذلك أن عليه أن يقضي ما ترك عند جمهور أهل العلم مع التوبة إلى الله  إذا كان يصلي، أما إذا كان لا يصلي؛ فتارك الصلاة، كافر وليس عليه إلا التوبة، ليس عليه قضاء لصوم ولا صلاة، بل عليه التوبة إلى الله  ثم يستقبل الأمر استقبالًا.  أما إذا كان يصلي، ولكنه تساهل في الصيام؛ فإنه يقضي، فإنه مسلم عاصي؛ فعليه التوبة والقضاء، مع إطعام مسكين، عن كل يوم نصف صاع من قوت البلد، من تمر أو غيره، يجمع ويعطاه بعض الفقراء عن جميع الأيام التي أفطرها، وعليه التوبة إلى الله التوبة الصادقة بالندم على ما مضى من فعله القبيح، والعزم الصادق ألا يعود في ذلك، والله المستعان نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11447/حكم-من-افطر-اياما-من-رمضان-متعمدا-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47601.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13212,"question":"يقول هذا السائل: صمت رمضان، وأفطرت يومًا واحدًا فيه بغير عذر، وتبت إلى الله  وقضيت هذا اليوم من غير تأخير، والحمد لله، فهل علي مع صومي هذا اليوم كفارة، وجزاكم الله خيرًا؟","title":"حكم من أفطر في رمضان متعمداً من غير عذر","answer":"الجواب: إذا كان إفطارك بغير الجماع؛ فليس عليك كفارة، عليك التوبة -والحمد لله- والقضاء، إما إذا كان بجماع جامعت زوجتك، أو جماعًا محرمًا -نعوذ بالله- فعليك الكفارة، مع قضاء اليوم، ومع التوبة، عليك الكفارة، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصوم شهرين متتابعين، ستين يومًا، شهرين متتابعين، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، كل مسكين له نصف الصاع، يعني: تسعين كيلو، كل مسكين له كيلو ونصف كفارة إذا كنت جامعت في رمضان، سواءً زوجتك، أو غيرها، نعوذ بالله من الشيطان. فالحاصل: أن الجماع يوجب الكفارة مع قضاء اليوم، أما إفطار بالأكل، أو الشرب، ونحو ذلك، لكن من غير جماع؛ هذا يوجب القضاء فقط، والتوبة، القضاء والتوبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11493/حكم-من-افطر-في-رمضان-متعمدا-من-غير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52007.mp3","categories":["مفسدات الصيام","قضاء الصيام"]},{"id":13252,"question":"بعد ذلك ننتقل إلى رسالة السائلة (خ. ص. ع) القصيم البكيرية، تقول: نرجو من سماحة الشيخ الرد على هذا السؤال، أخي توفي بحريق، وعمره في التاسعة عشرة، وله الآن متوف له ما يقارب من سنتين، ولم يصم مدة عمره بعد البلوغ إلا يومًا واحدًا فقط، ماذا ينبغي علينا أن نفعل، هل نتصدق عنه، أم نصوم؟ السائلة من البكيرية.","title":"حكم قضاء الصيام عن المتوفى","answer":"الجواب:  إذا كان هذا الميت يصلي؛ فالأفضل لكم أن تصوموا عنه؛ لأنه فرط وتساهل، وقد قال النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه متفق على صحته، والولي هو: القريب، كأخيه، وأبيه، وعمه، ونحو ذلك، فإذا كان عليه صيام رمضان، أو نذر، أو كفارة؛ يستحب لأقربائه أن يصوموا عنه. أما إن كان لا يصلي؛ فالذي ما يصلي كافر؛ فليس عليكم صيام، ولا يشرع لكم الصيام عنه، أما إذا كان يصلي، ولكنه تساهل في الصوم يدعى له بالمغفرة، ويصام عنه، نسأل الله الهداية للجميع. المقدم: اللهم آمين جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11537/حكم-قضاء-الصيام-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51316.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13500,"question":"لها فقرة أخرى قبل أن نختم هذا اللقاء سماحة الشيخ، تقول: نحن ثلاث بنات توفيت والدتنا، وعليها قضاء من صيام رمضان حوالي عشرين يومًا، فهل نتساعد في القضاء عنها بمعنى: كل واحدة سبعة أيام، أم يلزمنا أن نقوم بالقضاء واحدة فقط؟","title":"حكم الاشتراك في قضاء ما على الميت من صيام","answer":"الجواب: لا حرج إذا تساعدوا ما دام قضاء رمضان لا حرج أن يتساعدوا، هذه تصوم يومين، وهذه تصوم أربعة حتى يكملوا لا حرج. أما إذا كان صومًا متتابعًا، مثل الكفارة المتتابعة، أو نذر متتابع يصومه واحد حتى يتابع بينه؛ لقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه فإذا كان على الميت كفارة قتل شهرين، أو كفارة ظهار؛ يصام عنه متتابعة، يصوم واحد متتابع، وإن كان في ذلك مشقة؛ كفروا عنه بالإطعام، مثل كفارة الظهار: إطعام ستين مسكينًا، أو الوطء في رمضان: إطعام ستين مسكينًا، وإن صام عنه أحدهم ستين يومًا فجزاه الله خيرًا. أما القتل ما فيه إطعام، ما فيه إلا الصيام، أو العتق، فإذا تيسر في تركته ما يوجب العتق، وتيسر العتق أعتقوا من تركته، فإن كان ما تيسر العتق يصوم عنه بعضهم؛ لقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه يصوم واحد منهم متتابعًا، أما إذا كان لا، قضاء رمضان فلا بأس أن يشتركوا فيه؛ لأنه ليس فيه التتابع، فإذا صام هذا أيامًا، وهذا أيامًا؛ صار عشرين يوم عليه.... أربعة، كل واحد صام خمسة؛ فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/11811/حكم-الاشتراك-في-قضاء-ما-على-الميت-من-صيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51812.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13516,"question":"السائل مشاري عثمان يقول في هذا  بأنه شاب في الثانوية يبلغ من العمر السابعة عشرة من العمر حصل له قبل ستة أشهر فشل كلوي، يقول: وأنا الآن لم أصم رمضان، وذلك بسبب الفشل، وبعد أسبوع سوف أبدأ بالغسيل الكلوي، فإني سألت عن ماذا أفعل عن عدم الصيام، فقالوا لي: تقوم بتوزيع فدية ثلاثين صاعًا عن رمضان كل صاع لمسكين، أفيدوني أفادكم الله في ذلك.","title":"ما يلزم من لم يصم رمضان بسبب الفشل الكلوي؟","answer":"الجواب: عليك أن تسأل الأطباء المختصين، فإذا كان يرجى شفاؤك؛ فتقضي، تصوم في الأوقات التي ما فيها غسيل، ولا يضرك فيها الصوم، أو في الأوقات التي يزول فيها الغسيل -إن شاء الله- وتبرأ. أما إن كان المرض يستمر، وأن القاعدة أن هذا المرض يستمر، وأنه يضرك الصوم؛ فلا مانع من الإطعام عن كل يوم نصف صاع، عن جميع الشهر خمسة عشر صاعًا. لكن الظاهر -والله أعلم- أن هذا يرجى زواله، وأن الأيام التي ما فيها غسيل يمكن أن تقضي فيها، فالحمد لله، تقضي في الأيام التي ما فيها غسيل إذا كنت تستطيع، أما إذا قرر الأطباء أن هذا يضرك، وأن الصوم يضرك، وأنه لا بد أن تستمر في عدم الصوم، فتطعم عن كل يوم مسكينًا، نصف صاع كيلو ونصف. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11840/ما-يلزم-من-لم-يصم-رمضان-بسبب-الفشل-الكلوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53114.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13519,"question":"السائل مشاري عثمان يقول في هذا  بأنه شاب في الثانوية يبلغ من العمر السابعة عشرة من العمر حصل له قبل ستة أشهر فشل كلوي، يقول: وأنا الآن لم أصم رمضان، وذلك بسبب الفشل، وبعد أسبوع سوف أبدأ بالغسيل الكلوي، فإني سألت عن ماذا أفعل عن عدم الصيام، فقالوا لي: تقوم بتوزيع فدية ثلاثين صاعًا عن رمضان كل صاع لمسكين، أفيدوني أفادكم الله في ذلك.","title":"ما يلزم من لم يصم رمضان بسبب الفشل الكلوي؟","answer":"الجواب: عليك أن تسأل الأطباء المختصين، فإذا كان يرجى شفاؤك؛ فتقضي، تصوم في الأوقات التي ما فيها غسيل، ولا يضرك فيها الصوم، أو في الأوقات التي يزول فيها الغسيل -إن شاء الله- وتبرأ. أما إن كان المرض يستمر، وأن القاعدة أن هذا المرض يستمر، وأنه يضرك الصوم؛ فلا مانع من الإطعام عن كل يوم نصف صاع، عن جميع الشهر خمسة عشر صاعًا. لكن الظاهر -والله أعلم- أن هذا يرجى زواله، وأن الأيام التي ما فيها غسيل يمكن أن تقضي فيها، فالحمد لله، تقضي في الأيام التي ما فيها غسيل إذا كنت تستطيع، أما إذا قرر الأطباء أن هذا يضرك، وأن الصوم يضرك، وأنه لا بد أن تستمر في عدم الصوم، فتطعم عن كل يوم مسكينًا، نصف صاع كيلو ونصف. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11840/ما-يلزم-من-لم-يصم-رمضان-بسبب-الفشل-الكلوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53114.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13546,"question":"تقول في آخر أسئلتها: إذًا هل يجوز الصلاة والصيام عن الميت؟","title":"حكم الصيام عن الميت","answer":"الجواب: يصام عنه إذا كان عليه دين، إذا كان عليه رمضان أو نذور يصام عنه، أو كفارات، يقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه يعني: قريبه، يعني: صوم واجب مثل رمضان، مرض ولا صام ثم عافاه الله وتساهل ولا صام ... مات؛ يصام عنه، أو الحائض كذلك أفطرت في رمضان، أو النفساء، ثم ظهر رمضان، وتساهلت، ثم ماتت قبل أن تقضي؛ يقضى عنها، وهكذا كفارة الظهار .. كفارة الجماع في رمضان .. كفارة القتل .. إذا مات وعليه صيام صام عنه وليه، هذا هو المشروع. أما رمضان نفسه إذا كان معذورًا فلا، مثل: أفطر في رمضان مريض، ولكن مات في مرضه، ما يقضى عنه شيء؛ لأنه معذور، مات في مرضه، والتطوع لا يتطوع عنه أحد، لا يصوم أحد عنه تطوعًا، إنما يصوم عنه إذا كان عليه واجب، عليه قضاؤه، فلم يقضه، تساهل؛ فيستحب لأوليائه من الورثة أن يقضوا عنه، ولو جماعة يتقاطعونه من رمضان، كل واحد يصوم بعض الأيام. أما الكفارة لا. لابد يصومها واحد؛ لأنها متتابعة، يصوم كفارة القتل شهرين متتابعين، أو كفارة الجماع في رمضان شهرين متتابعين لمن عجز عن الرقبة، أو كفارة القتل لمن عجز عن الرقبة شهران، هذه يصومها واحد؛ لأنها متتابعة، يستحب لأقربائه أن يصومها منهم واحد هذه الكفارة المتتابعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11868/حكم-الصيام-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51905.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13595,"question":"هذه السائلة تقول: أخت كانت تأكل في رمضان أيام متعددة، وتسأل: هل يجب عليها القضاء بعد أن تابت، والتزمت بشرع الله، أم أنها تدخل تحت قوله تعالى: إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ [البقرة:173]؟","title":"حكم من أفطرت عمدًا ثم تابت","answer":"الجواب: عليها أن تقضي، ما دام مسلمة عليها أن تقضي، وتتوب إلى الله مما فرطت، الله -جل وعلا- يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فإذا كان المريض المعذور يقضي، والمسافر المتساهل المفطر عمدًا من باب الأولى مع التوبة إلى الله، أما إن كانت لا. كافرة ما تؤمن بالدين، أو ما تصلي؛ فعليها التوبة، ولا قضاء؛ لأن الكافر تحبط أعماله، فعليها تجدد من جديد. أما إذا كانت مسلمة، تؤمن بالله واليوم الآخر تصلي، ولكنها تساهلت في رمضان؛ فعليها القضاء والكفارة، القضاء والتوبة والكفارة، ثلاثة أمور: قضاء الأيام، والتوبة إلى الله مما فعلت بالندم، والإقلاع، والعزم ألا تعود، وإطعام مسكين عن كل يوم، وهي الكفارة، نصف صاع، كيلو ونصف تقريبًا، هذا عن كل يوم من قوت البلد، من تمر، أو رز، أو حنطة من قوت بلدها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11923/حكم-من-افطرت-عمدا-ثم-تابت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52304.mp3","categories":["قضاء الصيام","قضايا المرأة"]},{"id":13603,"question":"هذا السائل يقول في هذا  سماحة الشيخ! أنا رجل أبلغ من العمر الخامسة والسبعين، لم أبدأ الصيام في السن الشرعي، وإنما صمت أيامًا، وأفطرت أيامًا، وأنا لا أعرف عدد تلك الأيام، وقد كان ذلك في شبابي، أما الآن -وأحمد الله- فأنا مداوم على الصيام، وذلك من أكثر من ثلاثين عامًا، سماحة الشيخ! ماذا أفعل في الأيام التي فاتتني، وأنا لا أعلم عدد هذه الأيام، علمًا بأنني رجل عاجز، ولا أستطيع أن أقضي؟ جزاكم الله خيرًا.","title":"ما يلزم من ترك الصيام في شبابه وعجز عن القضاء لكبره؟","answer":"الجواب: عليك أن تقضيها بالظن، تجتهد في ظنك، في عددها، ثم تقضيها، وإذا كنت لا تستطيع قضاءها لكبر السن، والعجز؛ تطعم عن كل يوم مسكينًا، نصف صاع من قوت البلد، من تمر، أو أرز، أو حنطة عن كل يوم تجمعها، وتعطيها بعض الفقراء حسب الظن، ظننت عشرين يومًا، ثلاثين يومًا، أربعين يومًا، خمسين يومًا، حسب الظن تصومها، فإن عجزت لأنك كبير السن، ما تستطيع صيام رمضان، إذا كنت عاجزًا؛ فإنك تطعم عن كل يوم مسكينًا، وهكذا العاجز عن رمضان يطعم عن كل يوم مسكينًا، أما إذا كنت تستطيع أن تقضي؛ فعليك القضاء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11938/ما-يلزم-من-ترك-الصيام-في-شبابه-وعجز-عن-القضاء-لكبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52722.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13614,"question":"هذه السائلة سماحة الشيخ تقول: امرأة تنجب دائمًا في شهر رمضان، ويشق عليها القضاء لانشغالها بالأولاد، وأمور البيت، ماذا عليها أن تفعل؟","title":"ما تفعل من يشق عليها قضاء الصوم لانشغالها؟","answer":"الجواب: عليها أن تقضي، واجب عليها أن تقضي حسب الطاقة، ولو كانت ولدت في سنتين، أو ثلاث كلها في رمضان فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] تؤجل إذا عجزت، تؤجل حتى يتيسر لها القضاء، وإن استطاعت؛ وجب أن تقضي، لكن لو شغلت بالأطفال، وشق عليها الصوم؛ فإنها تؤجل حتى بعد رمضان، ما فيه أولاد ما فيه مشقة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] والمرضع مثل المريض، المرضع مثل المريض لها أن تؤجل حتى تستطيع. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11954/ما-تفعل-من-يشق-عليها-قضاء-الصوم-لانشغالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52808.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":13706,"question":"من سوريا السائلة التي رمزت لاسمها بـ (س. ع) تقول: البعض من النساء تأخذ حبوب لمنع العادة الشهرية في رمضان، فهل يجب على المرأة أن تقضي الأيام التي لم تفطرها من وقت العادة؟ أم يجب عليها الإعادة؟","title":"هل تقضي من استعملت حبوبًا لمنع الحيض في رمضان؟","answer":"الجواب: ما دامت أخذت الحبوب، وارتفع الحيض؛ ما عليها شيء، إذا كان أخذت الحبوب، أو شيئًا مما يمنع الحيض، وصامت وهي طاهرة، فليس عليها أن تقضي والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/12082/هل-تقضي-من-استعملت-حبوبا-لمنع-الحيض-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53509.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":13767,"question":"يقول هذا السائل أبو معاذ من اليمن: في أحد أيام رمضان المبارك استيقظت بعد أذان الصبح بعشر دقائق تقريبًا، فشربت معتقدًا أن هذه المدة بعد الأذان لا تؤثر، فهل صيامي صحيح لذلك اليوم، أم لا؟","title":"حكم من شرب بعد طلوع الفجر في رمضان","answer":"الجواب: هذا الصيام فيه شبهة واحتمال، فالأحوط لك أن تقضيه؛ لقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك وجوب الصيام فرض عليك، وهذا مشكوك فيه، فالأحوط لك أن تقضيه. نعم.","link":"https://binbaz.org.sa/fatwas/12151/حكم-من-شرب-بعد-طلوع-الفجر-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53606.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13804,"question":"تقول أختنا: في شهر رمضان لم أستطع أن أكمل الصيام لوضع الحمل ثم انتابتني حالة صحية بعد ذلك لم أستطع معها القضاء، ما هو توجيهكم؟","title":"وجوب قضاء الصوم عند القدرة","answer":"الجواب: عليك القضاء عند القدرة والحمد لله، يقول الله سبحانه: وَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، والحبلى معذورة إذا شق عليها الصوم تفطر، وهكذا المرضعة ثم تقضي بعد ذلك في الوقت الذي تستطيع، والحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12213/وجوب-قضاء-الصوم-عند-القدرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60212.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":13984,"question":"ما حكم من أخر قضاء أيام من رمضان أحد عشر عامًا وأراد أن يقضيها فقضاها، فهل يبقى عليه شيء؟","title":"حكم من أخر قضاء رمضان عدة سنوات","answer":"الجواب: عليه التوبة من التأخير، وعليه القضاء وعليه إطعام مسكين عن كل يوم أخره، إطعام مسكين عن كل يوم كما أفتى بذلك جماعة من الصحابة ، ثلاثة أمور:\nالأمر الأول: القضاء، يقضي.\nالأمر الثاني: التوبة من التأخير.\nالأمر الثالث: إطعام مسكين عن كل يوم نصف صاع من قوت البلد من تمر أو حنطة أو أرز. نعم.","link":"https://binbaz.org.sa/fatwas/12394/حكم-من-اخر-قضاء-رمضان-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53908.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14036,"question":"نعود إلى رسالة إحدى الأخوات المستمعات من الإمارات العربية المتحدة تقول: أم مجاهد، أختنا عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة لها سؤال استغرق صفحة واحدة فقط، أختنا تقول: حينما كنت حامل بمولودي الأول، وذلك قبل تسع سنوات؛ سألت أحد الإخوة ممن يدعو لمنهج السلف عن ماذا أفعل، وقد دخل علينا شهر رمضان، ولا أستطيع الصوم لظروف الحمل؛ فأجابني أن لا علي صوم، مستدلاً بالحديث: وضع شطر الصلاة عن المسافر، ووضع الصوم عن الحامل والمرضع، وأيضًا ليس هنالك جزاء، وأصبحت لا أصوم حينما أكون حاملًا أو مرضعًا، ولمدة أربع سنوات -أي: إلى مولودي الرابع، وبعدها سمعت من أحد الإخوة أن على أمثالي الجزاء فقط، مستدلاً بالأثر أن ابن عباس رأى أم ولد له مرضعًا فقال لها: \"أنت من الذين يطيقونه، عليك الجزاء وليس عليك القضاء\"، فأخذت مبلغًا من المال لأطعم به جزاء للأربعة الأشهر التي علي من رمضان، ولكن يا فضيلة الشيخ سمعت في برنامج (نور على الدرب) من أحد العلماء الأفاضل أن على أمثالي القضاء، ولو تأخر القضاء تكون معه كفارة، فماذا أفعل يا فضيلة الشيخ ورمضان على الأبواب لو قدر الله لنا الحياة، ومواعيد وضعي قبله بأيام، وسيكون الشهر الخامس دين علي، وسؤالي: ما صحة ما ذكر الإخوة من الحديث والأثر، ولو أدركني الموت قبل قضاء المائة والخمسين اليوم التي علي، هل أكون آثمة بذلك؟ أرجو الإفادة ليطمئن قلبي جزاكم الله خيرا، ثم إنني وضعت مبلغاً من المال بنية الإطعام، وجاءنا أحد الإخوة في الله عابر سبيل، نفذ ما عنده من مال؛ فأعطيته له بنية كفارة الفطر، فهل يصح عملي هذا؟ أم أطعم؟ أفيدوني جزاكم الله خيرًا.","title":"ما الواجب على من أفطرت لعذر الحمل أو الرضاع؟","answer":"الجواب: الصواب في هذا أن على الحامل والمرضع القضاء، وما يروى عن ابن عباس وابن عمر أن عليهما أن على الحامل والمرضع الإطعام، هو قول مرجوح، مخالف للأدلة الشرعية، والله يقول سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، والحامل والمرضع في حكم المريض، وليستا في حكم الشيخ الكبير العاجز، بل هما في حكم المريض؛ فتقضيان إذا استطاعتا ذلك ولو تأخر القضاء، وإذا تأخر القضاء مع العذر الشرعي؛ فلا إطعام، قضاء فقط، أما إذا تساهلت ولم تقض مع القدرة؛ فعليها مع القضاء الإطعام، إذا جاء رمضان آخر ولم تقض تساهلًا وتكاسلًا؛ فعليها القضاء مع الإطعام، أما إذا كان التأخير من أجل الرضاع أو الحمل لا تكاسلًا؛ فإن عليها القضاء فقط، ولا إطعام، وما أنفقت من الإطعام، فهو في سبيل الله، ولك أجره، ويؤدي ما يؤدي إذا كنت تساهلت في القضاء، يؤدي مؤداه، وعليك القضاء، تصومين حسب الطاقة، ولا يلزمك التتابع، تصومين وتفطرين حتى تكملي إن شاء الله، والله في عون العبد، وتسهيله  إذا صدق العبد، وأخلص لله واستعان به جل وعلا، فالله يعينك ويسهل لك القضاء، فأبشري بالخير واستعيني بالله واصدقي، والله جل وعلا هو المعين الموفق . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12460/ما-الواجب-على-من-افطرت-لعذر-الحمل-او-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60704.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":14040,"question":"حديث من مات وعليه صوم؛ صام عنه وليه، الشيء الذي أعرفه أنه محمول على صوم النذر، ولكن أحد العلماء ذكر في البرنامج أنه صوم رمضان، فهل هذا صحيح؟ أم الصحيح ما أعرفه من طريق أحد الكتب السلفية؟ أفيدوني مأجورين، جزاكم الله خيرًا.","title":"ما هو الصوم الذي يقضى عن الميت؟","answer":"الجواب: الصواب أنه عام وليس خاصًا بالنذر، وقد روي عن بعض الأئمة كـأحمد رحمه الله وجماعة، أنهم قالوا: إنه خاص بالنذر، ولكنه قول مرجوح، ولا دليل عليه.\nوالصواب أنه عام؛ لأن الرسول عليه السلام قال: من مات وعليه صيام صام عنه وليه، متفق على صحته من حديث عائشة رضي الله عنها، ولم يقل: صوم النذر، ولا يجوز تخصيص كلام النبي ﷺ بالدعاوى والاجتهادات والآراء، لا، حديث النبي عام عليه الصلاة والسلام، يعم صوم النذر وصوم رمضان إذا تأخر، إذا ترك صيامه تكاسلًا بعد القدرة، أو صوم الكفارات، فمن ترك ذلك؛ صام عنه وليه، والولي: هو القريب، أقاربه، وإن صام غيرهم؛ أجزأ ذلك، وقد سئل النبي ﷺ سأله رجل قال: يا رسول الله! إن أمي ماتت، وعليها صوم شهر أفأصوم عنها؟ قال: أرأيت لو كان على أمك دين أكنت قاضيه؟ اقضوا الله فالله أحق بالوفاء، وسألته امرأة عن ذلك قالت: يا رسول الله! إن أمي ماتت، وعليها صوم شهر أفأصوم عنها؟ قال: أرأيت لو كان على أمك دين أكنت قاضيته؟ اقضوا الله فالله أحق بالوفاء.\nوفي مسند أحمد بإسناد صحيح عن ابن عباس رضي الله عنهما: أن امرأة قالت: يا رسول الله! إن أمي ماتت وعليها صوم رمضان أفأصوم عنها؟ قال: صومي عن أمك، فأوضحت أنه رمضان، فأمرها بالصيام، فالأحاديث الكثيرة دالة على أن القضاء يعم رمضان وغيره، وأنه لا وجه لتخصيص النذر، بل هو قول مرجوح ضعيف، والصواب العموم، هكذا جاءت الأدلة عن رسول الله عليه الصلاة والسلام، لكن إذا كان المفطر في رمضان لم يفرط، بأن أفطر من أجل المرض، أو من أجل الرضاع أو الحمل، ثم مات المريض أو ماتت الحامل أو ماتت المرضعة، ولم تستطع القضاء؛ فلا شيء على الورثة، لا قضاء ولا إطعامًا للعذر الشرعي وهو المرض ونحوه، أما من شفي من مرضه، وأمكنه الصوم فتساهل؛ هذا يقضى عنه، أو المرضع أو الحامل، استطاعت أن تقضي بعد ذلك، ولكن تساهلت؛ فهذا يقضى عنها، والله ولي التوفيق.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12462/ما-هو-الصوم-الذي-يقضى-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60705.mp3","categories":["قضاء الصيام","شروح الحديث"]},{"id":14060,"question":"من المملكة الأردنية الهاشمية خريبة السوق هذه رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (م. س. ع) ، أختنا تقول في سؤال لها: إنني كنت في رمضان أفطر دائمًا، وعندما هداني الله، وأحسست بالإيمان لم أعد إلى ذلك، هل هنا أحاسب على جميع ما أفطرته قبل الهداية والتوبة إلى الله؟ أم علي القضاء لجميع ما أفطرت؟ مع العلم أنني لا أحصي ما أفطرت، بماذا تنصحونني أن أفعل؟ كذلك الصلاة لم أكن أصلي من قبل، والحمد لله الآن مداومة عليها وملتزمة بها، أرجو منكم التوضيح. جزاكم الله خيرًا.","title":"حكم قضاء الصلاة والصيام على من تركهما","answer":"الجواب: الواجب عليك التوبة، وقد من الله عليك بذلك والحمد لله، فعليك أن تلزمي التوبة، وأن تكثري من الاستغفار والعمل الصالح وصلاة النافلة، والصدقات إذا استطعت، كثرة التسبيح والتهليل والتحميد والتكبير والاستغفار، كل ذلك من أسباب كمال التوبة، ومن أسباب المغفرة، وليس عليك قضاء الصلاة ولا الصوم؛ لأن ترك الصلاة كفر، والكافر إذا أسلم ليس عليه قضاء، وقد قال عليه الصلاة والسلام في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة؛ فمن تركها فقد كفر، خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة بن الحصيب رضي الله تعالى عنه، وقال عليه الصلاة والسلام أيضًا: بين الرجل وبين الكفر والشرك ترك الصلاة، خرجه الإمام مسلم في صحيحه عن جابر بن عبد الله رضي الله تعالى عنهما، في أحاديث أخرى تدل على كفر تارك الصلاة.\nوقد ذكر عبد الله بن شقيق العقيلي التابعي الجليل عن الصحابة  -أصحاب النبي ﷺ- أنهم كانوا يرون أن ترك الصلاة كفر، وقال: كانوا لا يرون شيئًا من الأعمال تركه كفر إلا الصلاة، فالصلاة أمرها عظيم وهي عمود الإسلام، من حافظ عليها فقد حفظ دينه، ومن ضيعها فقد ضيع دينه.  فأنت إذا من الله عليك بالتوبة من ترك الصلاة وترك الصوم؛ فليس عليك قضاء والحمد لله، وإنما عليك التوبة الصادقة والاستقامة عليها، وحمد الله على ذلك وشكره على ذلك، والاستكثار من أعمال الخير: من صدقات -ولو بالقليل- من الاستغفار الكثير، التسبيح والتهليل والتحميد والتكبير، وغير ذلك من وجوه الخير: كصوم التطوع، وكثرة الدعاء والضراعة إلى الله أن يتقبل منك وأن يعفو عنك.  أما من ترك الصوم، ولكنه يصلي، مسلم يصلي لكن تساهل في الصيام؛ فإنه يقضي، يقضي ما عليه من الصيام؛ لأن ترك الصيام ليس ردة عن الإسلام، ولكنه معصية عظيمة، فمن ترك الصوم شهرًا أو أكثر أو أقل؛ فعليه القضاء؛ مادام مسلمًا يصلي، وليس معه ما يوجب ردته وكفره، فإن عليه القضاء؛ لأن الرسول ﷺ أمر الحيض بقضاء الصوم فعليهن القضاء، وهكذا من تعمدت ترك الصوم بغير عذر، ولكنها تصلي؛ فإن عليها القضاء أيضًا، وهكذا الرجل الذي تساهل في الصيام وهو مسلم يصلي؛ فإنه يقضي أيضًا ويتحرى الأيام التي تركها إذا كان لا يعلمها، يتحرى، ويعمل بظنه في ذلك ويقضي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12485/حكم-قضاء-الصلاة-والصيام-على-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60805.mp3","categories":["قضاء الصيام","قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":14087,"question":"أختنا تقول: قبل خمس وثلاثين سنة ولدت لي ابنة في رمضان، وبعدها بسنتين ولدت لي ابنة في رمضان، ولم أصم سوى عشرة أيام، أفيدوني جزاكم الله خيرًا، أنا امرأة كما وصفت من حالي كبيرة في السن ومريضة، كيف أتصرف الآن؟","title":"ما يلزم من أفطرت بسبب الولادة ولم تقض حتى كبرت؟","answer":"الجواب: إذا عافاك الله تصومين الأيام التي تركت، إذا عافاك الله عليك أن تصومي الأيام التي عليك من رمضان الأول ورمضان الثاني، وعليك مع ذلك إطعام مسكين عن كل يوم إذا كنت تساهلت في القضاء مع القدرة، عليك إطعام مسكين عن كل يوم نص صاع تمر أو رز، يعني: كيلو ونص تقريبًا عن كل يوم، يعطاه بعض الفقراء ولو واحد، تجمع ويعطاه بعض الفقراء فقير أو فقيرين، أو أهل بيت فقراء يكفي والحمد لله، أما إن كان التأخير من أجل المرض، وإلا ما تساهلت، لكن المرض منعك من الصوم؛ فعليك القضاء فقط، وليس عليك إطعام، بل تقضين الأيام التي تركت، وليس عليك إطعام؛ لأنك معذورة.\nفإن كان المرض ملازمًا، وقرر الأطباء أن هذا المرض ملازم، ولا يرجى برؤه ولا يرجى زواله؛ فليس عليك القضاء، ككبير السن الذي عجز عن القضاء، وعليك إطعام مسكين عن كل يوم والحمد لله، مثلما تقدم ..... نصف صاع تمر أو رز أو بر من قوت البلد، مقداره كيلو ونص تقريبًا يعطاه بعض الفقراء والحمد لله، يجمع كله ويعطاه بعض الفقراء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12542/ما-يلزم-من-افطرت-بسبب-الولادة-ولم-تقض-حتى-كبرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61010.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14092,"question":"أختنا تقول: قبل خمس وثلاثين سنة ولدت لي ابنة في رمضان، وبعدها بسنتين ولدت لي ابنة في رمضان، ولم أصم سوى عشرة أيام، أفيدوني جزاكم الله خيرًا، أنا امرأة كما وصفت من حالي كبيرة في السن ومريضة، كيف أتصرف الآن؟","title":"ما يلزم من أفطرت بسبب الولادة ولم تقض حتى كبرت؟","answer":"الجواب: إذا عافاك الله تصومين الأيام التي تركت، إذا عافاك الله عليك أن تصومي الأيام التي عليك من رمضان الأول ورمضان الثاني، وعليك مع ذلك إطعام مسكين عن كل يوم إذا كنت تساهلت في القضاء مع القدرة، عليك إطعام مسكين عن كل يوم نص صاع تمر أو رز، يعني: كيلو ونص تقريبًا عن كل يوم، يعطاه بعض الفقراء ولو واحد، تجمع ويعطاه بعض الفقراء فقير أو فقيرين، أو أهل بيت فقراء يكفي والحمد لله، أما إن كان التأخير من أجل المرض، وإلا ما تساهلت، لكن المرض منعك من الصوم؛ فعليك القضاء فقط، وليس عليك إطعام، بل تقضين الأيام التي تركت، وليس عليك إطعام؛ لأنك معذورة.\nفإن كان المرض ملازمًا، وقرر الأطباء أن هذا المرض ملازم، ولا يرجى برؤه ولا يرجى زواله؛ فليس عليك القضاء، ككبير السن الذي عجز عن القضاء، وعليك إطعام مسكين عن كل يوم والحمد لله، مثلما تقدم ..... نصف صاع تمر أو رز أو بر من قوت البلد، مقداره كيلو ونص تقريبًا يعطاه بعض الفقراء والحمد لله، يجمع كله ويعطاه بعض الفقراء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12542/ما-يلزم-من-افطرت-بسبب-الولادة-ولم-تقض-حتى-كبرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61010.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14098,"question":"تقول أختنا: إنني مريضة بالسكر والقرحة، فإذا لم أستطع الصوم ماذا يجب علي أن أفعل؟","title":"هل يجب الصيام على المصاب بالسكر والقرحة؟","answer":"الجواب: عليك مراجعة الطبيب المختص، فإذا قرر الطبيب المختص أن الصوم يضرك؛ فأفطري، واقضي بعد العافية، إذا عافاك الله تقضين بعد ذلك، وإن قرر الطبيب المختص أو الأطباء المختصون أن هذا المرض يضره الصوم دائمًا، وأنه فيما يعلمون مرض سوف يستمر ولا يرجى برؤه؛ فإنك تفطرين وتطعمين عن كل يوم مسكينًا والحمد لله، وليس عليك صيام، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/12526/هل-يجب-الصيام-على-المصاب-بالسكر-والقرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61004.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14210,"question":"السائل يقول في ثالث أسئلته في عام ألف وأربعمائة واثنين وألف وأربعمائة وثلاثة وألف وأربعمائة وأربعة لم أصم رمضان في هذه الأعوام الثلاث عصيانًا مني أو هذا كان في أول شبابي ولم أقض حتى الآن، هل أقضي هذه الأيام وأخرج كفارة؟الشيخ: أعد. أعد.المقدم: يقول: في أعوام ثلاث سابقة ألف وأربعمائة واثنين وثلاثة وأربعة لم أصم رمضان في هذه الأعوام الثلاث عصيانًا مني، وهذا كان في أول شبابي ولم أقض حتى الآن، هل أقضي وأخرج كفارة أو التوبة تكفي؟ وجهوني سماحة الشيخ.","title":"ما يجب على من أفطر رمضان ثلاث سنوات بدون عذر؟","answer":"الجواب: عليك التوبة والقضاء والإطعام، كل الثلاث، عليك التوبة إلى الله من عدم الصوم، وعليك أن تقضي الصوم، وعليك أن تطعم عن كل يوم مسكينًا بسبب التأخير إذا كنت تستطيع الإطعام، هذا هو الواجب عليك؛ لأن هذه جريمة عظيمة نسأل الله العافية، إذا كنت قد بلغت الحلم حين تركتها، فالواجب عليك القضاء والتوبة إلى الله وإطعام مسكينًا عن كل يوم نصف صاع من قوت البلد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12659/ما-يجب-على-من-افطر-رمضان-ثلاث-سنوات-بدون-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54811.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14245,"question":"السائل الذي رمز لاسمه (س. ع. ع) ، الرياض، يقول: سماحة الشيخ! أنا شاب في العشرين من العمر ذهبت إلى الدراسة خارج المملكة، وقد مر علي شهر رمضان في إحدى السنوات الأولى في بعثتي ولم أصم ذلك الشهر للأسف من باب التفريط، وكذلك لم أكن أؤدي الصلوات في تلك السنة، ولكن بعدما رجعت تبت إلى الله والحمد لله، ماذا أفعل في هذا الشهر الذي لم أصمه، هل أقضيه متواصل أم متفرق؟ أم ماذا ترون سماحة الشيخ؟","title":"هل يقضي الصلاة والصيام من تاب من تركهما؟","answer":"الجواب: مادمت لا تصلي فالذي ما يصلي كافر، والتوبة تجب ما قبلها، فلا صوم ولا صلاة لا تقضي الصوم ولا الصلاة؛ لأن من ترك الصلاة كفر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، لكن لو قضيت الصيام خروجًا من خلاف من قال: إنه لا يكفر كفرًا أكبر إذا كان لا يجحد وجوبها فلا بأس، لكن الصواب أنه يكفر تارك الصلاة وإن لم يجحد وجوبها، والكافر يكفيه التوبة، قال الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، وقال جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا [الزمر:53]، فالتوبة تجب ما قبلها وليس عليك قضاء إذا كنت لا تصلي كما قلت في السؤال. نعم.\nالمقدم: وبالنسبة للصلوات التي تركها.\nالشيخ: لا يقضي الصوم ولا الصلاة التوبة تجب ما قبلها.\nالمقدم: طيب جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12701/هل-يقضي-الصلاة-والصيام-من-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53015.mp3","categories":["قضاء الصيام","قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":14275,"question":"هذه السائلة التي رمزت لاسمها ب (ج. ر) من الخبر تقول: نود من سماحة الشيخ أن يفيدنا في الحكم الشرعي في هذه المسألة: لقد توفي والدي رحمه الله وكان قد نذر قبل وفاته نذر طاعة وشكرًا لله على أمر، وذلك إذا تم هذا الأمر أن يصوم شهرًا كاملًا في مكة المكرمة، وقد تحقق هذا الأمر والحمد لله، والآن هل يقوم أحد من الأولاد أو الزوجة بالصوم عنه في مكة المكرمة؟ وهل يكون الصوم متتابعًا أو على فترات؟ وهل لابد أن يكون الصوم في مكة أو في مدينة أخرى؟ أفيدونا سماحة الشيخ.","title":"حكم الصيام عمن من مات وعليه نذر صوم","answer":"الجواب: يشرع لمن يقرب منه أن يصوم عنه كأخيه أو ابنه أو أبيه أو زوجته، لقول النبي ﷺ: من مات وعليه صيام صام عنه وليه يعني: قريبه، إذا تيسر أحد يصوم عنه فهذا طيب وهو مشروع لهذا الحديث الصحيح: من مات وعليه صيام صام عنه وليه هكذا يقول ﷺ، فيستحب لبعض أقاربه أو زوجته أن يصوموا عنه هذا الشهر، وإذا كان في مكة فهو أفضل وأكمل وإن ما تيسر ففي أي مكان. نعم.","link":"https://binbaz.org.sa/fatwas/12734/حكم-الصيام-عمن-من-مات-وعليه-نذر-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54914.mp3","categories":["قضاء الصيام"]},{"id":14444,"question":"امرأة كبيرة في السن فاتتها أو فاتها صيام رمضان في العام الماضي نظرًا لمرضها، وعدم استطاعتها، وهي تسأل ماذا تفعل في قضاء ذلك الصيام؟ علمًا بأنها الآن لا تستطيع القضاء نظرًا لحالتها الصحية.","title":"ما يجب على من أفطرت بسبب الكبر والمرض؟","answer":"الجواب: إن كانت لا تستطيع القضاء لمرضها فعليها القضاء بعد الشفاء وتمهل؛ لقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَر [البقرة:185] أما إن كانت لا تستطيع لكبر سنها، وضعف بدنها وعجزها عن الصبر عن الطعام والشراب إلى الليل، فإنها تطعم عن كل يوم مسكينًا، ولا شيء عليها، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/12910/ما-يجب-على-من-افطرت-بسبب-الكبر-والمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55402.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","قضايا المرأة"]},{"id":14809,"question":"المستمع: محمد سريع الروقي، من عفيف، بعث برسالة يقول فيها: كانت زوجتي حاملًا في الشهر التاسع، عندما هل شهر رمضان قبل مدة، فقلت لها: إذا لم تستطيعي الصيام؛ فافطري، وقد أفطرت ذلك الشهر كله، على أمل أن تقضيه بعد الوضع، ولكنها تعرضت لحادث سيارة أصبحت بعده ربع مشلولة، وقد أمرتها أن تقضي ما عليها من صومٍ، ولكنها لم تقضه حتى الآن. علمًا بأنها قادرة على ذلك، بدليل أنها صامت أكثر من رمضان بعده، نرجو الإفادة، هل يجوز أن أصوم عنها أنا، أم يصوم عنها أحد أولادها، أم أنه لا بد أن تقضيه هي؟جزاكم الله خيرًا.","title":"حكم الصيام عمن أفطرت رمضان ولم تقضه مع استطاعتها","answer":"الجواب: الواجب أن تقضيه هي، وليس لأحدٍ أن يصوم عنها وهي موجودة، أما لو كانت قد ماتت صام عنها غيرها، لكن مادامت موجودة، فالواجب عليها أن تبادر، وأن تصوم جميع الأيام التي أفطرتها، وعليها مع ذلك إطعام مسكين عن كل يوم لكونها أخرت الصيام بدون عذر، فعليها الصوم، وعليها إطعام مسكين عن كل يوم، وعليها التوبة مع ذلك، فعليها أمور ثلاثة: الصيام، والتوبة، وإطعام مسكين عن كل يوم؛ وذلك نصف صاع من قوت البلد، مقداره كيلو ونصف تقريباً، من تمرٍ، أو أرز، أو حنطة، أو شعير، هذا الواجب عليها، فعليكم أن تنصحوها، وأن تجتهدوا في حثها على البدار بأداء الواجب، قبل أن يحل بها الأجل، نعم.\nالمقدم: كونها مصابة بربع شلل، كما يقول سماحة الشيخ؟ الشيخ: ما يمنع، ما دام تستطيع الصيام ما يمنع، ولو هي مقعدة، إذا كانت تستطيع الصيام الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13304/حكم-الصيام-عمن-افطرت-رمضان-ولم-تقضه-مع-استطاعتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64205.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":14883,"question":"يقول: أصابني مرض في عام مضى، وله أكثر من أربعة أعوام في شهر رمضان، ولم أصم ذلك الشهر، ولم أقضه حتى الآن، فماذا يجب علي أن أفعل؟جزاكم الله خيرًا.","title":"حكم من أفطر رمضان ولم يقضه","answer":"الجواب: عليك التوبة إذا كنت أخرته من غير عذر، عليك التوبة إلى الله سبحانه، والندم على ما مضى منك من التفريط، والعزم الصادق أن لا تعود في مثل هذا، وعليك أن تصوم، وتطعم عن كل يوم مسكينًا أيضًا إن كنت قادرًا لأنك مفرط. وقد أفتى جماعة من الصحابة من فرط أن يطعم مسكينًا مع القضاء، فعليك أن تقضي الأيام، وعليك أن تطعم مع كل يوم مسكينًا، نصف صاع من التمر، أو الأرز، أو الحنطة، كيلو ونصف كل واحد عن كل يوم، وعليك مع ذلك التوبة إلى الله عن تقصيرك وتأخيرك؛ لأن الواجب البدار بقضائه قبل رمضان الجديد، وأنت أخرت كثيرًا، فعليك التوبة إلى الله من ذلك، وعليك القضاء قضاء الأيام، سواء متتابعة، أو مفرقة لا بأس، وعليك مع ذلك إن كنت قادر أن تطعم عن كل يوم مسكيناً، تجمع الطعام، وتعطيه بعض الفقراء بعدد الأيام، كل يوم عنه نص صاع، يعني: كيلو ونصف عن كل يوم، تجمعها وتعطيها بعض الفقراء، ولو فقيرًا واحدًا.  أما إن كنت فقيراً ما تستطيع الطعام، فإنك تصوم فقط مع التوبة، ويكفي؛ لأن الله يقول سبحانه: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13379/حكم-من-افطر-رمضان-ولم-يقضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49106.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14906,"question":"السائلة أم عادل من المدينة المنورة من أسئلتها تقول: هل يجب علي صيام قضاء من رمضان متتالي أو أيام متفرقة؟ هل هذا كله جائز؟","title":"حكم قضاء صيام رمضان مفرقًا","answer":"الجواب: يجوز القضاء متتابع، ويجوز مفرق، لا بأس بذلك؛ قضاء رمضان، أما الكفارة لا بد من تتابعها، كفارة الظهار، كفارة القتل، لا بد من التتابع.  أما كفارة الصيام الثلاثة الأيام فالذي ينبغي تتابعها، كما قال ابن مسعود  في قراءته: «فصيام ثلاثة أيام متتابعة» التتابع أولى وأحوط، أما صوم رمضان هذا لا يجب فيه التتابع، يعني: قضاء رمضان لا يجب فيه التتابع، لكن إن تابع فهو أفضل، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13405/حكم-قضاء-صيام-رمضان-مفرقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56207.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":14907,"question":"في آخر أسئلة السائلة أم عادل، من المدينة المنورة، تقول: علي قضاء مؤخر لعدة سنوات، وأريد قضاءه، فهل يجوز لي أن أشتري كيس رز، يكفي لطعام أسرة كاملة، لمدة ستين يومًا، هل يجوز لي أن أدفعه لأسرة فقيرة، وأصوم القضاء الذي علي، أم أصوم وأطعم عن كل يوم؟","title":"حكم القضاء والكفارة لمن أخرت قضاء الصوم","answer":"الجواب: إذا كان تأخير الصوم من أجل المرض، أو نحوه، فيكفي قضاء فقط، قضاء الصوم يكفي، أما إذا تساهل من أفطر في رمضان، ولم يقض وهو طيب حتى أدرك رمضان آخر، فإنه يقضي ويطعم عن كل يوم مسكينًا، وإذا جمعه وأعطاه بعض الفقراء، كفى، إذا جمع طعام الشهر كله، وأعطاه بعض الفقراء كفى. أما إذا كان تأخيره من أجل المرض ما استطاع، فلما استطاع بادر فليس عليه شيء إلا القضاء، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13406/حكم-القضاء-والكفارة-لمن-اخرت-قضاء-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56208.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":14908,"question":"رسالة وصلت إلى البرنامج من المستمع: إبراهيم موسى عبده، سوداني، أخونا يقول في رسالته:جاء رمضان وكنت عامل بناء، وكان معي عمال، وكنت أنا الوحيد بينهم الصائم، حيث كان العمل شاقًا، وفي اليوم الثاني لم أستطع الخروج إلى العمل، وكنت لا أملك طعام ذلك اليوم، وكنت أبًا لعائلةٍ كبيرة، وفي اليوم الثالث خرجت مفطرًا من البيت إلى العمل، ووجدت كل الجماعة كذلك، حيث أفطرت باقي رمضان كله، فماذا عليَّ يا سماحة الشيخ؟ علمًا بأن ذلك كان قبل عدة سنوات.","title":"ما يلزم من أفطر في رمضان بسبب مشقة العمل؟","answer":"الجواب: عليك أولاً القضاء، قضاء الأيام التي أفطرتها في الأوقات المناسبة، في الشتاء، أو في أوقاتٍ لا تحتاج فيها للعمل، تقضي الأيام التي عليك.\nوأما إفطارك، فهذا فيه تفصيل:\nإن كنت تستطيع عملًا يقوم بحالك، ليس فيه إفطار، أو يمكن أن تجد من مالك ما يغنيك عن الإفطار، وتكتفي به مدة رمضان؛ لم يجز لك الإفطار بأسباب العمل، بل عليك أن تصوم رمضان؛ لأن الله أوجب على المسلمين المستطيعين، المقيمين غير المسافرين، أوجب عليهم أن يصوموه في وقته، فعليك أن تصوم مع الناس، إذا استطعت ذلك. أما لو فرضنا أنك لم تستطع، ولم تجد عملًا في أوقاتٍ مناسبة، في الليل، أو في بعض النهار يقوم بحالك، واضطررت إلى الإفطار من أجل العمل، وأنك لا تستطيع الصوم مع العمل؛ جاز لك الإفطار للضرورة، كما يجوز للمريض الذي يشق عليه الصوم، فأنت ضررك أعظم من ضرر المريض، إذا كنت لم تجد شيئًا لنفسك وعائلتك، ولم تستطع أسبابًا أخرى تغنيك عن الإفطار، ولم تجد عملًا في الليل، أو في بعض النهار يغنيك عن هذا العمل، والله يعلم السر وأخفى، ولا تخفى عليه خافية ، فإذا كنت صادقًا ولم تجد عملًا، فأنت معذور، وعليك القضاء. وأما إن كنت قد فرطت وتساهلت فعليك التوبة مع القضاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13411/ما-يلزم-من-افطر-في-رمضان-بسبب-مشقة-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64003.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14942,"question":"أيضًا يسأل ويقول: لدي أخ أصيبت يده بكسرٍ في عام ألف وأربعمائة وسبعة، في شهر رمضان المبارك، وكان عمره ذلك الوقت ثنتي عشرة سنة، وقد صام في هذا الشهر خمسة عشر يومًا، وأفطر باقي الأيام، فهل عليه أن يقضيها؟","title":"من أفطر وعمره اثتي عشرة سنة هل عليه قضاء؟","answer":"الجواب: إذا كان لم يبلغ ليس عليه القضاء، ولكن إن قضاه فحسن، وأما إذا كان قد بلغ بإنبات الشعر الخشن حول الفرج، أو بالاحتلام؛ فإنه يقضي هذه الأيام؛ لأنه صار رجلًا، صار مكلفًا، ولو ما بلغ خمسة عشر سنة، نعم، والمرأة مثل ذلك، لكنها تزيد أمرًا رابعًا وهو الحيض، إذا حاضت بلغت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13431/من-افطر-وعمره-اثتي-عشرة-سنة-هل-عليه-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64011.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15041,"question":"مستمع من الرياض، بعث يسأل ويقول: ما حكم من فرط في شهر رمضان من شدة العمل في الحر، ولقد مضى عليه ستة أعوام، فهل يجزئ عنه الإطعام وما مقداره، أم لا بد من الصيام؟جزاكم الله خيرًا.","title":"حكم من أفطر أيامًا من رمضان للعمل وشدة الحر","answer":"الجواب: أولًا: عليه التوبة إلى الله ، والندم على ما مضى منه، والعزم الصادق ألا يعود في ذلك، ثم عليه القضاء، قضاء ذلك الشهر مع إطعام مسكين عن كل يوم إذا كان يقدر، وأما كان فقيرًا ما يستطيع فإنه يكفيه الصيام، والحمد لله مع التوبة، وهذه جريمة عظيمة، نعوذ بالله، فعليه التوبة إلى الله، والندم والإقلاع، والعزم الصادق ألا يعود، وعليه القضاء والبدار بالقضاء، وعليه مع ذلك إطعام مسكين عن كل يوم، نصف صاع يعني: كيلو ونصف عن كل يوم من طعام بيته، من أرز أو حنطة أو تمر أو غيرها من قوت البلد، فإن كان فقيرًا عاجزًا لا يستطيع ذلك سقط عنه الإطعام، وبقي عليه الصيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13541/حكم-من-افطر-اياما-من-رمضان-للعمل-وشدة-الحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49311.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15080,"question":"هذا سائل سوداني، ومقيم بالمنطقة الشرقية، يقول سماحة الشيخ، يذكر في أنه في الحادية والثلاثين من العمر، يقول: كنت لا أصلي، ولا أصوم إلا القليل، وكنت لا أبالي في ارتكاب الآثام قبل ثماني سنين، وقد من الله علي  بالتوبة والاستقامة، أحمد الله على ذلك. فأرجو من سماحتكم أن توضحوا لي ماذا أعمل بالصوم الذي لم أصمه، ولا أدري عدد الشهور والأيام، وهل يلزمني إعادة الصلوات وهل علي الحج؟","title":"حكم قضاء الصلاة والصوم لمن تاب من تركهما","answer":"الجواب: التوبة تكفي، والحمد لله، التوبة تكفي، يقول النبي ﷺ: التوبة تجب ما قبلها ويقول ﷺ: التائب من الذنب كمن لا ذنب له وهذا هو معنى قوله سبحانه: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] أجمع العلماء على أن هذه الآية الكريمة في التائبين، وأن من تاب إلى الله من شركه وكفره تاب الله عليه، وهكذا من جميع المعاصي، فليس عليك -يا أخي- قضاء للصلاة الفائتة التي تركتها، ولا للصوم، الحمد لله، قد عفا الله عنك ذلك بتوبتك، وعليك بالجد والاجتهاد في طاعة ربك، والإكثار من العمل الصالح، والله يقول سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13571/حكم-قضاء-الصلاة-والصوم-لمن-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15093,"question":"المستمع: (م. م) من عسيف، بعث يسأل ويقول: ما الحكم في شخص أفطر في رمضان بغير عذر شرعي، وهو في السنة السابعة عشرة تقريبًا، ولا يوجد له أي عذر كما قلت، فماذا يعمل؟ وهل يجب عليه القضاء؟","title":"حكم من أفطر متعمدًا في رمضان","answer":"الجواب: نعم يجب عليه القضاء، وعليه التوبة، عليه التوبة إلى الله  عن تفريطه وإفطاره وعليه القضاء، وأما ما روي عنه ﷺ أنه قال: من أفطر يومًا من رمضان بغير عذر لم يقض عنه صيام الدهر وإن صامه فهو حديث ضعيف مضطرب عند أهل العلم لا يصح. والصواب: أنه عليه القضاء ويكفيه ذلك مع التوبة، إذا قضاه قبل رمضان الآتي، أما إذا تأخر حتى فات رمضان آخر، فعليه مع القضاء إطعام مسكين عن كل يوم، وعليه التوبة إلى الله، التوبة النصوح الصادقة والندم، والعزم الصادق ألا يعود في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13590/حكم-من-افطر-متعمدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49404.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15238,"question":"السائل من تشاد، يقول في هذا السؤال سماحة الشيخ: جدتي كانت لا تصوم مع الناس، وكانت تقول: لا أصوم إلا إذا رأيت الهلال بعيني، وماتت على هذه الحالة، ولم تصم، وأنا الآن أقوم بالتصدق على الفقراء، وأقول: اللهم ألحق أجر هذه الصدقة لجدتي، وأطلب من الله -عز وجل- أن يغفر لها ذنوبها، هل دعائي هذا يصلها، وهذا الأجر يصلها سماحة الشيخ؟","title":"حكم من مات وهو تارك للصوم","answer":"الجواب:  هي غلطانة بهذا العمل، غلطانة وجاهلة، وأنت مأجور على الصدقة عنها، وإذا صمت عنها الأيام التي تركتها، فأنت مأجور، أو غيره من أقاربها، يقول النبي ﷺ: من مات وعليه صيام صام عنه وليه -يعني: قريبه- فإذا صام عنها بعض أولادها أو بعض إخوتها أو بعض أقاربها كان ذلك حسنًا وطيبًا، مع الاستغفار لها، والدعاء لها بالمغفرة والرحمة؛ لأنها جاهلة، نعم.","link":"https://binbaz.org.sa/fatwas/13738/حكم-من-مات-وهو-تارك-للصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56505.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15292,"question":"تقول السائلة (م. م. ع) أفطرت أيامًا من رمضان، منذ عدة سنوات؛ لوجود العذر الشرعي؛ لعدم علمي بوجوب قضاء تلك الأيام بعد ذلك؛ ولذلك فلم أقضها حتى الآن، ما الذي يجب علي الآن أن أفعله؟ هل هو القضاء والكفارة أم القضاء فقط أم أن عدم علمي بذلك يسقط عني القضاء؟","title":"ما الواجب على من أخرت قضاء رمضان جهلًا؟","answer":"الجواب: الواجب عليك أمور ثلاثة: التوبة إلى الله من فعلك، والقضاء أيضًا، وإطعام مسكين عن كل يوم نصف صاع، كيلو ونصف عن كل يوم من قوت البلد.  ثلاثة أمور: التوبة، والقضاء، والإطعام عن كل يوم نصف صاع، وهو كيلو ونصف من قوت البلد، نعم، يعطاها بعض الفقراء، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13781/ما-الواجب-على-من-اخرت-قضاء-رمضان-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56520.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":15302,"question":"هذا سؤال من المستمعة (ن. أ. ف) من حائل، تقول: سؤالي عن الصلاة؛ حيث أنني كنت مريضة لمدة ثلاث سنوات، ولم أصل في هذه الفترة إلا بعض الأوقات، أما الأوقات الأخرى فإني لم أستطع أن أصليها؛ لأنني كنت في حالة غيبوبة.وأيضًا أسأل عن الصيام فقد مضت سنتان لم أصم شهر رمضان فيهما من شدة المرض، وإلى الآن لم أستطع الصيام، أرجو إفادتي عماذا يجب علي فعله نحو الصيام والصلاة؟جزاكم الله خيرًا.","title":"حكم من تركت الصلاة والصيام لشدة المرض","answer":"الجواب: أما الصيام فعليك قضاء الصيام، فإذا كان تركه من أجل شدة المرض، فعليك قضاء الصيام إذا شفاك الله ؛ لأن الله قال : وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ[البقرة:185] أما إذا كان تركهما عن زوال عقل أصابك مرض أزال العقل، وصادف رمضان وأنت غير عاقلة قد زال العقل منك، فلا صيام عليك، إذا كانت المدة التي في رمضان والعقل مفقود فلا صيام؛ لأن التكليف مربوط بالعقل، فإذا زال العقل زال التكليف، أما إذا كان من شدة المرض فقط فعليك القضاء. وهكذا الصلاة؛ إن كنت تركت الصلاة من أجل زوال العقل، بسبب ما أصابك من الإغماء الذي فقدت معه العقل، حتى مضى عليك سنة أو سنتان وأنت غير عاقلة، قد ذهب عقلك فلا قضاء؛ لأن من ذهب عقله فهو شبه المجنون والمعتوه، لا قضاء عليه، أما إن كان من أجل المرض شدة المرض تساهلت ولم تصلي تحسبين أنه يجوز لكِ ذلك فعليك أن تقضي ما تركت من الصلوات التي غلب على ظنك أنك تركتيها بسبب شدة المرض، تقضينها حسب الطاقة، تسردين ما ظننت أنك تركتيه في كل وقت، تجمعين جملة من الصلوات فتقضينها لأنك تركتيها عن جهل منك وعن غلط منك بسبب المرض. والمريض يصلي على حسب حاله، يصلي قاعدًا، فإن عجز صلى على جنبه، فإن عجز صلى مستلقيًا لا يتساهل، النبي ﷺ قال للمريض: صل قائمًا فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هكذا يجب على المؤمن إذا مرض إن استطاع القيام صلى قائمًا، فإن عجز صلى وهو قاعد، ويركع ويسجد في الأرض، فإن عجز عن القعود صلى على جنبه، والأفضل على جنبه الأيمن، يقرأ ويكبر ويتعاطى ما شرع الله بالكلام، وينوي الأفعال بالنية، ينوي الركوع بالنية، ينوي السجود، ينوي الجلوس بين السجدتين بالنية، ينوي الجلوس في التحيات بالنية، ويأتي بالأقوال المشروعة من القراءة وغيرها، فإن عجز صلى مستلقيًا، يستلقي ويجعل رجليه إلى القبلة، ويصلي وهو مستلقي يكبر ويقرأ، يكبر ويركع بالنية، يقول: سمع الله لمن حمده بالنية، ويرفع بالنية، يقول: ربنا ولك الحمد، ثم يكبر ناويًا السجود، وهكذا من المضطجع على جنبه ومن المستلقي. أما إذا كنت قد فقدت الشعور قد فقدت عقلك فالمدة التي فقدت فيها عقلك المدة الطويلة، هذه لا صلاة فيها لا قضاء فيها، أما إذا كان المدة قليلة اليوم واليومين التي فقدت فيها عقلك، والباقي صاحية، فاليوم واليومين والثلاث تقضى كالنائم يقضي، فإذا طالت المدة أكثر من ثلاثة أيام طالت المدة بسبب فقد العقل والإغماء فلا قضاء على الصحيح. المقصود: أن عليك قضاء المدة التي تركت فيها الصلاة من أجل شدة المرض لا من أجل زوال العقل، فإذا كان من أجل شدة المرض هذا تساهل منك، وعليك القضاء مرتبًا؛ ظهر عصر مغرب عشاء فجر ظهر عصر، وهكذا مرتب، ولو في أيام قلائل، كل وقت تصلي فيه عدة صلوات حسب ظنك وغلبة ظنك تجتهدين وتصلينها -إن شاء الله-، هذا هو الأحوط لك والأفضل لك، نعم.\nالمقدم: بالنسبة للصيام؟\nالشيخ: والصيام كذلك، ما ترك من أجل شدة المرض تقضيه، وما كان عن زوال العقل يعني: ذهب عقلها، ولم يكن معها عقل فلا قضاء مثل المعتوه. المقدم: لا يلزمها شيء مع القضاء.\nالشيخ: ولا يلزمها إلا الصيام؛ لأنها معذورة. أما إذا كان تركك -أيها السائلة- للصلاة عن عمد وقلة مبالاة ما هو عن شبهة، وتظنين أن المرض عذر، فتركتها قلة مبالاة، وتساهلًا بها، هذا كفر وضلال، فلا تقضى بعد ذلك، التوبة تكفي، التوبة تكفي فقط؛ لأن الرسول ﷺ أخبر أن ترك الصلاة كفر، فقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فإذا كنت تركتها عمدًا لا عن شبهة، ولا عن ظن أنه يجوز لك تأخيرها من أجل المرض، فهذا منكر عظيم، وكفر صريح، فالتوبة تكفي، ولا قضاء عليك لما مضى؛ لأن تركها من غير عذر كفر وضلال وردة عن الإسلام في أصح قولي العلماء، فإذا تاب العبد من ذلك كفته التوبة فقط، نعم، نسأل الله السلامة، نعم.\nالمقدم: نسأل الله السلامة، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13821/حكم-من-تركت-الصلاة-والصيام-لشدة-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_682/nour_68205.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":15438,"question":"سؤاله الثالث يقول: أنا الآن أبلغ من العمر الثامنة والعشرين، ومنذ كان عمري سبع عشرة سنة، وأنا أصلي وأصوم، ولكن أحيانًا أترك الصلاة مدةً، ثم أعود إليها، فماذا علي الآن؟ هل يلزمني قضاء أم تكفي التوبة؟ وكيف أعمل وأنا ربما أجهل عدد الأيام التي تركت الصلاة فيها؟ وكذلك بالنسبة للصيام فقد أفطرت بعض الأيام بدون عذر، وأفطرت خلال أربع سنوات بسبب مرض، ولم يمنعني الأطباء من الصيام، ولكني أنا شعرت بضعف شديد، وهبوط في صحتي، فأفطرت، فماذا أفعل الآن؟أرشدوني، بارك الله فيكم.","title":"حكم قضاء الصيام والصلاة لمن يترك أحيانًا","answer":"الجواب: ترك الصلاة كفر أكبر، نعوذ بالله، تعمد ترك الصلاة كفر أكبر، يقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر ويقول -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة فترك الصلاة وإن كان تهاونًا كفر أكبر في أصح قولي العلماء. \nأما إن كان عن جحد لوجوبها، فهذا كفر أكبر عند جميع العلماء، لكن إذا كان عن تساهل وعن تهاون، فهذا كفر أكبر في أصح قولي العلماء. فعليك التوبة إلى الله، وليس عليك القضاء عليك التوبة الصادقة النصوح بالندم على ما مضى منك، والعزم الصادق على ألا تعود إلى هذا الشيء، والاستمرار في الصلاة، وليس عليك قضاء ما فات من الصيام والصلوات السابقة التي تركتها تهاونًا، فالصوم تابع لذلك؛ لأن ترك الصلاة كفر فليس عليك قضاء الصلاة، ولا قضاء الصيام. أما ما تركت من الصيام وأنت تصلي بعدما تاب الله عليك، وتركت هذا الذنب العظيم، فإنك تقضي الصيام. وأما إذا كان ترك الصيام في وقت ترك الصلاة، فإنك لا تقضيه، ولا تقضي الصيام؛ لأن المسلم إذا ارتد عن دينه لا يقضي، قال الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ[الأنفال:38] والنبي ﷺ يقول: الإسلام يهدم ما كان قبله، والتوبة تجب ما قبلها فإذا تاب الرجل من ترك الصلاة بعدما تركها تاب ورجع إلى الله، فإنه يستمر في العبادة، والعمل الصالح، ويسأل ربه المغفرة والعفو، وليس عليه قضاء، لا لصلاته ولا لصومه السابق الذي تركه في حال ترك الصلاة، نسأل الله السلامة. وعليك الصدق مع الله ودعائه -جل وعلا- أن يثبتك على الحق، وعليك الإكثار من العمل الصالح، كما قال الله -جل وعلا-: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى[طه:82] ولما ذكر سبحانه الشرك والقتل والزنا قال بعد هذا: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا[الفرقان:70]. فنوصيك وجميع المسلمين بالتوبة إلى الله الصادقة النصوح من جميع الذنوب، ولا سيما ترك الصلاة، فإنه ذنب عظيم، وكفر عظيم، فعليك بالمبادرة والمسارعة إلى التوبة الصادقة، والعزم الصادق أن لا تعود، والاستمرار في الصلاة، وهكذا نوصي جميع من ترك الصلاة أن يتوب إلى الله، وأن يبادر بالتوبة الصادقة النصوح، وليس عليه قضاء لما ترك قبل ذلك، نعم. المقدم: بالنسبة لتعين القضاء هل بالنسبة للعدد هو يجهل عدد الأيام التي أفطرها؟\nالشيخ: ما دام أنه في حال ترك الصلاة ما عليه قضاء، أماإذا كان مسلمًا وهو يصلي، ما عنده ناقض من نواقض الإسلام فإنه يصوم ما غلب على ظنه. المقدم: يجتهد في التقدير. الشيخ: يجتهد ويصوم ما غلب على ظنه أنه تركه، أنه أفطر فيه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13965/حكم-قضاء-الصيام-والصلاة-لمن-يترك-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_686/nour_68603.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15467,"question":"هذه سائلة للبرنامج تقول: بأنه في رمضان في عام مضى كانت ترضع طفلها في حالة الصيام، هل عليها القضاء؟","title":"حكم من أرضعت طفلها في رمضان","answer":"الجواب: إذا كانت أفطرت، نعم عليها القضاء، أما إن كانت ما أفطرت كونها ترضع ما يضر، إذا كانت صائمة، أما إذا أفطرت من أجل الرضاع عليها القضاء، وإذا تأخر عن رمضان الثاني تقضي مع إطعام مسكين عن كل يوم، أما إذا قضت قبل رمضان فليس عليها إلا القضاء، وليس عليها إطعام، تقضي الأيام التي عليها، والحمد لله، أما إن تأخرت في القضاء من دون عذر، حتى جاء رمضان آخر، عليها مع القضاء إطعام مسكين عن كل يوم نصف صاع، عن كل يوم مع القضاء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13990/حكم-من-ارضعت-طفلها-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56815.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15470,"question":"هذان سؤالان بعثت بهما الأخت (ر. ف. ي. ل) من العراق، تقول: كانت والدتي تصوم وتصلي، وقد مرضت مرضًا شديدًا منذ سنتين توفيت على إثره، ولم تكن تصوم ولا تصلي في وقت مرضها؛ لعدم الاستطاعة، فهل يلزمني دفع كفارة عنها، أو الصيام والصلاة عنها؟أفيدوني، بارك الله فيكم.","title":"حكم قضاء الصلاة والصيام عمن مات مريضًا","answer":"الجواب: ما دامت ماتت وهي مريضة ما استطاعت الصيام، فليس عليك صيام عنها، إذا كانت ماتت وهي في مرضها، لم تستطع صيامها المدة الطويلة، فإنك لا تقضين عنها شيئًا، وليس عليك إطعام أيضًا، والحمد لله. أما الصلاة فقد غلطت في ترك الصلاة، كان الواجب عليها أن تصلي، ولو كانت مريضة، ولا تؤجل الصلاة، الواجب على المريض أن يصلي على حسب حاله، إن استطاع القيام صلى قائمًا، وإن عجز صلى قاعدًا، فإن لم يستطع القعود صلى على جنبه الأيمن -وهو الأفضل- أو الأيسر على حسب طاقته، فإن لم يستطع الصلاة على جنبه صلى مستلقيًا، هكذا أمر النبي ﷺ، لما شكا إليه بعض الصحابة  المرض قال له: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا. هذا هو الواجب على المريض ذكرًا كان أو أنثى، أن يصلي قاعدًا إذا عجز عن القيام، سواء قاعدًا مستوفزًا أو متربعًا، أو كجلسته بين السجدتين، كل ذلك جائز، فإن عجز عن القعود صلى على جنبه الأيمن أو الأيسر، والأيمن أفضل إذا استطاع، ينوي أذكار الصلاة وواجباتها، ويتكلم بما يستطيع يكبر، يقرأ الفاتحة أول  شيء، يقرأ ما تيسر ثم يكبر، وينوي الركوع، ثم يقول: سمع الله لمن حمده ناويًا الرفع: ربنا ولك الحمد، إلى آخره، ثم يكبر ناويًا السجود، يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم يرفع مكبرًا، ناويًا الجلوس بين السجدتين يقول: رب اغفر لي، رب اغفر لي، ثم يكبر ناويًا السجدة الثانية، وهكذا بالنية والكلام حسب طاقته. ولا تقضى الصلاة، الصلاة لا تقضى، وإنما عليك الدعاء لها، والترحم عليها، والاستغفار إذا كانت موحدة، إذا كانت مسلمة موحدة، أما إن كانت تدعو الأموات تستغيث بالأموات والقبور، تدعو غير الله، هذه لا يدعى لها؛ لأن هذا شرك أكبر، فإذا كانت في حياتها تدعو الأموات، تستغيث بالأموات، أو بأصحاب القبور، أو تسأل البدوي، أو عبد القادر، أو غير عبد القادر الجيلاني، هذا من الشرك الأكبر؛ لأن دعاء الأموات، والاستغاثة بالأموات، كأن يقول: يا سيدي عبد القادر، اشف مريضي، أو انصرني، أو عافني، أو يا سيدي فلان -من الأموات- افعل بي كذا، أو يا رسول الله، افعل بي كذا، أو يا سيدي البدوي، افعل كذا، أو يا فلان افعل كذا من الأموات، كل هذا من الشرك الأكبر، والذي يموت على هذه الحالة لا يدعى له؛ لأنه مات على ظاهر الشرك، نسأل الله السلامة. أما إن كانت موحدة بحمد الله، لا تدعو غير الله، بل تعبد الله وحده، يدعى لها، ويستغفر لها، ولا يصلى عنها؛ لأن الصلاة لا تقضى، نعم.","link":"https://binbaz.org.sa/fatwas/14000/حكم-قضاء-الصلاة-والصيام-عمن-مات-مريضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68803.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15497,"question":"هذه السائلة نورة تقول: امرأة عليها قضاء من رمضان قبل الماضي، فهل عليها كفارة مع القضاء؟ وما مقدار ذلك؟","title":"حكم الكفارة لمن عليها قضاء من رمضان سابق","answer":"الجواب: إذا كان القضاء من رمضان سابق غير رمضان القريب، فعليها إطعام مسكين؛ لأجل تأخير القضاء، إذا كانت أخرته من دون عذر، بل بالتساهل حتى جاء رمضان آخر، فعليها القضاء مع إطعام مسكين عن كل يوم نصف صاع من قوت البلد من تمر أو غيره أو رز أو بر.  وأما إذا كان لا، أخرته لعذر لمرضها أو حملها أو رضاعها ما تيسر لها ذلك العذر تقضي فقط، وليس عليها إطعام يكفيها قضاءه، أما إذا تساهلت وأخرت من دون عذر فهي تجمع بين الأمرين بين القضاء وإطعام مسكين، عن كل يوم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14030/حكم-الكفارة-لمن-عليها-قضاء-من-رمضان-سابق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69105.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":15525,"question":"السائلة هذه أرسلت بسؤالين، تقول في سؤالها الأول: تذكر بأنها فتاة تبلغ من العمر الثالثة والثلاثين، جسمها نحيل جدًا جدًا، حيث أن وزنها أربعين كيلو غرام، داومت على صيام شهر رمضان منذ عشر سنوات في الثالث والعشرين من عمرها، ولم تستطع على الصيام في صغرها، فقد كانت لا تستطيع أن تقف في هذه الأيام الحارة، وأن تصوم، والآن تقول: أنا أداوم على الصيام مع الدعاء للمقدرة على ذلك، وتبت إلى الله عما سلف، فهل علي قضاء لما سبق؟ فأنا لا أستطيع أن أصوم هذه المدة الزمنية السابقة، فهل علي قضاء أم كفارة أم تكفي التوبة؟ يا سماحة الشيخ.","title":"حكم قضاء رمضان لمن تركت صيامه عدة سنوات","answer":"الجواب: يجب عليك القضاء، يجب عليك القضاء على حسب القدرة، لا بد أن تقضي، ولو مفرقًا، ما يلزم التتابع، تقضين كلما استطعت، تقضين حتى تكملي ما مضى عليك؛ لأنك مكلفة؛ فالواجب عليك القضاء من حين بلغت، واستعيني بالله، وأبشري بالخير، نعم. وعليها مع هذا إطعام مسكين عن كل يوم، عليك مع هذا إطعام مسكين عن كل يوم، نصف صاع عن كل يوم تجمع ويعطاها بعض المساكين، عن كل سنة خمسة عشر صاعًا يعطاها بعض الفقراء، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14060/حكم-قضاء-رمضان-لمن-تركت-صيامه-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56920.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":15648,"question":"أسأل سماحتكم عمن أفطر في نهار رمضان عامدًا متعمدًا، هل يقضي ذلك اليوم؟ وهل هناك كفارة؟","title":"حكم من أفطر في رمضان بغير عذر","answer":"الجواب: عليه التوبة إلى الله؛ لأنها جريمة، ومنكر عظيم، وكبيرة من الكبائر؛ فعليه التوبة إلى الله، وعليه القضاء، وليس عليه كفارة، الكفارة في الجماع خاصة في نهار رمضان، أما الفطر بالأكل والشرب ونحو ذلك؛ ليس فيه كفارة، بل فيه التوبة إلى الله، والندم والعزم ألا يعود في ذلك، وكثرة الاستغفار مع القضاء، قضاء اليوم الذي أفطره.  أما حديث: من أفطر في يوم من رمضان عامدًا لم يقضه صيام الدهر وإن صامه هذا حديث ضعيف عند أهل العلم، ليس بصحيح، حديث مضطرب ليس بصحيح، والصواب: أنه يقضي يومًا فقط، مع التوبة إلى الله ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14184/حكم-من-افطر-في-رمضان-بغير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70512.mp3","categories":["حكم الصلاة وأهميتها","قضاء الصيام","الرقائق"]},{"id":15660,"question":"لها سؤال أخير تقول فيه: في العام الماضي لم تستطع أن تصوم رمضان؛ لأنها كانت حاملًا، وبعد ذلك لم تستطع قضاء ذلك الشهر بسبب الرضاعة، حيث أن صحتها ضعيفة، فماذا تفعل قبل دخول رمضان هذا العام؟ وكذلك هناك سنين مضت لم تقض فيها الأيام التي أفطرتها بسبب الحيض، فماذا تفعل الآن تكفيرًا لهذا؟ وخاصة أنها لا تعرف عدد تلك الأيام وقد صامت بعضًا منها، وكثيرًا ما كان يمنعها المرض من أن تكمل ما تبقى؟","title":"حكم من أخرت القضاء إلى رمضان آخر","answer":"الجواب: عليها أولًا أن تصوم ما تبقى عليها من الأيام، وتتقي الله في ذلك، مع التوبة عما أخرته عن رمضان السابق، عليها التوبة إلى الله مما أخرت من الصيام الذي قبل رمضان السابق.  وأما ما يتعلق بالسنة الأخيرة، رمضان الأخير، فعليها أن تصومه في بقيت هذه الأيام قبل رمضان، وعليها أن تصوم ما بقي عليها من أيام ماضية، ولو بعد رمضان فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] وعليها أن تطعم عن كل يوم مسكينًا، عن كل يوم مسكينًا من الصيام السابق الذي قبل رمضان الماضي؛ لأن التأخير عن رمضان المستقبل يوجب عليها الفدية على الصحيح، فما كان قبل رمضان السابق فهذا تقضيه مع الفدية، وما كان من رمضان السابق القريب فهذا فيه القضاء من دون فدية، رمضان عام ألف وأربعمائة وثلاثة، هذا فيه القضاء من دون فدية.\nوأما ما كان قبله من الرمضانات فإنها تقضي مع الفدية عن كل يوم نصف صاع تمر أو رز، يعطاه بعض المساكين، يجمع ويعطاه بعض الفقراء. وأما كونها لا تحفظ الأيام فعليها أن تتحرى غالب الظن.\nالمقدم: تجتهد في العدد؟ الشيخ: تجتهد، وتعمل بغالب ظنها في الأيام التي عليها، ومع التوبة والاستغفار عما حصل من التأخير الذي ليس لها فيه عذر، أما ما كانت فيه معذورة من أجل المرض أو الرضاع فليس عليه فدية، إذا كانت أخرت من أجل مرض أو رضاع الذي يشق معها الصيام فهي معذورة، ولا شيء عليها، ليس عليها فدية، لكن إذا كانت تساهلت وأخرت من دون عذر، فهذا هو محل الفدية.\nالمقدم: لو بقي عليها شيء من الأيام التي من رمضان الماضي إلى ما بعد رمضان الحالي فتقضيها فقط، أو تقضي وتفدي؟ الشيخ: مثلما تقدم، إن كان قبل رمضان الماضي، يعني من رمضان ألف وأربعمائة واثنين، أو رمضان ألف وأربعمائة واحد، أو ما أشبه ذلك تقضي وتفدي إلا إذا كانت معذورة، بأن أخرت من أجل الرضاع، من أجل مرض والعجز عن القضاء فهذه ليس عليها إلا القضاء، ليس عليها فدية؛ لأنها معذورة.\nأما إن كانت تساهلت، أخرت تساهلًا وكسلًا فهذا عليها مع القضاء التوبة وعليها مع القضاء أيضًا الفدية، عن كل يوم نصف صاع من التمر أو الأرز، كيلو ونصف تقريبًا، يدفع للمساكين والفقراء عما حصل من التأخير مع القضاء، أما ما كان من رمضان هذا العام عام ثلاثة، فهذا ليس فيه فدية، تقضيه الآن هذه الأيام، والحمد لله.\nالمقدم: الفدية يجوز أن تجمع بعدد الأيام التي أفطرتها...\nالشيخ: نعم، ويعطاها بعض الفقراء.\nالمقدم: وتعطى، دفعة واحدة؟ الشيخ: نعم، دفعة واحدة، نعم.","link":"https://binbaz.org.sa/fatwas/14200/حكم-من-اخرت-القضاء-الى-رمضان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69906.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":15735,"question":"تقول السائلة: عندما كنت في الصف الثاني الثانوي في شهر رمضان، وكان ذلك في فترة الامتحانات، عندما رجعت إلى المنزل كنت أشعر بعطش شديد، فشربت ماءً، فهل أصوم ذلك اليوم، أم أطعم مساكينًا وأصوم يومًا آخرًا عنه؟","title":"حكم من أفطر في رمضان للعطش الشديد","answer":"الجواب: عليك الإمساك مع قضاء يوم، عليك أن تمسكي بعد الشرب، عليك أن تمسكي، وعليك القضاء بعد ذلك من دون إطعام، بل المبادرة بالقضاء، والحمد لله.\nلكن ليس لك الشرب إلا عند العطش الشديد تخشين معه الموت أو المرض، أما العطش الذي يمكن الصبر عليه، فليس لك الشرب، حتى تغيب الشمس في رمضان، وفي صوم الفريضة، أما إذا اشتد العطش وخفت على نفسك من المرض أو الموت فلا بأس، لكن بعد الشرب تمسكين حتى تغيب الشمس، ثم تقضين هذا اليوم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14314/حكم-من-افطر-في-رمضان-للعطش-الشديد","audio":"","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15828,"question":"هذه السائلة (م. هـ. هـ) تقول: امرأة شكت في أن عليها صيام يوم من رمضان في العام الماضي، وصامت هذا اليوم في اليوم الأخير من شهر شعبان، فهل عليها شيء في فعلها هذا؟","title":"حكم صيام آخر يوم من شعبان قضاء","answer":"الجواب: ليس عليها شيء ما دام قضاء، هذا الواجب عليها، نعم. المقدم: أحسن الله إليكم","link":"https://binbaz.org.sa/fatwas/14417/حكم-صيام-اخر-يوم-من-شعبان-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57520.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15854,"question":"امرأة لم تصم خمسة عشر يومًا من رمضان لذهاب عقلها، ولم تقضه بعد ذلك حتى أدركها رمضان الآخر، ماذا عليها؟","title":"حكم قضاء الصوم على من فقدت عقلها ثم شفيت","answer":"الجواب: إذا كان ذهب عقلها، ثم رد الله عليها عقلها؛ فليس عليها قضاء وقت ذهاب العقل، إنما تقضي ما تركت وهي عاقلة، أما لو أصابها جنون ونحوه، ثم عافاها الله لا تقضي أيام الجنون. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14445/حكم-قضاء-الصوم-على-من-فقدت-عقلها-ثم-شفيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57616.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":15858,"question":"هذه الرسالة وصلتنا من أحد الإخوة المستمعين، يقول -سماحة الشيخ-: امرأة عليها قضاء خمسة أيام من رمضان الماضي، وأتى عليها شهر رمضان الفضيل، ولم تدرك صيام الخمسة الأيام التي عليها، فما العمل بالنسبة لها؟ وماذا يجب عليها؟","title":"ما يجب على من أدركها رمضان ولم تقض ما أفطرت؟","answer":"الجواب: عليها تقضيها بعد العيد، تقضيها بالنية عن رمضان السابق، وعليها إطعام مسكين عن كل يوم زيادة، إذا كانت تأخرت، هذا تساهل، عليها إطعام مسكين، نصف صاع عن كل يوم، صاعين ونصف؛ تعطاها بعض الفقراء عن الخمسة الأيام، مع قضائها، مع التوبة إلى الله والندم والإقلاع والاستغفار؛ لأنها أخطأت في تأخيرها. أما إذا كانت أخرتها لمرض، عجز، أو رضاع، عجز، فهذا تقضيها، ولا عليها شيء، أما إذا كان تساهلًا، فالواجب عليها التوبة والندم، وقضاء الخمسة، مع إطعام مسكين عن كل يوم نصف صاع، يعني: صاعين ونصف عن الأيام الخمسة، تعطيها بعض الفقراء، واحد من الفقراء، نعم.","link":"https://binbaz.org.sa/fatwas/14449/ما-يجب-على-من-ادركها-رمضان-ولم-تقض-ما-افطرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57620.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":15886,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد، أبا عبدالله، سوداني الجنسية، مقيم في المملكة، أخونا له سؤال يقول فيه: كنت في رمضان ماش في الصحراء واضطررت للإفطار، وبعد رمضان أتممت القضاء في رابع أيام العيد، وقد صادف ذلك اليوم يوم جمعة، ولم أكن أعرف ذلك؛ لأني كنت في الصحراء، هل صيامي صحيح؟ وهل يترتب علي شيء؟جزاكم الله خيرًا.","title":"حكم قضاء الصوم في يوم الجمعة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفصيامك صحيح؛ لأنك لم ترد تخصيص الجمعة، وإنما أردت قضاء ما عليك، فالصوم صحيح، والحمد لله، وإنما النهي فيمن يخصها بالتطوع، فقد ثبت عنه ﷺ أنه نهى عن إفراد الجمعة بالصوم، وقال: لا يصومن أحدكم يوم الجمعة، إلا أن يصوم يومًا قبله، أو يومًا بعده وأنت إنما أردت قضاء ما عليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14474/حكم-قضاء-الصوم-في-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74501.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16037,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة أم أحمد من الأردن عمان، تسأل عدة أسئلة في أحد أسئلتها تقول: لقد جاء علينا شهر رمضان في سنة من السنوات في شهر تموز، وهو شهر حار جدًا، وقد ذهبت لسوء حظي في حفلة زفاف أخي، وكنت صائمة، فكانت النتيجة أنني لم أتحمل الحر الشديد، فأفطرت، هذا الكلام مضى عليه عشر سنوات، وما زلت حتى الآن أتعذب بسبب هذا اليوم، بالرغم من أنني قمت بإعادته، فماذا أفعل حتى أرضي الله تعالى؟ جزاكم الله خيرًا.","title":"حكم الإفطار لشدة الحر","answer":"الجواب: ليس عليك -بحمد الله- إلا التوبة، وقد قضيت اليوم وندمت على ما فعلت، فهذا كافي والحمد لله، يقول النبي ﷺ: التوبة تجب ما قبلها والحمد لله الذي جعل في قلبك خوف الله، ومراقبته، وخشيته سبحانه، احمدي الله على هذا، فإذا كنت ندمت على ما فعلت، وعزمت ألا تعودي لمثله، وقضيت اليوم؛ فهذا كافي، والحمد لله. وإذا كان الفطر من خطر شديد، خشيت معه الموت؛ فلا شيء عليك، والحمد لله، وأما إن كان حصل فيه تساهل؛ فالتوبة كافية والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14663/حكم-الافطار-لشدة-الحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74802.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16066,"question":"يسأل في سؤال آخر فيقول: كيف يقضي المسلم صلاته التي لم يؤدها منذ بلوغه، والتي فاتت عليه، وهل يحاسب على تركها؟ جزاكم الله خيرًا.","title":"ما حكم من ترك الصلاة فترة من الزمن؟","answer":"الجواب: عليه أن يتوب إلى الله من ذلك، وليس عليه قضاء، ومتى تاب توبة صادقة؛ محا الله عنه ذلك الكفر، وذلك الضلال، يقول الله -جل وعلا-: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فمن تاب صادقًا أفلح، ويقول النبي ﷺ: التوبة تمحو ما قبلها والتائب من الذنب كمن لا ذنب له.  والصحيح أن تارك الصلاة تكاسلًا كافر كفرًا أكبر، أما إن كان تركها جحدًا لوجوبها؛ فإنه يكون كافرًا بإجماع المسلمين، والكافر إذا أسلم لا يؤمر بالقضاء لما ترك من صلاة، وصوم، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14702/ما-حكم-من-ترك-الصلاة-فترة-من-الزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74902.mp3","categories":["حكم الصلاة وأهميتها","قضاء الصيام","الرقائق"]},{"id":16154,"question":"من المدينة المنورة رسالة وبعثت بها إحدى الأخوات من هناك، رمزت إلى اسمها بالحروف (ص) و (ف) تسأل سؤالًا تقول فيه: إذا كانت المرأة لا تتمكن من قضاء ما عليها من رمضان بعده مباشرة؛ لضعف صحتها، أو لكثرة هذه الأيام، وأيضًا لا تتمكن من صيام الست من شوال، فبماذا توجهونها؟ جزاكم الله خيرًا.","title":"حكم تأخير قضاء رمضان","answer":"الجواب: قد وسع الله لها، فلها أن تؤخر الصوم إلى شعبان، لها أن تؤخر الصوم إلى الشتاء.. إلى شعبان.. إلى رجب.. السنة كلها -بحمد الله- فيها سعة، كانت عائشة -رضي الله عنها- لا تقضي إلا في شعبان؛ لأسباب تتعلق بالرسول ﷺ وحاجته إليها. المقصود: أن الأمر فيه سعة، لكن لا تصوم الست قبل القضاء، تبدأ بالقضاء، إن قدرت، تبدأ بالقضاء، وإلا فلا شيء عليها، لا تبدأ بالست، بدل ما تصوم الست تصوم ستًا من القضاء، والحمد لله، نعم. المقدم: جزاكم الله خيرًا إذا كان ما أفطرته من رمضان كثيرًا، وهي تود أن تجمع بين القضاء، وبين صيام الست، فكيف تصوم؟ الشيخ: ولو، تبدأ بالقضاء، ولا عليها ست، تبدأ بالقضاء، ولو استغرق الشهر كله، والحمد لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم إذًا حينئذ تكفيها النية سماحة الشيخ؟ الشيخ: لها الأجر، إن شاء الله. المقدم: اللهم آمين. الشيخ: إذا كان منعها من ذلك القضاء لها الأجر، إن شاء الله، إذا شق عليها القضاء في شوال، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14828/حكم-تاخير-قضاء-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75010.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":16213,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول في أسئلته في هذه الرسالة: إذا كان الإنسان لا يصلي، ولا يصوم في فترة من حياته، ثم تاب، وأقام الصلاة، وصام رمضان، هل يلزمه قضاء الصلاة، والصيام؟ أم لا؟","title":"حكم قضاء الصلاة والصيام على من تاب من تركهما","answer":"الجواب: الصواب أنه لا يلزمه ذلك، والتوبة تكفي، والحمد لله، التوبة الصحيحة النصوح تكفي، والحمد لله يقول النبي ﷺ: التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله وتارك الصلاة يكفر بذلك، فإذا أسلم، وتاب؛ فليس عليه إعادة كسائر الكفار، إذا أرتد كسائر من ارتد، ثم رجع لا يقضي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14893/حكم-قضاء-الصلاة-والصيام-على-من-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75110.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":16241,"question":"تقول: إنني في شهر رمضان استفرغت عشرة أيام، ولم أفطر، هل علي القضاء، أم لا؟ جزاكم الله خيرًا.","title":"حكم القضاء على من استقاء في نهار رمضان","answer":"الجواب:  إن كان الاستفراغ باختيارك؛ فعليك القضاء، لقول النبي ﷺ: من ذرعه القيء؛ فلا قضاء عليه، ومن استقاء؛ فعليه القضاء أما إذا كان غلبك، ولم تختاري ذلك، ولكن غلبك، وخرج بغير اختيارك؛ فليس عليك قضاء لهذا الحديث المذكور، أما إن كنت استفرغت أنت بنفسك اختيارًا منك في الأيام العشرة؛ فإنك تقضين جميع الأيام؛ لأن الصوم بطل بذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14930/حكم-القضاء-على-من-استقاء-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80703.mp3","categories":["قضاء الصيام","مفسدات الصيام"]},{"id":16356,"question":"أخيرًا يسأل سماحتكم ما حكم من أفطر في رمضان بدون عذر؟","title":"حكم من أفطر في رمضان بدون عذر","answer":"الجواب: حكمه أنه عاص لله، وعليه التوبة، وقضاء اليوم، إذا أفطر في رمضان من دون عذر؛ فهو قد عصى ربه، وتعرض لغضبه، ولا حول ولا قوة إلا بالله، وعليه التوبة، والقضاء، عليه التوبة حالًا والقضاء بعد رمضان، قضاء اليوم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15050/حكم-من-افطر-في-رمضان-بدون-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71419.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16459,"question":"الرسالة التالية بتوقيع أحد الإخوة المستمعين وقع في نهايتها بقوله: أخوكم في الله: عبدالله، له جمع من الأسئلة في أحدها يقول: عندما يتوب الإنسان، ويمن الله عليه بالهداية، هل يقضي أشهر رمضان التي لم يصمها، وإذا كان الإنسان عامدًا متعمدًا في الإفطار بما هو من شهوات النفس، هل يلزمه ذلك، أم أنه يكفي أن يطعم عن كل يوم مسكينًا؟ جزاكم الله خيرًا.","title":"ما الواجب على من أفطر عدة رمضانات متعمدًا؟","answer":"الجواب: عليه أن يصوم ما أفطر مع التوبة إلى الله  ولا يجزئه الإطعام ما دام يستطيع الصيام، عليه أن يتوب إلى الله  مما فعل، وعليه أن يبادر بالصوم مع إطعام مسكين عن كل يوم إذا كان أخر الصوم إلى رمضان آخر، وهذه جريمة عظيمة، ومنكر عظيم. لكن إن كان لا يصلي؛ صار كافرًا، والكافر لا يقضي، إذا كان لا يصلي؛ كان كافرًا، والكافر لا يقضي في أصح قولي العلماء، فأما إن كان يصلي، ولكنه ترك الصيام؛ فإنه لابد من القضاء مع إطعام مسكين عن كل يوم إذا كان القضاء تأخر إلى رمضان آخر، نسأل الله أن يمن علينا، وعلى كل مسلم بالتوبة النصوح، نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15182/ما-الواجب-على-من-افطر-عدة-رمضانات-متعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81302.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16478,"question":"تقول: أفطرت من رمضان يومًا واحدًا قبل عدة سنوات ولم أصمه، وفيما أرى أنني لا أستطيع القضاء، فبم توجهونني؟ جزاكم الله خيرًا.","title":"توجيه لمن أفطر في رمضان ولا يستطيع القضاء","answer":"الجواب: إذا كنت لا تستطيعين القضاء لمرض ملازم، أو كبر سن؛ فعليك أن تصدقي بنص صاع عن هذا اليوم، كيلو ونص من التمر، أو نحوه من قوت البلد: تمر، أو حنطة، أو أرز لبعض الفقراء، مع التوبة والاستغفار عما حصل من التأخير والندم. أما إن استطعت القضاء؛ يجب عليها القضاء، تصومين هذا اليوم مع إطعام مسكين عن التأخير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15190/توجيه-لمن-افطر-في-رمضان-ولا-يستطيع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75604.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16484,"question":"من القصيم أخوكم الذي رمز لاسمه بـ (س. ر) يقول بأنه شاب يبلغ من العمر الثالثة والعشرين، يقول: وكنت فيما مضى من الأيام من عمري متهاونًا في أداء الصلوات، وحتى الصوم، فقد مرت علي شهور من رمضان أفطرت فيها أيامًا بدون عذر شرعي، وإنما تهاونًا، فإذا شعرت بالجوع، أو العطش؛ أفطرت، وبعد أن من الله علي بالتوبة، والهداية، وأيقنت بخطورة هذا الأمر؛ واظبت على الصلاة، ولكن الذي يؤلمني يا سماحة الشيخ هذه الأيام التي مضت من عمري عن تلك الصلوات، وعن أيام الصيام التي أفطرت فيها، كيف أبرئ ذمتي؟ جزاكم الله خيرًا.","title":"ما الواجب على من ترك الصلاة والصوم ثم تاب؟","answer":"الجواب: الواجب عليك يا أخي التوبة إلى الله، والحمد لله، ما دمت تبت إلى الله، وندمت، وأقلعت، وأصلحت؛ كفى ذلك، والحمد لله، ولا يلزمك قضاء الصلوات، ولا قضاء الصيام؛ لأن ترك الصلاة كفر، والتوبة تكفي، تجب ما قبلها، ما دمت تبت إلى الله؛ فالتوبة تجب ما قبلها، يقول النبي ﷺ: التوبة تجب ما قبلها ويقول ﷺ: التائب من الذنب كمن لا ذنب له. فالذي تاب من ترك الصلاة، وتاب من ترك الصيام، لا قضاء عليه، أما الصيام الذي تركته بعدما حافظت على الصلاة، إذا كنت تركت شيئًا من الصيام بعد أن حافظت على الصلوات؛ فإنك تقضي، أما الصيام الذي تركته مع ترك الصلاة؛ فالتوبة تكفي فيه، والحمد لله، أما إذا كان هناك أيام تركت صومها بعدما من الله عليك بالتوبة من ترك الصلاة؛ فإنك تقضيها. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15191/ما-الواجب-على-من-ترك-الصلاة-والصوم-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58213.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":16539,"question":"من إحدى الأخوات المستمعات بعثت برسالة تقول فيها: عندما كنت صغيرة وحضت لم أعرف أي شيء عن الحيض، وأنه يجب الإفطار في رمضان، وقضاؤه بعد ذلك، وكنت أصلي في مدة الحيض كالأيام العادية، ولم يكن أحد يعلم عن ذلك، حتى أمي، ومضت سنتان، ثم درست، وتعرفت، ولكن أنساني الشيطان القضاء السابق في بداية الحيض، وعندما بلغت الرابعة والعشرين من العمر، تذكرت بقدرة الله، فاجتهدت في عدد الأيام، فكانت اثني عشر يومًا، فقضيتها، وأخرجت عن كل يوم إطعام مسكين، وجمعتها، ووزعتها من قوت البلد، هل ما فعلته صحيح؟ أم توصونني بشيء آخر؟","title":"حكم من أفطر أيامًا من رمضان لا يعرف عددها","answer":"الجواب: قد أحسنت في ذلك، هذا الذي فعلت طيب، وقد أحسنت في ذلك مع التوبة اللازمة، مع التوبة والندم على ما حصل من التأخير، وفقك الله، وتقبل منك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15280/حكم-من-افطر-اياما-من-رمضان-لا-يعرف-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81510.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":16589,"question":"المستمع (م. ع. م) سوداني بعث يسأل، ويقول: ما حكم من فرط في شهر رمضان نسبة لانشغاله بعمل شاق، وكيف يكون القضاء؟ وإذا كان لم يستطع القضاء هل تكفي الكفارة؟ وإذا أخر القضاء إلى أن يرجع إلى بلده هل له ذلك؟ جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان لأجل العمل","answer":"الجواب: أولًا عليه التوبة من ترك الصيام، عليه التوبة إلى الله -جل وعلا- والندم، والإقلاع، والعزم ألا يعود في ذلك؛ لأن تركه الصيام مع القدرة جريمة، ومنكر، وكبيرة من كبائر الذنوب؛ فعليه التوبة إلى الله بالندم على ما مضى منه، والعزم الصادق ألا يعود فيه، وعليه قضاء رمضان، وإذا قضاه قبل رمضان آخر؛ فليس عليه إلا التوبة، والقضاء، أما إن تأخر القضاء إلى رمضان آخر؛ فعليه مع التوبة والقضاء إطعام مسكين عن كل يوم زيادة يكون عليه ثلاثة أمور: التوبة، والقضاء، وإطعام مسكين عن كل يوم إذا تأخر القضاء إلى رمضان آخر. أما إن قضى قبل رمضان؛ فالتوبة تكفي مع القضاء، يقضي والتوبة، والندم مع ذلك، نسأل الله الهداية للجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15328/حكم-من-افطر-في-رمضان-لاجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81710.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16590,"question":"يسأل يقول: كيف تقضي المرأة التي تركت الصلاة، والصيام لعذرها الشرعي، كيف تقضي ما فاتها؟","title":"كيفية القضاء لمن تركت الصلاة لعذر أو متعمدة","answer":"الجواب: إن كان عذرها الحيض والنفاس؛ فليس عليها قضاء الصلاة، إنما تقضي الصوم فقط، صوم رمضان، أما إن كان عذرها نومًا، واستيقظت؛ تقضي إذا استيقظت من نومها، وأما إن كانت مجنونة، ثم رد الله عليها العقل؛ فليس عليها قضاء. أما إن كانت مريضة؛ فالواجب عليها أن تصلي في حال المرض، ولو على جنب، ولو مستلقية، فإن تساهلت جهلًا منها، ولم تصل لأجل المرض؛ تقضيها مرتبة، ولو في وقت واحد، حسب طاقتها مرتبة؛ ظهر، عصر، مغرب، عشاء، فجر، هكذا مرتبة، ولو في وقت واحد، ولو في ضحوة، أو في ظهر، أو في ليلة حسب طاقتها، إذا كان تركها لها عن مرض، تجهل أنها تصلي وهي قاعدة، أو على جنبها؛ تقضي. أما إن كان التساهل بالصلاة، تتركها عمدًا؛ فليس عليها قضاء، عليها التوبة، وهكذا الرجل الذي لا يصلي، ثم يتوب، ليس عليه قضاء، عليه التوبة إلى الله، والرجوع إلى الله، والاستقامة على الصلاة، وما فات قبل ذلك مما تركه عمدًا تساهلًا منه؛ فهذا فيه التوبة، وتكفيه التوبة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15323/كيفية-القضاء-لمن-تركت-الصلاة-لعذر-او-متعمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81706.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":16600,"question":"المستمع (م. ع. م) سوداني بعث يسأل، ويقول: ما حكم من فرط في شهر رمضان نسبة لانشغاله بعمل شاق، وكيف يكون القضاء؟ وإذا كان لم يستطع القضاء هل تكفي الكفارة؟ وإذا أخر القضاء إلى أن يرجع إلى بلده هل له ذلك؟ جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان لأجل العمل","answer":"الجواب: أولًا عليه التوبة من ترك الصيام، عليه التوبة إلى الله -جل وعلا- والندم، والإقلاع، والعزم ألا يعود في ذلك؛ لأن تركه الصيام مع القدرة جريمة، ومنكر، وكبيرة من كبائر الذنوب؛ فعليه التوبة إلى الله بالندم على ما مضى منه، والعزم الصادق ألا يعود فيه، وعليه قضاء رمضان، وإذا قضاه قبل رمضان آخر؛ فليس عليه إلا التوبة، والقضاء، أما إن تأخر القضاء إلى رمضان آخر؛ فعليه مع التوبة والقضاء إطعام مسكين عن كل يوم زيادة يكون عليه ثلاثة أمور: التوبة، والقضاء، وإطعام مسكين عن كل يوم إذا تأخر القضاء إلى رمضان آخر. أما إن قضى قبل رمضان؛ فالتوبة تكفي مع القضاء، يقضي والتوبة، والندم مع ذلك، نسأل الله الهداية للجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15328/حكم-من-افطر-في-رمضان-لاجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81710.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16601,"question":"يسأل يقول: كيف تقضي المرأة التي تركت الصلاة، والصيام لعذرها الشرعي، كيف تقضي ما فاتها؟","title":"كيفية القضاء لمن تركت الصلاة لعذر أو متعمدة","answer":"الجواب: إن كان عذرها الحيض والنفاس؛ فليس عليها قضاء الصلاة، إنما تقضي الصوم فقط، صوم رمضان، أما إن كان عذرها نومًا، واستيقظت؛ تقضي إذا استيقظت من نومها، وأما إن كانت مجنونة، ثم رد الله عليها العقل؛ فليس عليها قضاء. أما إن كانت مريضة؛ فالواجب عليها أن تصلي في حال المرض، ولو على جنب، ولو مستلقية، فإن تساهلت جهلًا منها، ولم تصل لأجل المرض؛ تقضيها مرتبة، ولو في وقت واحد، حسب طاقتها مرتبة؛ ظهر، عصر، مغرب، عشاء، فجر، هكذا مرتبة، ولو في وقت واحد، ولو في ضحوة، أو في ظهر، أو في ليلة حسب طاقتها، إذا كان تركها لها عن مرض، تجهل أنها تصلي وهي قاعدة، أو على جنبها؛ تقضي. أما إن كان التساهل بالصلاة، تتركها عمدًا؛ فليس عليها قضاء، عليها التوبة، وهكذا الرجل الذي لا يصلي، ثم يتوب، ليس عليه قضاء، عليه التوبة إلى الله، والرجوع إلى الله، والاستقامة على الصلاة، وما فات قبل ذلك مما تركه عمدًا تساهلًا منه؛ فهذا فيه التوبة، وتكفيه التوبة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15323/كيفية-القضاء-لمن-تركت-الصلاة-لعذر-او-متعمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81706.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":16618,"question":"رسالة وصلت إلى البرنامج من الدمام، وباعثها المستمع (ف. ح. ش) يقول: ما حكم صيام يوم الجمعة فقط قضاء لا تطوعًا؟ وهل يجب صيام يوم قبله، أو يوم بعده؟","title":"حكم صيام يوم الجمعة قضاء","answer":"الجواب: أما في التطوع فلا بد من صوم يوم قبله، أو يوم بعده؛ لأن الرسول ﷺ نهى أن يصام الجمعة، قال: إلا أن تصوموا يومًا قبله، أو يومًا بعده ولما صامت إحدى زوجاته ﷺ يوم الجمعة، قال: هل صمت أمس؟ قالت: لا، قال: هل تصومين غدًا؟ قالت: لا، قال: أفطري. أما إذا كان عن فريضة؛ فلا حرج -إن شاء الله- لأنه ما خص الجمعة، ولكن وافقت الجمعة أنها وقت راحته، وعدم العمل، أو لأسباب أخرى؛ فصام الجمعة عن قضاء ما عليه من رمضان، أو نذر، أو غير ذلك، فهذا لم يخصها لأنها لفضلها، وإنما صامها من أجل أنها أيسر له في قضاء ما عليه بسبب الأعمال، وإن صام يومًا قبلها، أو يومًا بعدها على سبيل الاحتياط؛ فهو أحسن، من قضائه، يصوم يومين جميعًا، أو ثلاثة: الخميس والجمعة والسبت؛ يكون هذا أبعد عن الشبهة: دع ما يريبك إلى ما لا يريبك. أما النهي فهو جاء في النهي عن التطوع بها، لا يطوع بها وحدها، بل يكون قبلها يوم، أو بعدها يوم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15353/حكم-صيام-يوم-الجمعة-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75823.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16651,"question":"ما قول سماحتكم فيمن بلغت في سن صغيرة، ولم تتعرف على أحكام الدين، وأمور الشرع المتعلقة بها بالقدر الذي وصلت إليه من المعرفة بها حاليًا، فلم تصل، ولم تصم، ولم تتحجب عن الأجانب، ثم بعد أن عرفت أحكام الدين في هذا الأمر احتجبت، وأصبحت تصلي، وتصوم بعد أن كانت تصوم صيام الأطفال، تفطر متى شاءت، وتصوم متى طاقت ذلك، الآن هل يلزمها قضاء ما فاتها من الصيام، والصلاة؟ وهل يلزمها إلى جانب قضاء الصيام صدقة؟ وإذا كان هناك صدقة، فما مقدارها؟ علمًا بأن الفترة التي أمضتها، وهي جاهلة بأحكام الشرع، ولا تلتزم بها سنتان ونصف، جزاكم الله خيرًا.","title":"حكم قضاء الصلاة والصوم لمن تركهما بلا عذر","answer":"الجواب: الصواب أنه لا يلزمها شيء، ويكفي التوبة؛ لأن الرسول ﷺ لم يأمر الذين أسلموا أن يقضوا ما فاتهم من صلاة، وصيام؛ولأن ترك الصلاة كفر، فالتوبة تكفي في هذا، فإذا كانت لا تصلي، ولا تصوم، فالتوبة كافية، وليس عليها قضاء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15384/حكم-قضاء-الصلاة-والصوم-لمن-تركهما-بلا-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71714.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17136,"question":"تقول أختنا: وضعت في شهر رمضان، وأفطرت نصف الشهر، وهذه الحادثة لها عامان، ولم أقض بعد، فبماذا توجهونني؟ هل علي كفارة؟ وما هي؟ هل هي فلوس؟ أم إطعام من طعام البلد؟ جزاكم الله خيرًا.","title":"حكم من أخرت قضاء رمضان لمدة عامين","answer":"الجواب: عليك القضاء والتوبة إلى الله من التأخير إذا كان التأخير من غير علة، وعليك إطعام مسكين عن كل يوم من قوت بلدك، من ذرة، أو شعير، أو حنطة، أو رز، أو تمر من قوت البلد، نصف صاع، يعني: كيلو ونصف تقريبًا لبعض الفقراء عن كل يوم، تجمع، ويعطاها فقير واحد، أو بيت فقير، وعليك التوبة إلى الله، والندم، وعدم العود لمثل هذا إذا كنت أخرت بدون عذر شرعي، نسأل الله للجميع الهداية. نعم.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16028/حكم-من-اخرت-قضاء-رمضان-لمدة-عامين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83209.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":17139,"question":"يقول في سؤال آخر: لي عمة، وقد كانت حاملًا في الشهر التاسع، وهم بدوٌ يرحلون على المواشي مسافات طويلة، في ذات مرة اشتد عليها العطش، فأفطرت، وهي صائمة في رمضان، ولا تدري عن حكم القضاء، وقد مضى على هذه الحادثة ما يقرب من خمس وعشرين سنة، فما الحكم الآن؟ جزاكم الله خيرًا.","title":"حكم من أفطرت لشدة العطش ولم تقض جهلًا","answer":"الجواب: عليها القضاء، وإطعام مسكين مع القضاء نصف صاع تمر، أو رز، أو حنطة لبعض الفقراء مع التوبة، والاستغفار عما حصل من التأخير، وعدم السؤال، والاستفتاء.. عليها التوبة إلى الله؛ لأنها قصرت في عدم الاستفتاء، وعليها أن تصوم اليوم وعليها أن تطعم مسكينًا واحدًا، نصف صاع من قوت بلدها، نسأل الله أن يصلح حال الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16019/حكم-من-افطرت-لشدة-العطش-ولم-تقض-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83207.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":17287,"question":"الأخوات أم أمل، وأم رقية، وأم عبدالرحمن من تبوك لهن مجموعة من الأسئلة، سؤالي الأول سماحة الشيخ تذكر إحداهن وتقول: بأنها فتاة تبلغ من العمر إحدى وعشرين عامًا، وكانت تقول سابقًا ترعى الغنم في رمضان، وكانت تشرب دون أن يعلم بها أحد إلا الله  وذلك جهلًا منها تقول، والآن تذكرت تلك الأيام، وتريد الآن أن تقضي ما عليها، لكن لا تدري كم عدد هذه الأيام، هل هي قليلة، أم كثيرة؟ ولم يغلب على ظنها كم عدد هذه الأيام؟ تقول: وجهوني يا سماحة الشيخ؟","title":"حكم الفطر في رمضان جهلًا","answer":"الجواب: إذا كان ذلك بعدما بلغت وأرشدت؛ عليها القضاء، أما إذا كان ذلك قبل البلوغ، قبل أن تكمل خمسة عشر سنة، قبل أن تحيض، إذا كان وهي صغيرة؛ ما عليها قضاء، أما إذا كان بعد البلوغ فعليها القضاء بالتحري بالتحري .. عشره أيام.. عشرين يومًا.. ثلاثين يومًا، تتحرى حسب طاقتها، وتصوم. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16131/حكم-الفطر-في-رمضان-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59307.mp3","categories":["مفسدات الصيام","قضاء الصيام"]},{"id":17307,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (س. ف) أخونا عرضنا بعض أسئلته في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد يقول فيه: لماذا إذا لم يصل الشخص يكون خارجًا عن الملة؟ وإذا تاب لا يقضي صلواته التي لم يصلها؟ ولماذا يقضي صومه إذا تاب؟ علمًا بأني لم أكن أصلي من قبل، أفيدوني عن هذه القضايا، جزاكم الله خيرًا.","title":"الفرق بين تارك الصلاة وتارك الصيام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.. أما بعد.  فينبغي أن يعلم أن الأحكام الشرعية إنما تؤخذ عن الله، وعن رسوله -عليه الصلاة والسلام- لا عن آراء الناس، فالأحكام التي يحكم بها على العباد في كفر، أو إيمان، أو طاعة، أو معصية إنما تؤخذ عن الله، وعن رسوله -عليه الصلاة والسلام- فمن ترك الصلاة فقد حكم عليه الرسول ﷺ بأنه كافر، كما أن من أشرك بالله، وعبد معه غيره فقد حكم الله عليه ورسوله بأنه كافر، وهكذا من استهزأ بالله، ودينه حكم الله عليه بأنه كافر. وهناك أحاديث أخرى كلها تدل على كفر تارك الصلاة؛ لأنها عمود الإسلام، وأعظم الأركان بعد الشهادتين، فلهذا كفر تاركها، وإذا أسلم لا يؤمر بالقضاء؛ لأن الرسول ﷺ لم يأمر الذين ارتدوا، ثم أسلموا أن يقضوا، بل قبل منهم إسلامهم، ولم يأمرهم بالقضاء، وهكذا الصحابة  لما قاتلوا أهل الردة لم يأمروهم بالقضاء بعدما أسلموا؛ لأن الإسلام يجب ما قبله، الإسلام توبة عظيمة تهدم ما قبلها؛ ولأن مطالبة الإنسان بقضاء ما فاته في حال الردة قد ينفره من الإسلام، قد يحول بينه وبين الدخول في الإسلام، فكان من حكمة الله ومن إحسانه إلى عباده أن جعل الإسلام يهدم ما كان قبله، يقول النبي ﷺ: الإسلام يهدم ما كان قبله فمن أسلم غفر الله له ما مضى من شرك، وغيره. أما من ترك الصيام فإنه مسلم لا يكون كافرًا إذا كان لم يجحد الوجوب، إذا كان ما جحد وجوب صوم رمضان، بل يعلم أنه واجب عليه، ولكن تكاسل، فأفطر في بعض الأحيان، هذا يكون عاصيًا، وعليه القضاء، والتوبة إلى الله . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16152/الفرق-بين-تارك-الصلاة-وتارك-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83301.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17320,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (س. ف) أخونا عرضنا بعض أسئلته في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد يقول فيه: لماذا إذا لم يصل الشخص يكون خارجًا عن الملة؟ وإذا تاب لا يقضي صلواته التي لم يصلها؟ ولماذا يقضي صومه إذا تاب؟ علمًا بأني لم أكن أصلي من قبل، أفيدوني عن هذه القضايا، جزاكم الله خيرًا.","title":"الفرق بين تارك الصلاة وتارك الصيام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.. أما بعد.  فينبغي أن يعلم أن الأحكام الشرعية إنما تؤخذ عن الله، وعن رسوله -عليه الصلاة والسلام- لا عن آراء الناس، فالأحكام التي يحكم بها على العباد في كفر، أو إيمان، أو طاعة، أو معصية إنما تؤخذ عن الله، وعن رسوله -عليه الصلاة والسلام- فمن ترك الصلاة فقد حكم عليه الرسول ﷺ بأنه كافر، كما أن من أشرك بالله، وعبد معه غيره فقد حكم الله عليه ورسوله بأنه كافر، وهكذا من استهزأ بالله، ودينه حكم الله عليه بأنه كافر. وهناك أحاديث أخرى كلها تدل على كفر تارك الصلاة؛ لأنها عمود الإسلام، وأعظم الأركان بعد الشهادتين، فلهذا كفر تاركها، وإذا أسلم لا يؤمر بالقضاء؛ لأن الرسول ﷺ لم يأمر الذين ارتدوا، ثم أسلموا أن يقضوا، بل قبل منهم إسلامهم، ولم يأمرهم بالقضاء، وهكذا الصحابة  لما قاتلوا أهل الردة لم يأمروهم بالقضاء بعدما أسلموا؛ لأن الإسلام يجب ما قبله، الإسلام توبة عظيمة تهدم ما قبلها؛ ولأن مطالبة الإنسان بقضاء ما فاته في حال الردة قد ينفره من الإسلام، قد يحول بينه وبين الدخول في الإسلام، فكان من حكمة الله ومن إحسانه إلى عباده أن جعل الإسلام يهدم ما كان قبله، يقول النبي ﷺ: الإسلام يهدم ما كان قبله فمن أسلم غفر الله له ما مضى من شرك، وغيره. أما من ترك الصيام فإنه مسلم لا يكون كافرًا إذا كان لم يجحد الوجوب، إذا كان ما جحد وجوب صوم رمضان، بل يعلم أنه واجب عليه، ولكن تكاسل، فأفطر في بعض الأحيان، هذا يكون عاصيًا، وعليه القضاء، والتوبة إلى الله . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16152/الفرق-بين-تارك-الصلاة-وتارك-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83301.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17354,"question":"من الخرج المستمعة أمل الصالح تقول: أنا فتاة أبلغ من العمر السابعة عشرة، وقد تذكرت أن علي بعض الأيام من شهر رمضان لم أصمها، وكانت في ذلك الوقت أول سنة من بلوغي، حيث كان عمري إحدى عشرة سنة، وأنا لا أدري عن عدد الأيام التي أفطرتها، وجهوني كيف يكون القضاء؟ جزاكم الله خيرًا.","title":"كيفية قضاء صيام الأيام التي لا يعلم عددها","answer":"الجواب: عليك أن تصومي حسب ظنك واجتهادك، اعملي بالظن في الأيام التي أفطرتيها، ويكفي، والحمد لله، تجتهدين، فإذا كنت تظنيها سبعًا صومي سبعًا، تظنينها ثمانًا ثمانًا، عشرًا عشرًا حسب الاجتهاد، والتحري لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16215/كيفية-قضاء-صيام-الايام-التي-لا-يعلم-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83408.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":17424,"question":"رسالة وصلت إلى البرنامج من المستمع خالد الحربي يقول في رسالته: يوجد لي جد مصاب بالجلطة، غاب عن ذهنه لمدة ثلاثة أشهر، وهو الآن قد عاد، وبدأ يذكر الصلاة، وبدأ يصلي، لكنه لم يصم بطبيعة الحال، فكيف توجهوننا وحاله ما ذكر؟ جزاكم الله خيرًا.","title":"حكم قضاء الفرائض لمن فقد عقله مدة من الزمن","answer":"الجواب:  ليس عليه قضاء ما فات في حال ذهاب عقله، وليس عليه قضاء الصوم إذا كان رمضان صادفه في المدة التي غاب فيها عقله؛ لأنه قد رفع عنه القلم، وإنما يصلي مستقبلًا بعدما رجع إليه عقله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16286/حكم-قضاء-الفراىض-لمن-فقد-عقله-مدة-من-الزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83515.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17480,"question":"يقول السائل: سماحة الشيخ! حاليًا أعمل هنا في المملكة حيث كنت لا أصلي في جميع الأوقات، والآن -ولله الحمد- التزمت، وأصوم أيام ثلاثة عشر، وأربعة عشر، وخمسة عشر من كل شهر -والحمد لله- كما أداوم على قراءة القرآن الكريم في أكثر الأوقات، و كنت في السابق لم أصل إلا ما ندر، ولا أصوم في رمضان، وهجرت القرآن، هل علي إعادة لتلك الأيام سماحة الشيخ؟","title":"حكم قضاء التائب للصلاة والصوم","answer":"الجواب: ليس عليك إعادة، التوبة تجبُّ ما قبلها، والإسلام يهدم ما كان قبله، والحمد لله، ما دمت رجعت إلى دين الله، وأسلمت وتبت؛ فالذي مضى ليس عليك قضاء، ولكن عليك لزوم التوبة والاستقامة، وكثرة العمل الصالح، والاستغفار، وأبشر بالخير، أبشر بالخير، التوبة تجبُّ ما قبلها، والإسلام يهدم ما كان قبله، والحمد لله، نعم. المقدم: بعض الشباب سماحة الشيخ يتذكر تلك الأيام، ويوسوس له الشيطان عن تلك الأيام التي لم يصلها، أو لم يصم فيها، هل من توجيه لأولئك الذين عادوا إلى الله؟ الشيخ: لا، عليه أن يتعوذ بالله من الشيطان، إذا خطر له هذه الوساوس؛ عليه أن يقول: أعوذ بالله من الشيطان الرجيم، يتعوذ بالله من الشيطان الرجيم، يحسن ظنه بربه، ويكثر من الاستغفار، ويكثر من التعوذ بالله من الشيطان، ولا يضره ذلك، الشيطان يوسوس، ويؤذي المؤمن، ولكن عليه أن يكون قويًا ضد عدو الله، وأن يستعيذ بالله من الشيطان، وأن يحذر الوساوس، ويحمد ربه على ما منَّ به عليه من التوبة. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16388/حكم-قضاء-التاىب-للصلاة-والصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77315.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17627,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول أم عبد الرحمن، أم عبد الرحمن لها جمع من الأسئلة تقول في أحدها: إنها امرأة في الخامسة والعشرين من عمرها كانت في سابق حياتها لا تقضي الأيام التي أفطرتها في رمضان ولا تذكر المدة بالتحديد، ولا تعلم إذا كانت في تلك المدة التي لم تصم فيها كانت تصلي أو لا، وتستمر على هذا الحال وتصف نفسها بالجهل وترجو من سماحة الشيخ التوجيه؟","title":"حكم من أفطر في رمضان أيامًا لا يعلم عددها","answer":"الجواب: عليك التوبة إلى الله وقضاء الأيام بالظن، الأيام التي أفطرتها تقضينها بالظن ولو مفرقة من غير تتابع تصومين وتفطرين وتصومين حتى تكملي حسب ظنك؛ شهر.. شهرين.. ثلاثة.. حسب ما ظننت الأيام التي أفطرتيها في السنوات الماضية تقضينها مع التوبة والاستغفار ومع إطعام مسكين عن كل يوم إن كنت قادرة وإن كنت فقيرة لا تستطيعين فالصوم كافي ولا حاجة إلى الإطعام، أما إن قدرتي فأطعمي عن كل مسكين يوم عن عشرة أيام خمسة أصواع عن عشرين يوم عشرة أصواع.. وهكذا كل يوم نص صاع تجمع ويعطاها بعض الفقراء أو بيت فقير والحمد لله، والتوبة تجب ما قبلها والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16556/حكم-من-افطر-في-رمضان-اياما-لا-يعلم-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84402.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":17718,"question":"الأخت السائلة تذكر بأنها امرأة حاضت وهي في الخامسة الابتدائي وبدأت الصيام ولكن في الثلاث السنوات الأولى التي بعد البلوغ لم تصم رمضان وكانت تجهل الحكم ما الذي يلزمها الآن؟","title":"ما يلزم من أفطرت عدة رمضانات جهلًا بعد بلوغها؟","answer":"الجواب: عليها القضاء ما دام أتاها الحيض وهي صغيرة بنت تسع سنين أو عشر سنين عليها أن تقضي ما تركت. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16679/ما-يلزم-من-افطرت-عدة-رمضانات-جهلا-بعد-بلوغها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77623.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":17804,"question":"السائل يقول في هذا السؤال سماحة الشيخ: أنا رجل أبلغ حوالي السبعين وعلي أشهر لا أعرف عددها من رمضان لم أصمها حتى اليوم وأنا بصحة جيدة والحمد لله وأعيش في البادية وأفكر بأن أكفر عن ذلك، ما الحكم وهل يجب علي الصوم؟","title":"حكم التساهل في قضاء أيام رمضان","answer":"الجواب: يجب عليك أن تصوم ما فرطت فيه، عليك أن تصوم وتطعم عن كل يوم مسكينًا نصف صاع عن كل يوم كيلو ونصف؛ لأنك مفرط أخرت الصيام بغير عذر فعليك التوبة إلى الله وقضاء الشهور الماضية من رمضان وإطعام مسكينًا عن كل يوم إن كنت تقدر عندك مال تستطيع الإطعام مع التوبة والاستغفار، وهذا خطأ عظيم، وتفريط كبير، نسأل الله لنا ولك الهداية.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16793/حكم-التساهل-في-قضاء-ايام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77816.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":17903,"question":"إذا سافرت في شهر رمضان إلى منطقة يباح لي الإفطار فيها وأمضيت مدة عشرين يومًا في ذالكم السفر كيف تنصحونني إذا أردت القضاء؟ جزاكم الله خيرًا.","title":"كيفية قضاء الصيام لمن كان مسافرًا","answer":"الجواب: تقضي إن شئت متتابعًا وإن شئت مفرقًا، والحمد لله، تقضي ما أفطرت سواءً كان ذلك متتابعًا أو مفرقًا، الأمر في هذا واسع والحمد لله، إن تابعت فهو أفضل وإن فرقت فلا حرج.\nالمقدم: جزاكم الله خيرًا. ماذا لو أخر إذا جاء رمضان آخر سماحة الشيخ؟\nالشيخ: لا يؤخر إلى رمضان، الواجب أن يقضي قبل رمضان، فلو أخر بغير عذر عليه القضاء والتوبة وعليه إطعام مسكينًا عن كل يوم زيادة، نصف الصاع عن كل يوم، مع التوبة، ومع القضاء.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16932/كيفية-قضاء-الصيام-لمن-كان-مسافرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84609.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":17955,"question":"سماحة الشيخ! هذه سائلة تقول: عندما كنت صغيرة وحتى كبرت كنت أعيش تحت رعاية أبي ولم أكن أصلي ولم أكن أصوم وذلك جهلًا مني، وعندما تزوجت هذه المرأة تقول: ومن ذلك الوقت وأنا أصوم وأصلي والحمد لله، ماذا يجب علي أن أفعل في الصلاة والصيام السابق أيام شبابي مع العلم بأنني تبت إلى الله وندمت على هذا العمل؟","title":"حكم من كان لا يصلي ولا يصوم ثم تاب","answer":"الجواب: التوبة كافية، إنسان ما يصلي ولا يصوم ثم تاب التوبة كافية وليس عليه قضاء، الحمد لله، يقول جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ[الأنفال:38]، ويقول النبي ﷺ: التوبة تجب ما قبلها فالكافر إذا أسلم وتاب تاب الله عليه، ولم يلزمه قضاء ما مضى، وهكذا الذي لا يصلي إذا تاب تاب الله عليه، ولا يلزمه القضاء، لا صوم، ولا صلاة، ولا غير ذلك، التوبة تجب ما قبلها نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16977/حكم-من-كان-لا-يصلي-ولا-يصوم-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78017.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":18178,"question":"كنت من قبل لا أواظب على الصلاة والصوم، ثم تبت إلى الله والحمد لله، وقد سمعت في برنامجكم أن الصلاة لا تقضى، فهل الصوم كذلك، أم أن الصوم يجب قضاؤه؟ علمًا بأنني لا أعلم كم صمت وكم أفطرت.","title":"حكم قضاء الصلاة والصوم لمن تاب من تركهما","answer":"الجواب: أما الصلاة فمن تركها عمدًا لا يقضي بل عليه التوبة إلى الله ؛ لأن تركها ردة عن الإسلام والمرتد لا يقضي ما ترك، فعليه أن يتوب إلى الله، وأن يبادر بالصلاة، ويسأل الله العفو عما مضى. أما إذا كان المؤمن يصلي والمؤمنة تصلي ولكن تتساهل في بعض الصيام فإنه يقضي؛ لأن ترك الصيام ليس بردة عن الإسلام، ولكنه معصية كبيرة؛ فإذا تركت المرأة قضاء الصوم أو الرجل قضاء الصوم؛ فإنه يلزمه التوبة إلى الله مع قضاء الصوم، وعليه مع ذلك إطعام مسكين عن كل يوم إذا تأخر القضاء عن رمضان الذي يلي رمضان الذي تركه منه؛ فإنه يقضي ويطعم مسكين عن كل يوم نصف صاع من قوت البلد مقداره كيلو ونص تقريبًا من جهة الوزن مع الصوم ومع التوبة إلى الله  وقد أفتى بالطعام جماعة من أصحاب النبي ﷺ كفارة وتعزيرًا للمتخلف في قضاء صومه. نعم.","link":"https://binbaz.org.sa/fatwas/17223/حكم-قضاء-الصلاة-والصوم-لمن-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":18190,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية، وباعثها أحد الإخوة من هناك يقول الاسم الشافعي، أخونا يقول في سؤال له: والدتي تبلغ من العمر سبعين عامًا تقريبًا والحمد لله على كل حال ابتلاها الله بمرض مزمن اضطرت معه إلى الإفطار في رمضان من كل عام، ولا ندري بالضبط تاريخ الإصابة بالمرض، وللأسف لم تفد بإطعام مسكين عن الأيام التي أفطرتها لسببين:الأول: ليس عندها الوعي الديني الكافي بهذا الخصوص.والسبب الثاني: لا يوجد في القرية مساكين يستحقون الفدية.والآن وقد هداني الله وأرشدني إلى الصواب أريد أن أخرج فدية للمساكين عن الشهور التي أفطرتها في السنوات الماضية، لكن لا أعلم عددها بالتحديد، وهي كذلك لا تعلم، وكذلك لا أعلم مقدار الفدية الواجب إخراجها عن هذه الشهور التي مضت، فما رأي سماحتكم في هذا الأمر؟وإذا كانت لي أخت متزوجة وعندها أولاد صغار وهي فقيرة، فهل يفضل أن أعطيها قيمة هذه الفدية، علمًا بأن زوجها على قيد الحياة؟ أفيدوني في هذه القضايا جزاكم الله خيرًا.","title":"حكم من أفطر عدة رمضانات ولا يعلم مقدار ما أفطر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن كانت الوالدة التي سألت عنها حين إفطارها عاجزة فقيرة لا تملك إخراج الفدية فليس عليها شيء؛ لقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] أما إن كانت قادرة ولكن تركت ذلك من أجل الجهل؛ فإنك تخرج عنها أو تخرج هي بنفسها عن كل يوم نصف صاع من قوت البلد أرز أو حنطة أو غيرهما من قوت البلد، ومقدار ذلك كيلو ونص تقريبًا عن كل يوم تجمع ويعطاها بعض الفقراء ولو في قرية أخرى في غير قريتها، ليس من اللازم أن يكونوا في قريتها، بل ولو في قرية أخرى تنقل إليهم هذه الكفارة، ولا يجوز إخراج نقود بل يعطون طعامًا. وإذا كانت أختك فقيرة وزوجها فقير فلا مانع من دفع هذه الكفارة إلى زوجها يعطاها الزوج؛ لأنه المنفق والمسئول عن الزوجة والأولاد فإذا كان فقيرًا فإنها تدفع إليه، أما إن كان غنيًا فإنه هو الذي يقوم بنفقة الزوجة والأولاد، ولا يعطى النفقة الكفارة المذكورة، بل يلتمس فقراء غير زوج أختك مطلقًا سواءً كانوا في البلد أو في غير البلد. وإذا كنتم لا تعرفون عدد الأشهر فإنكم تكتفون بالظن تجتهد الوالدة وأنت تجتهدان جميعًا في تحري الأيام التي أفطرتها الوالدة في سنتين أو ثلاث أو أربع على حسب الظن الغالب، ثم تخرجون هذه الكفارة بناءً على الظن الغالب الذي منك أو منها أو منكما جميعًا لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]. نعم.","link":"https://binbaz.org.sa/fatwas/17227/حكم-من-افطر-عدة-رمضانات-ولا-يعلم-مقدار-ما-افطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_855/nour_85501.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18261,"question":"ننتقل إلى رسائل أخرى، ومواضيع أخرى عبر هذه الرسائل، فهذه رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها عددًا من الأسئلة، ويبدو أن أخانا نسي أن يكتب اسمه، على أي حال الأسئلة يقول أولها:هل يجوز للحامل أو المرضع الإفطار في رمضان وعليهما الفدية فقط دون القضاء؟","title":"ما الواجب على الحامل والمرضع إذا أفطرتا في رمضان؟","answer":"الجواب: هذه المسألة مسألة خلاف بين أهل العلم، من أهل العلم من قال: إن عليهما الفدية فقط، ولهما أن تفطرا؛ لأن الحمل قد يتتابع، ورمضان قد يتتابع، فلا يكون عندهما فرصة للقضاء، وهذا مروي عن ابن عباس وعن ابن عمر رضي الله عنهما، قاله جماعة من السلف. والقول الثاني: أنهما كالمريض إن شق عليهما الصيام أفطرتا وقضتا، فإن لم يشق عليهما صامتا، وهذا القول هو الأرجح وهو الأقوى دليلًا، وهو الذي جاء فيه الحديث الصحيح عن أنس بن مالك الكعبي ، غير أنس بن مالك الأنصاري أن الرسول  قال: إن الله وضع عن المسافر شطر الصلاة والصوم، وعن الحبلى والمرضع الصوم . فهذا يدل على أنهما كالمسافر، فالمسافر في الصوم، يفطر ويقضي وهما كذلك، والمسافر يختص بالقصر في الصلاة، فوضع الله عنه شطر الصلاة يعني: الرباعية، الظهر والعصر والعشاء، فليس في الدنيا من يقصر الصلاة سوى المسافر، فالمريض لا يقصر، والحبلى والمرضع لا تقصران، وإنما الذي يقصر المسافر يصلي الرباعية ركعتين، الظهر والعصر والعشاء فقط. بعض الناس قد يغلط ويظن أن المريض يقصر وهذا غلط، المريض لا يقصر يصلي أربعًا المريض، فالحبلى والمرضع الصواب فيهما أنهما كالمسافر والمريض تفطران وتقضيان وليس عليهما فدية، هذا هو الأرجح وهذا الصواب وهو الذي نفتي به، وهو الذي فيما يظهر، هو قول الأكثر من أهل العلم؛ لأنهما شبيهتان بالمريض، قد يشق عليهما الصوم من أجل الرضاع ومن أجل الحبل، وقد لا يشق عليهما كالمريض خفيف المرض فتصومان. نعم. المقدم: بارك الله فيكم ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17310/ما-الواجب-على-الحامل-والمرضع-اذا-افطرتا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_909/nour_90902.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":18385,"question":"منذ فترة طويلة، أفطر شخص في نهار رمضان متعمدًا، ولم يقض حتى الآن، مع العلم بأنه مستمر في الغربة هنا في المملكة، ماذا يجب على هذا الشخص؟ وماذا يفعل؟","title":"حكم مغترب أفطر متعمدًا في رمضان","answer":"الجواب: يجب عليه أن يقضي الأيام التي أفطرها مع التوبة إلى الله، ويجب عليه أن يصوم كل ما دخل رمضان مع الناس، يجب عليه الصوم، ويجب عليه قضاء ما أفطر فيه، وعليه التوبة إلى الله مما حصل من الفطر والتأخير، عليه التوبة إلى الله  وعليه قضاء الأيام التي أفطرها، وعليه الصوم كلما دخل رمضان أن يصوم مع الناس، حكمه حكم المقيمين ما دام عزم على الإقامة في البلد للعمل، أو لأسباب أخرى يلزمه أن يصوم مع الناس. أما لو كانت الإقامة محدودة، وهو مسافر، الإقامة محدودة أربعة أيام فأقل؛ فإنه له الفطر ثم يسافر، أما إذا كان لا، الإقامة غير محدودة، الإقامة طويلة، أو عزم على الإقامة الطويلة؛ فهذا يلزمه الصوم، وليس له الفطر إلا إذا كانت الإقامة أربعة أيام فأقل، أو لا يدري متى يسافر، يقول: اليوم أسافر ، غدًا أسافر، ما عنده إقامة معينة، هذا له أن يفطر حتى يعزم على الإقامة، أو يرجع إلى بلده مثل بعض الناس يقدم من بلده لحاجة يدور غريم، يدور سلعة يريد يشتريها، يقول: اليوم أرتحل .. باكر أرتحل، هذا له الفطر حتى يعين إقامة معينة أكثر من أربعة أيام، فإذا عزم على الإقامة أكثر من أربعة أيام وجب عليه الصيام عند جمهور أهل العلم. وأما إذا قدم بنية السفر لكنه يطلب حاجة، إما غريمًا يطلبه، أو سلعة يطلبها، أو ما أشبه ذلك لا يدري هل يقيم يوم أو يومين أو ثلاث هذا له الفطر، وله القصر حتى يعزم على الإقامة، أو يرجع إلى بلده، فإذا عزم على الإقامة أكثر من أربعة أيام وجب عليه الصوم، ووجب عليه القضاء؛ قضاء ما أفطره قبل رمضان القادم .نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17470/حكم-مغترب-افطر-متعمدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78410.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18427,"question":"تسأل أختنا عن صيام قضاء شهر رمضان الذي أفطرته المرأة بسبب النفاس أو الحيض، هل يجوز لها القضاء يومًا بعد يوم؟ وإذا تركته حتى جاء رمضان آخر، فما الحكم؟ جزاكم الله خيرًا.","title":"حكم تتابع القضاء وتأخيره حتى دخول رمضان آخر","answer":"الجواب: الواجب عليها القضاء، ولو غير متتابع ولو مفرقًا، لا بأس؛ لأن الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، وهكذا النفساء والحائض تقضي لكن لا بأس أن تفرق تصوم يومًا وتفطر يومًا لا حرج، ولا يجوز التأخير إلى رمضان، بل يجب البدار حتى يصام قبل رمضان. نعم. المقدم: جزاكم الله خيرًا. ومن أخرت حتى جاء رمضان آخر ثم قضت، ماذا عليها سماحة الشيخ؟ الشيخ: إذا أخرت عليها التوبة وعليها القضاء، وعليها إطعام مسكين عن كل يوم زيادة ثلاثة أمور: عليها التوبة إلى الله والندم، وعليها القضاء، وعليها إطعام مسكين عن كل يوم، إذا كان تأخيرًا بدون عذر إذا كان مع القدرة ما عندها مانع، ما عندها مرض يمنعها ولا عذر، لكن أخرت تساهلًا؛ فعليها القضاء والتوبة وإطعام مسكين عن كل يوم نص صاع عن كل يوم يجمع ويعطاه بعض الفقراء بعدد الأيام ........... نعم. المقدم: جزاكم الله خيرًا. نصف الصاع كم يعادل بالكيلو لو تكرمتم؟ الشيخ: كيلو ونصف. المقدم: كيلو ونصف؟ الشيخ: نعم. المقدم: نعم إذًا تعطي عن كل يوم أخرته لغير عذر كيلو ونصف لأحد المساكين؟ الشيخ: نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17555/حكم-تتابع-القضاء-وتاخيره-حتى-دخول-رمضان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73308.mp3","categories":["قضايا المرأة","قضاء الصيام"]},{"id":18479,"question":"السائل من الدمام مصري ومقيم هناك (م. ع. م) يقول في هذا السؤال الذي فهمت منه يقول: بأن زوجته مريضة بالصرع منذ صغرها، مما يُلزمها باتباع برنامج علاجي صعب يصعب معه الصيام لشهر رمضان المبارك، ولكنها في السنوات القليلة الماضية كانت تصر على الصيام، وبفضل الله كانت تتمكن من صيام معظم أيام الشهر الكريم رغم ما كانت تتعرض له من تعب ونوبات قلبية نتيجة عدم تناولها للعلاج في نهار شهر رمضان المبارك، مع العلم بأنه بعد الانتهاء من الشهر الكريم لا تستطيع صيام ما عليها من أيام أفطرتها خلال شهر رمضان الكريم، أفيدونا مأجورين:هل لها أن تصوم شهر رمضان وهي على هذه الحالة؟ وماذا يجب عليها إزاء عدم صيامها سنوات كثيرة سابقة، وكذلك إزاء الأيام التي عليها من شهر رمضان في السنوات الثلاث الأخيرة؟ جزاكم الله خيرا، سماحة الشيخ.","title":"حكم العاجز عن صيام رمضان بسبب المرض المستمر","answer":"الجواب: عليها أن تصوم إذا استطاعت، هي أعلم بنفسها، إن استطاعت عليها أن تصوم وتقضي ما فاتها من أيام الحيض، وإن لم تستطع للمرض الذي أصابها تطعم عن كل يوم مسكينًا، إذا كان مرضها مستمرًا معها ما فيه حيلة يعني: عرض على الأطباء ولا وجدوا حيلة، فهذا تطعم عن كل يوم مسكينًا، أما إذا استطاعت أن تصوم، ولو بعض الصيام ثم تقضي فإنها تصوم وتقضي ما فاتها، هذا هو الواجب عليها؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، ويقول سبحانه: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ[البقرة:184]. والله جل وعلا كتب علينا الصيام قال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ[البقرة:183]، والنبي ﷺ أخبر أن صيام رمضان من أركان الإسلام الخمسة، فإذا استطاعت فعليها أن تصوم، وإذا أفطرت بعض الأيام تقضيها، وإن كان اشتد معها المرض، ولم تستطع الصوم أفطرت فهي على كل حال تراعي حالها، تصوم إذا استطاعت، وتفطر إذا شق عليها، ثم تقضي. فإن كانت لا تستطيع أبدًا، ويشق عليها مشقة بينة تطعم عن كل يوم مسكينًا إذا كان لا يرجى برؤها، تعرض نفسها على الأطباء الخاصين؛ فإذا كان لا يرجى برؤها من هذا المرض فالحمد لله تطعم عن كل يوم مسكينًا، تجمع الطعام خمسة عشر صاعًا عن الشهر، وتعطيه بعض الفقراء، خمسة عشر صاعًا يعني: خمسة وأربعين كيلو، كل يوم عنه: كيلو ونصف، تعطيه بعض الفقراء، هذا هو الواجب عليها إذا كانت لا تستطيع الصوم بشهادة الأطباء المختصين من أجل مرضها، نسأل الله لنا ولها العافية. المقدم: اللهم آمين، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17577/حكم-العاجز-عن-صيام-رمضان-بسبب-المرض-المستمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78520.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18759,"question":"هذه سائلة تقول: أنجبت ولدين من ضمن أبنائي خلال شهر رمضان المبارك، فأفطرت كوني -تقول-: امرأة نفساء ومرضعة، وبعد مرور اثنين وعشرين عامًا تريد أن تقضي ذلك الدين في هذين الشهرين، فما حكم القضاء؟ وهل يترتب على ذلك كفارة إلى جانب الصيام؟ تذكر بأنها امرأة فقيرة الحال.","title":"حكم القضاء والكفارة على من أخرت الصيام لمدة طويلة","answer":"الجواب: عليها التوبة إلى الله، على المرأة المذكورة التوبة إلى الله سبحانه من هذا التأخير الكثير، وعليها أن تقضي رمضان الذي أفطرت فيه، جميع الأيام التي أفطرتها عليها أن تقضيها، إن كان الولدين في سنة واحدة توأمين عليها أن تقضي الشهر، وإن كان كل واحد في رمضان فعليها أن تقضي الشهرين، إذا كان كل واحد في رمضان في سنة فعليها أن تقضي الشهرين، وإن كانا توأمين خلال شهر واحد فعليها أن تقضي رمضان. وعليها أن تطعم مسكين عن كل يوم إذا كانت تستطيع، وإن كان ما تستطيع فقيرة يكفي الصيام، والحمد لله، مع التوبة إلى الله ، أما إن كانت تستطيع فعليها إطعام مسكين عن كل يوم مع الصيام نصف صاع مع الصيام يجمع خمسة عشر صاع عن رمضان يعطاها بعض الفقراء، وإن كان رمضانين ثلاثين صاع يعطاها بعض الفقراء مع الصيام؛ لأن سؤالها محتمل أنها.......، ويحتمل أنها في سنتين، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17887/حكم-القضاء-والكفارة-على-من-اخرت-الصيام-لمدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79013.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18772,"question":"رجل توفي وعليه صيام من رمضان، وله أبناء رجال ونساء، فهل يجب عليهم القضاء عن أبيهم؟ وهل يكون القضاء عليهم جميعًا، أم على الرجال فقط؟ وهل كلهم يصومون في يوم واحد، أم كل واحد يصوم يومًا واحدًا عنه؟","title":"كيفية قضاء الصوم عمن مات وعليه صوم","answer":"الجواب: يقول النبي ﷺ: من مات وعليه صيام صام عنه وليه إذا مات وعليه قضاء من رمضان، أو صوم نذر شرع لأقربائه أن يصوموا عنه، فإن صام عنه واحد أو جماعة فقد أحسنوا، جزاهم الله خيرًا، إذا صام عنه واحد جميع الأيام، أو صام جماعة: هذا صام ثلاثة وهذا صام أربعة، وهذا صام يومين، فقد أحسنوا، جزاهم الله خيرًا؛ لأنه ﷺ قال: من مات وعليه صيام صام عنه وليه. فالسنة لأقربائه أن يصوموا عنه، فإن كان قضاء رمضان صاموا عنه، وإن كان كفارة متتابعة صاموها متتابعة كشهرين متتابعين يصومها واحد متتابعة منهم يستحب له ذلك، فإن كان يوم واحد صامه عنه بعض أقاربه من رمضان أو نذر. المقصود: أن السنة لأقاربه أن يصوموا عنه ما وجب عليه من الصيام إذا مات ولم يصم، سواءً كان من رمضان، أو من الكفارات، لكن إذا كانت الكفارة متتابعة ككفارة القتل كفارة الظهار صاموها متتابعة يصومها واحد؛ لأن التتابع يكون من واحد يوم بعد يوم متتابعة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17904/كيفية-قضاء-الصوم-عمن-مات-وعليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79110.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18966,"question":"تقول سماحة الشيخ الأخت السائلة: من عليه القضاء وإطعام المساكين أو الفقراء بالنسبة للمفطر في رمضان، فإن أطعم مسبقًا لكل الأيام، ثم بعد الفراغ من الإطعام يصوم عدد الأيام التي عليه، هل هذا صحيح أم لا؟","title":"حكم تقديم الإطعام على الصيام في كفارة قضاء رمضان","answer":"الجواب: لا بأس، قدم الإطعام أو أخره، سواء قدمه أو أخره، إذا كان عليه أيام من رمضان أخرها إلى رمضان آخر تأخرت، يقضي ويطعم عن كل يوم مسكين، سواء قدم الإطعام أو أخره عن كل يوم نصف صاع، يعني: كيلو ونصف عن كل يوم، إذا أخرها إلى بعد رمضان آخر، نعم.","link":"https://binbaz.org.sa/fatwas/18101/حكم-تقديم-الاطعام-على-الصيام-في-كفارة-قضاء-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88224.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19018,"question":"الأخت المستمعة (ش. ع. ح) من جدة بعثت تقول: إلى سماحة الوالد الشيخ عبد العزيز بن عبد الله بن باز حفظه الله ذخرًا للإسلام والمسلمين، أما بعد:السلام عليكم ورحمة الله وبركاته. إنني -يا سماحة الشيخ- حائرة في أمري! والمشكلة هي أن والدتي أخبرتني قريبًا أنها في الماضي لم تقض أيام الحيض والنفاس، وهو عن جهل منها في ذلك، وهي الآن كبيرة في السن، لا تقدر أن تقضي هذه المدة الطويلة، وأيضًا مصابة بالسكر والضغط، وهي الآن في حيرة أيضًا من أمرها، هل الصدقة تجزئ عن ذلك؟ وما هو مقدارها؟ أفتونا جزاكم الله خيرًا.","title":"حكم من أفطرت لعذر ثم كبر سنها ولا تستطيع القضاء","answer":"الجواب: أولًا: عليها التوبة إلى الله  عما فعلت من الترك، والتوبة حقيقتها أمور ثلاثة: هذه التوبة ندم على الماضي، وإقلاع من الذنب، وترك له خوفًا من الله  وتعظيمًا له، وأمر ثالث وهو العزم الصادق ألا يعود في الذنب. فالوالدة التي سألت عنها أيها السائلة جزاك الله خيرًا، عليها أن تتوب إلى الله بالندم على ما مضى، الندم الصادق، وعليها مع ذلك أن تطعم عن كل يوم مسكينًا، ما دامت لا تستطيع القضاء عليها أن تطعم عن كل يوم مسكينًا، إذا كانت تستطيع، إذا كانت عندها قدرة مالية تطعم عن كل يوم مسكينًا نصف صاع، بصاع النبي عليه الصلاة والسلام، ومقداره كيلو ونصف تقريبًا، من قوت البلد: رز، أو تمر، أو حنطة، أو شعير.. ونحو ذلك. هذا هو الواجب عليها مع التوبة والاستغفار عما مضى، والله  يتوب على التائبين، وأنت جزاك الله خيرًا أعينيها على هذا الخير إذا كانت تعجز عن بعض الكفارة، وأنت تقدرين فأعينيها والله في عون العبد ما كان العبد في عون أخيه فكيف بالوالدة. نعم الله المستعان. المقدم: نعم نعم، جزاكم الله خيرًا. تقدم الرز صافي دون أن يكون معه شيء شيخ عبد العزيز . الشيخ: وأيضًا عليها أن تعتني بعدد الأيام ولو بالظن إذا شق العلم ولو بالظن، يكتفى بالظن عند العجز عن العلم في مقدار الأيام، وإذا كان مع الرز أو الحنطة إدام هذا أفضل وأفضل منه لحم أو سمن هذا كله طيب وإلا فهو يكفي وحده، التمر وحده والرز وحده والحنطة وحدها تكفي، لكن إذا كان مع الرز ونحوه إدام صار أفضل. نعم. المقدم: نعم نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18187/حكم-من-افطرت-لعذر-ثم-كبر-سنها-ولا-تستطيع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92705.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19190,"question":"أخونا يقول: مرضت ولم أتمكن من صيام رمضان، فأخرته إلى رمضان من السنة القادمة، هل يجزئ الصوم فقط، أم هناك كفارة وما هي؟","title":"حكم من أفطر في رمضان وأخر القضاء حتى رمضان آخر","answer":"الجواب: إذا كنت أخرته من أجل المرض كفاك القضاء فقط، إذا كان المرض استمر معك إلى رمضان الآخر، فإنه يكفيك القضاء والحمد لله ولا شيء عليك. أما إذا كنت تساهلت وأنت طيب فلم تقض إلا بعد رمضان، فإنك تجمع بين الأمرين، تقضي الأيام التي أفطرتها وتطعم عن كل يوم مسكينًا، نصف صاع بصاع النبي عليه الصلاة والسلام، ومقداره كيلو ونص تقريبًا، من قوت البلد، من تمر، أو أرز، أو حنطة، ونحو ذلك، يعطاها بعض الفقراء، تجمع ويعطاها بعض الفقراء. نعم.","link":"https://binbaz.org.sa/fatwas/18364/حكم-من-افطر-في-رمضان-واخر-القضاء-حتى-رمضان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93212.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19212,"question":"الرسالة التالية من إحدى الأخوات المستمعات تقول المرسلة (ش. س. ف) أختنا لها سؤالان، في سؤالها الأول تقول: منذ خمس سنوات، وفي شهر رمضان المبارك أفطرت أربعة أيام، وليس لي عذر غير التعب، وسؤالي هو: هل يجب علي القضاء؟ وهل علي كفارة؟ وما هي؟ جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان عمدًا بغير عذر شرعي","answer":"الجواب: نعم عليك ثلاثة أمور: الأمر الأول: التوبة إلى الله سبحانه، والندم على ما فعلت من التقصير والإفطار بغير حق؛ فإن كنت أفطرت من أجل الحيض فلا حرج، لكن عليك التوبة إلى الله من أجل التأخير؛ لأنك أخرت القضاء، والواجب أن تقضي قبل رمضان الذي بعد رمضانك الذي أفطرت فيه. فعليك التوبة إلى الله سبحانه من هذا التأخير، أو من الإفطار بغير عذر إن كنت أفطرت بغير عذر، والتوبة لازمة من كل ذنب، وهي الندم على الماضي من الذنب، والإقلاع منه والعزم الصادق أن لا يعود العبد إليه، هذه التوبة. وعليك مع ذلك قضاء الأيام الأربعة؛ لأن الله قال: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] وإذا أفطر غير المريض وغير المسافر فمن باب أولى أن يقضي وعليه التوبة إلى الله. وأمر ثالث: وهو إطعام مسكين عن كل يوم نصف صاع، يعني: كيلو ونصف تقريبًا من التمر أو من الحنطة أو من الرز أو غيرها من قوت البلد، عن كل يوم نصف صاع يعني: صاعين بصاع النبي ﷺ، يعطاها بعض الفقراء ولو فقيرًا واحدًا يكفي، والله جل وعلا المسؤول أن يغفر لنا ولك، وأن يهدينا وإياك وسائر المسلمين. المقدم: جزاكم الله خيرًا ونفع بكم.","link":"https://binbaz.org.sa/fatwas/18387/حكم-من-افطر-في-رمضان-عمدا-بغير-عذر-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93307.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19214,"question":"المستمع محمد أحمد علي حسان، يمني مقيم في الرياض يقول: امرأة أفطرت في رمضان لمدة ثلاث سنوات، وذلك أنها كانت تحمل ويصادف ذلك رمضان، وللجهل بحكم الصيام ولم يكن هناك مرشدين لها، وقد أفتاها بعض المجتهدين بأن عليها الإطعام دون القضاء، نرجو التوجيه في هذه المسألة، جزاكم الله خيرًا.","title":"حكم الحامل والمرضع إذا أفطرتا في رمضان","answer":"الجواب: الصواب الذي دلت عليه الأدلة الشرعية أن عليها القضاء دون الإطعام، والقول بأن عليها الإطعام قول غلط في أصح قولي العلماء، وإنما عليها القضاء دون الإطعام إذا كانت معذورة من أجل الحمل أو الرضاع أو مرض فعليها القضاء فقط. أما إن كانت تساهلت وحصل لها وقت تقضي فيه لكنها تساهلت فعليها مع القضاء إطعام مسكين عن كل يوم نصف صاع بصاع النبي ﷺ وهو يقارب كيلو ونص تقريبًا من قوت البلد من تمر أو أرز أو غير ذلك عن تأخيرها الصيام. وعلى المرأة أن تتقي الله دائمًا في صومها وصلاتها وغير ذلك كالرجل، كل منهما عليه أن يتقي الله وأن يهتم بأمر دينه وأن يجتهد في أداء الحق الذي عليه، فالصوم ركن من أركان الإسلام الخمسة، وهو صوم رمضان. فالواجب على الرجل والمرأة المكلفين العناية بهذا الأمر وعدم التفريط فيه، فإذا أفطر الإنسان لمرض أو سفر أو أفطرت المرأة لحيض أو حمل أو رضاع يشق معه الصيام فإنها تقضي، وتبادر بالقضاء من حين تستطيع، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا. كونها تركت الصيام للجهل ولقلة التوعية الإسلامية في وطنهم كما يذكر. الشيخ: ما يمنع القضاء؛ لأن هذا أمر معروف بين المسلمين، ومن الأمور المشهورة المعروفة التي لا تخفى على أحد، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18389/حكم-الحامل-والمرضع-اذا-افطرتا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93309.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":19390,"question":"تسأل عن معنى حديث عن الرسول ﷺ: من أفطر في رمضان متعمدًا لا يقبل الله منه صوم وإن صام الدهر كله، وإذا أفطر متعمدًا ثم تاب، فهل يقبل الله منه توبته؟","title":"ما صحة حديث: «من أفطر يومًا من رمضان لم يقبل منه»؟","answer":"الجواب: الحديث المذكور ضعيف، والتوبة مقبولة إذا تاب توبة صادقة فإنها تقبل منه التوبة، وعليه قضاء اليوم فقط الذي أفطره، والحديث المذكور: من أفطر يومًا من رمضان لم يقبل منه صيام الدهر وإن صامه، هذا ضعيف مضطرب عند أهل العلم لا يصح، فالمقصود أنه حديث ضعيف. والصواب أن عليه التوبة، ولا يلزمه إلا قضاء اليوم الذي أفطره فقط، هذا هو الصواب، وعليه التوبة، والتوبة تكفي في هذا والحمد لله، التوبة تكفي حتى من الشرك الأكبر، كيف بالمعصية. فالمقصود أن التوبة تجب ما قبلها كما قاله النبي عليه الصلاة والسلام والتائب من الذنب كمن لا ذنب له، قاله النبي أيضًا عليه الصلاة والسلام، فإذا تاب توبة صادقة مضمونها الندم على ما مضى منه، والعزم ألا يعود في ذلك، والإقلاع من هذا العمل السيئ؛ فإنها توبة صحيحة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18611/ما-صحة-حديث-من-افطر-يوما-من-رمضان-لم-يقبل-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74005.mp3","categories":["قضاء الصيام"]},{"id":19441,"question":"يقول عن نفسه: كنت لا أصلي ولكن الآن والحمد لله أنا محافظ على الصلاة وعندما كان أهلي يحثوني على الصلاة كنت أقول لهم حسب ما يصف نفسه (إنه كافر) ولكن ندمت عليها بعد أن هداني الله، فهل لي توبة؟ أفيدوني أفادكم الله.","title":"من وَصْف نفسه بالكفر هل له توبة؟","answer":"الجواب: نعم كل ذنب له توبة حتى الشرك الأكبر، فعليك التوبة إلى الله  والندم على ما مضى منك والعزم الصادق ألا تعود والله يتوب على من تاب سبحانه، والحمد لله الذي من عليك بالتوبة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18675/من-وصف-نفسه-بالكفر-هل-له-توبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93804.mp3","categories":["حكم الصلاة وأهميتها","قضاء الصيام","الرقائق"]},{"id":19486,"question":"أريد أن أصوم الأيام التي فاتتني عندما بلغت، ولكن لا أعرف كم عدد أيامها لأنني بلغت وأنا في الثانية عشرة من العمر، وكنت أصوم وأفطر لما ألقاه من تعب، وعندما بلغت الرابعة عشرة من العمر أتممت الصيام، كما قلت: لا أعرف عدد تلك الأيام التي أفطرتها وجهوني، جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان ولا يعرف عدد الأيام التي أفطره","answer":"الجواب: عليك أن تحسبي الأيام بالظن، والاجتهاد والتحري، فإذا غلب على ظنك أنها عشرة أيام، خمسة عشر يومًا صمتيها، تصومين ما تيسر من ذلك حسب الطاقة، حسب الظن الغالب لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286] عليك أن تجتهدي وتتحري الأيام التي أفطرتيها بعد البلوغ، وعليك أن تصوميها سواء كانت متتابعة أو مفرقة، وعليك مع ذلك إطعام مسكين عن كل يوم لتأخر صيامك لها، وهو نصف صاع من التمر أو الأرز ونحوهما إذا كنت قادرة على ذلك. أما إذا كنت فقيرة لا تستطيعين فإنه يكفي الصوم، ولا حاجة إلى الإطعام لقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18737/حكم-من-افطر-في-رمضان-ولا-يعرف-عدد-الايام-التي-افطره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94507.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19499,"question":"هذا السائل ضيف الله القصيم الرس، يقول: سماحة الشيخ لدي أخ أصيب بمرض وهو فشل كلوي، وقد أفطر يومين من العام الماضي، وشد عليه المرض في رمضان الحالي، وبقي في المستشفى خمسة عشر يومًا من رمضان، ونصحه الأطباء بعدم الصوم حفاظًا على صحته، ولم يصم الشهر كله، و هل عليه قضاء أم صدقة؟ وما هو معيار الصدقة هل هو صاع أم نصف صاع لليوم الواحد نرجو توضيح ذلك مأجورين؟","title":"حكم من أفطر في رمضان لمرض","answer":"الجواب: ما دام يرجو العافية فعليه الصوم عليه القضاء، قضاء الفائت من رمضان السابق، وقضاء رمضان الحالي، فإذا قرر الأطباء المختصون أنه مأيوس من شفائه وعود الصحة إليه فإنه يطعم عن كل يوم مسكين نصف صاع، عن كل يوم مسكين نصف صاع، كيلو ونص من قوت البلد من تمر، أو شعير، أو حنطة، أو أرز لكل واحد يعني: خمسة عشر صاعاً للشهر كله عن كل يوم نصف الصاع، ولو لمسكين واحد، أو مسكينين، أو ثلاثة، نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18753/حكم-من-افطر-في-رمضان-لمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94604.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19518,"question":"في آخر أسئلة هذه السائلة أم عايض من الخرج تقول: عندما كانت صغيرة فاتها أعوام لم تصم فيها، تقول: بأن أهلي لم يوجهوني على الصيام والصلاة، ولم أعرف أمور ديني، والآن أنا عمري ثمانية وعشرين سنة، وماذا يلزمني من كفارة وصيام؟","title":"حكم قضاء الصوم لمن تركت جاهلة","answer":"الجواب: إذا كانت لا تصلي عليها التوبة، التوبة مما تركت من الصلاة والصوم ويكفي.\nأما إن كانت تصلي ولكن تركت الصيام فعليها القضاء عما مضى.\nأما إذا كانت لا تصلي جاهلة تركت الصوم والصلاة لعدم التعليم فعليها التوبة ويكفي، والحمد لله. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18767/حكم-قضاء-الصوم-لمن-تركت-جاهلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93933.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19624,"question":"هذه رسالة -سماحة الشيخ- وصلت من مستمع للبرنامج لم يذكر أختكم في الله السائلة، أختكم في الله (هـ. ع. ش) فلسطين تقول: سماحة الشيخ أمي أفطرت عدة رمضانات من حوالي ثمانية وعشرين سنة لعذر شرعي، ولم تصم لجهلها، وهي الآن كبيرة في السن، ولا تستطيع أن تصوم، فماذا عليها؟","title":"حكم من أفطر ولم يقض حتى كبر ولا يستطيع الصوم","answer":"الجواب: عليها الإطعام عن كل يوم مسكينًا، نصف صاع من قوت البلد من الرز، أو تمر، أو بر عن كل يوم، كل شهر خمسة عشر صاع، كل شهر رمضان من السنوات الماضية التي ما صامتها خمسة عشر صاع، لكل مسكين نصف صاع ولو مسكينًا واحدًا، لو جمعتها، وأعطتها مسكينًا واحدًا أجزأ؛ والحمد لله، مع التوبة والاستغفار. نعم.","link":"https://binbaz.org.sa/fatwas/18891/حكم-من-افطر-ولم-يقض-حتى-كبر-ولا-يستطيع-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94822.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]}]
